INSERT INTO "fornecedores" VALUES(27,'servico','Máquinas, estrutura e manutenção','Mecânico de máquinas agrícolas','Rodrigues Mecânica Agrícola','empresa','Rodrigues Mecânica Agrícola é uma empresa sediada em Carangola/MG, na região Matas de Minas, no mercado há 26 anos. Segmento: Mecânico de máquinas agrícolas. Faz manutenção de tratores e implementos com atendimento na propriedade. Atende emergências durante a safra. Especialidades: sistema hidráulico, colhedoras, tratores. Atende produtores em Carangola, Simonésia, Caratinga, num raio de até 30 km. Preço médio: R$ 176,00 por hora. Avaliação média 3,9 de 5 (223 avaliações). Disponibilidade: sob agendamento.','sistema hidráulico, colhedoras, tratores',3.9,223,176.0,'hora','Carangola','MG','Matas de Minas','local','Carangola, Simonésia, Caratinga',30,26,NULL,'sob agendamento','(33) 99808-3484',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(28,'produto','EPI e ferramentas','Ferramentas manuais','Mesquita Ferramentas','empresa','Mesquita Ferramentas é uma empresa sediada em Simonésia/MG, na região Matas de Minas, no mercado há 24 anos. Segmento: Ferramentas manuais. Atende produtores e turmas de trabalho. Tem motosserras e peças. Especialidades: foice, tesoura de poda, motosserra. Atende produtores em Simonésia, Manhuaçu, num raio de até 30 km. Preço médio: R$ 179,00 por unidade. Avaliação média 4,7 de 5 (255 avaliações). Disponibilidade: pronta entrega.','foice, tesoura de poda, motosserra',4.7,255,179.0,'unidade','Simonésia','MG','Matas de Minas','local','Simonésia, Manhuaçu',30,24,NULL,'pronta entrega','(33) 98118-1162',1,'2026-09-24 20:42:33');
