INSERT INTO "fornecedores" VALUES(32,'produto','Pós-colheita e beneficiamento (equipamentos)','Secadores de café','Catuaí Secadores','empresa','Catuaí Secadores é uma empresa sediada em Ibaiti/PR, na região Norte Pioneiro do Paraná, no mercado há 33 anos. Segmento: Secadores de café. Fabrica e instala secadores rotativos e de leito fixo. Oferece assistência técnica e peças. Faz orçamento rápido pela plataforma. Especialidades: secador vertical, instalação, fornalha. Atende e envia para todo o Brasil. Preço médio: R$ 95.000,00 por unidade. Avaliação média 4,2 de 5 (199 avaliações). Disponibilidade: pronta entrega.','secador vertical, instalação, fornalha',4.2,199,95000.0,'unidade','Ibaiti','PR','Norte Pioneiro do Paraná','nacional','Todo o Brasil',NULL,33,NULL,'pronta entrega','(43) 99313-9388',1,'2026-09-24 20:42:33');
