INSERT INTO "fornecedores" VALUES(39,'produto','Tecnologia e comercialização','Equipamentos de classificação e prova','Barbosa Laboratório de Café','empresa','Barbosa Laboratório de Café é uma empresa sediada em Lajinha/MG, na região Matas de Minas, no mercado há 27 anos. Segmento: Equipamentos de classificação e prova. Monta salas de prova para fazendas e cooperativas. Vende peneiras, mesas de prova e mini torradores para amostra. Trabalha com marcas reconhecidas e garantia de fábrica. Especialidades: mesa de prova, peneiras de classificação, kit de classificação, mini torrador. Atende e envia para todo o Brasil. Preço médio: R$ 12.000,00 por unidade. Avaliação média 4,5 de 5 (25 avaliações). Disponibilidade: estoque limitado.','mesa de prova, peneiras de classificação, kit de classificação, mini torrador',4.5,25,12000.0,'unidade','Lajinha','MG','Matas de Minas','nacional','Todo o Brasil',NULL,27,NULL,'estoque limitado','(33) 98466-9463',1,'2026-09-24 20:42:33');
