INSERT INTO "fornecedores" VALUES(202,'produto','Tecnologia e comercialização','Software de gestão rural','FazendaCafezal App','empresa','FazendaCafezal App é uma empresa sediada em Nova Venécia/ES, na região Norte do Espírito Santo, no mercado há 33 anos. Segmento: Software de gestão rural. Gera relatórios de custo por saca. Tem aplicativo para registro de atividades no campo. Atende de pequenos produtores a grandes fazendas. Dá desconto em compras de volume e para cooperados. Tem experiência com café conilon/robusta. Especialidades: gestão financeira, rastreabilidade, controle de safra. Atende e envia para todo o Brasil. Preço médio: R$ 275,00 por mês. Avaliação média 3,6 de 5 (67 avaliações). Disponibilidade: pronta entrega.','gestão financeira, rastreabilidade, controle de safra',3.6,67,275.0,'mês','Nova Venécia','ES','Norte do Espírito Santo','nacional','Todo o Brasil',NULL,33,NULL,'pronta entrega','(27) 99017-5294',1,'2026-09-24 20:42:33');
