INSERT INTO "fornecedores" VALUES(226,'produto','Colheita e armazenagem (materiais)','Embalagens herméticas para café','Terra Boa Embalagens','empresa','Terra Boa Embalagens é uma empresa sediada em Itumirim/MG, na região Campo das Vertentes, no mercado há 23 anos. Segmento: Embalagens herméticas para café. Atende produtores que exportam microlotes. Envia para todo o Brasil. Oferece condições especiais antes da safra. Atende muitos produtores de cafés especiais da região. Especialidades: sacos herméticos multicamada, preservação de cafés especiais. Atende e envia para todo o Brasil. Preço médio: R$ 39,72 por unidade. Avaliação média 4,2 de 5 (91 avaliações). Disponibilidade: pronta entrega.','sacos herméticos multicamada, preservação de cafés especiais',4.2,91,39.72,'unidade','Itumirim','MG','Campo das Vertentes','nacional','Todo o Brasil',NULL,23,NULL,'pronta entrega','(35) 98812-8746',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(227,'produto','Tecnologia e comercialização','Equipamentos de classificação e prova','Rezende Laboratório de Café','empresa','Rezende Laboratório de Café é uma empresa sediada em Carmo de Minas/MG, na região Sul de Minas, no mercado há 11 anos. Segmento: Equipamentos de classificação e prova. Vende peneiras, mesas de prova e mini torradores para amostra. Monta salas de prova para fazendas e cooperativas. Faz orçamento rápido pela plataforma. Especialidades: moedor de prova, kit de classificação, mesa de prova. Atende e envia para todo o Brasil. Preço médio: R$ 4.230,00 por unidade. Avaliação média 4,0 de 5 (89 avaliações). Disponibilidade: pronta entrega.','moedor de prova, kit de classificação, mesa de prova',4.0,89,4230.0,'unidade','Carmo de Minas','MG','Sul de Minas','nacional','Todo o Brasil',NULL,11,NULL,'pronta entrega','(35) 98149-6514',1,'2026-09-24 20:42:33');
