INSERT INTO "fornecedores" VALUES(326,'produto','Máquinas e implementos','Implementos agrícolas','Boa Colheita Implementos','empresa','Boa Colheita Implementos é uma empresa sediada em Ituaçu/BA, na região Chapada Diamantina, no mercado há 39 anos. Segmento: Implementos agrícolas. Tem implementos para o recolhimento e a esparramação de palha. Vende roçadeiras, adubadeiras e trinchas para lavouras de café. Faz orçamento rápido pela plataforma. Atende de pequenos produtores a grandes fazendas. Especialidades: adubadeira, recolhedora, roçadeira tratorizada, carretas. Atende toda a região Chapada Diamantina (Piatã, Mucugê, Ibicoara, Barra da Estiva, Abaíra, Ituaçu), num raio de até 200 km da sede. Preço médio: R$ 21.000,00 por unidade. Avaliação média 2,5 de 5 (273 avaliações). Disponibilidade: sob encomenda.','adubadeira, recolhedora, roçadeira tratorizada, carretas',2.5,273,21000.0,'unidade','Ituaçu','BA','Chapada Diamantina','regional','Piatã, Mucugê, Ibicoara, Barra da Estiva, Abaíra, Ituaçu',200,39,NULL,'sob encomenda','(75) 98998-1016',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(327,'servico','Máquinas, estrutura e manutenção','Soldador e serralheiro rural','Patrícia Gomes Pimenta','pessoa_fisica','Patrícia Gomes Pimenta atua como soldador e serralheiro em São Desidério/BA, na região Oeste da Bahia, com 22 anos de experiência. Faz soldas em implementos e reforma de carretas. Fabrica estruturas metálicas para galpões e terreiros suspensos. Agenda as visitas com antecedência e cumpre os prazos combinados. Especialidades: solda de implementos, portões e cercas. Atende produtores em São Desidério, Luís Eduardo Magalhães, Barreiras, num raio de até 60 km. Preço médio: R$ 76,00 por hora. Avaliação média 4,5 de 5 (9 avaliações). Disponibilidade: imediata.','solda de implementos, portões e cercas',4.5,9,76.0,'hora','São Desidério','BA','Oeste da Bahia','local','São Desidério, Luís Eduardo Magalhães, Barreiras',60,22,NULL,'imediata','(77) 98046-7468',1,'2026-09-24 20:42:33');
