INSERT INTO "fornecedores" VALUES(346,'produto','Máquinas e implementos','Máquinas agrícolas usadas','Bourbon Seminovos Agrícolas','empresa','Bourbon Seminovos Agrícolas é uma empresa sediada em Abaíra/BA, na região Chapada Diamantina, no mercado há 8 anos. Segmento: Máquinas agrícolas usadas. Vende tratores, colhedoras e implementos usados revisados. Aceita troca e trabalha com consignação. Parcela no cartão ou aceita pagamento na safra. Oferece condições especiais antes da safra. Especialidades: tratores usados, colhedoras usadas, troca e consignação. Atende toda a região Chapada Diamantina (Piatã, Mucugê, Ibicoara, Barra da Estiva, Abaíra, Ituaçu), num raio de até 150 km da sede. Preço médio: R$ 48.000,00 por unidade. Avaliação média 4,9 de 5 (143 avaliações). Disponibilidade: sob encomenda.','tratores usados, colhedoras usadas, troca e consignação',4.9,143,48000.0,'unidade','Abaíra','BA','Chapada Diamantina','regional','Piatã, Mucugê, Ibicoara, Barra da Estiva, Abaíra, Ituaçu',150,8,NULL,'sob encomenda','(75) 99947-8340',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(347,'produto','Mudas e sementes','Viveiro de mudas de café','Mateus Rocha','pessoa_fisica','Mateus Rocha atua como viveirista de mudas de café em Lavras/MG, na região Campo das Vertentes, com 34 anos de experiência. Trabalha com cultivares resistentes à ferrugem. Faz mudas por encomenda com prazo de produção combinado. Especialidades: Topázio, Catuaí Amarelo, conilon clonal. Atende toda a região Campo das Vertentes (Lavras, Perdões, Bom Sucesso, Ijaci, Santo Antônio do Amparo, Itumirim, Ingaí), num raio de até 150 km da sede. Preço médio: R$ 1,22 por muda. Avaliação média 4,5 de 5 (23 avaliações). Disponibilidade: sob encomenda.','Topázio, Catuaí Amarelo, conilon clonal',4.5,23,1.22,'muda','Lavras','MG','Campo das Vertentes','regional','Lavras, Perdões, Bom Sucesso, Ijaci, Santo Antônio do Amparo, Itumirim, Ingaí',150,34,NULL,'sob encomenda','(35) 98672-5402',1,'2026-09-24 20:42:33');
