INSERT INTO "fornecedores" VALUES(349,'servico','Máquinas, estrutura e manutenção','Eletricista rural','Gustavo Barbosa Brandão','pessoa_fisica','Gustavo Barbosa Brandão atua como eletricista rural em Itumirim/MG, na região Campo das Vertentes, com 24 anos de experiência. Monta quadros de comando para motores. Faz manutenção preventiva antes da safra. Especialidades: bombas de irrigação, instalação de secadores, rede trifásica, quadros de comando. Atende produtores em Itumirim, Ingaí, Bom Sucesso, Ijaci, num raio de até 40 km. Preço médio: R$ 128,00 por hora. Avaliação média 4,2 de 5 (27 avaliações). Disponibilidade: imediata. Certificações/registros: NR-10.','bombas de irrigação, instalação de secadores, rede trifásica, quadros de comando',4.2,27,128.0,'hora','Itumirim','MG','Campo das Vertentes','local','Itumirim, Ingaí, Bom Sucesso, Ijaci',40,24,'NR-10','imediata','(35) 99937-7122',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(350,'produto','Máquinas e implementos','Máquinas agrícolas usadas','Silva Máquinas Usadas','empresa','Silva Máquinas Usadas é uma empresa sediada em Rio Bananal/ES, na região Norte do Espírito Santo, no mercado há 23 anos. Segmento: Máquinas agrícolas usadas. Faz a vistoria da máquina antes da venda. Vende tratores, colhedoras e implementos usados revisados. Atende de pequenos produtores a grandes fazendas. Tem assistência técnica e pós-venda. Tem experiência com café conilon/robusta. Especialidades: troca e consignação, tratores usados. Atende toda a região Norte do Espírito Santo (Linhares, São Gabriel da Palha, Nova Venécia, Jaguaré, Vila Valério, Sooretama, Rio Bananal, Águia Branca), num raio de até 120 km da sede. Preço médio: R$ 121.000,00 por unidade. Avaliação média 4,8 de 5 (114 avaliações). Disponibilidade: pronta entrega.','troca e consignação, tratores usados',4.8,114,121000.0,'unidade','Rio Bananal','ES','Norte do Espírito Santo','regional','Linhares, São Gabriel da Palha, Nova Venécia, Jaguaré, Vila Valério, Sooretama, Rio Bananal, Águia Branca',120,23,NULL,'pronta entrega','(27) 98424-7028',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(351,'produto','Insumos agrícolas','Revenda de defensivos agrícolas','AgroCenter Cafeicultor','empresa','AgroCenter Cafeicultor é uma empresa sediada em Muniz Freire/ES, na região Montanhas do Espírito Santo, no mercado há 2 anos. Segmento: Revenda de defensivos agrícolas. Recebe embalagens vazias para devolução. Emite receituário agronômico na hora da compra. Tem assistência técnica e pós-venda. Trabalha com marcas reconhecidas e garantia de fábrica. Especialidades: acaricidas, fungicidas. Atende toda a região Montanhas do Espírito Santo (Venda Nova do Imigrante, Brejetuba, Iúna, Domingos Martins, Castelo, Afonso Cláudio, Conceição do Castelo, Ibatiba, Irupi, Muniz Freire), num raio de até 80 km da sede. Preço médio: R$ 357,00 por litro (média do portfólio). Avaliação média 4,5 de 5 (167 avaliações). Disponibilidade: sob encomenda. Certificações/registros: Revenda registrada no IMA/órgão estadual.','acaricidas, fungicidas',4.5,167,357.0,'litro (média do portfólio)','Muniz Freire','ES','Montanhas do Espírito Santo','regional','Venda Nova do Imigrante, Brejetuba, Iúna, Domingos Martins, Castelo, Afonso Cláudio, Conceição do Castelo, Ibatiba, Irupi, Muniz Freire',80,2,'Revenda registrada no IMA/órgão estadual','sob encomenda','(28) 99799-7199',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(352,'servico','Planejamento e implantação da lavoura','Engenheiro agrônomo','Arábica Agronomia','empresa','Arábica Agronomia é uma empresa sediada em Boa Esperança/MG, na região Sul de Minas, no mercado há 45 anos. Segmento: Engenheiro agrônomo. Orienta a escolha de cultivares, espaçamento e densidade de plantio. Acompanha a lavoura com visitas periódicas e emite receituário agronômico. Atende pequenos, médios e grandes produtores. Especialidades: recomendação de adubação, nutrição do cafeeiro, cafés especiais. Atende toda a região Sul de Minas (Varginha, Três Pontas, Guaxupé, Machado, Alfenas, Boa Esperança, Campos Gerais, Carmo de Minas, São Sebastião do Paraíso, Nepomuceno, Poços de Caldas, Nova Resende, Muzambinho, Cabo Verde, Monte Santo de Minas, Três Corações, Elói Mendes, Paraguaçu, Carmo do Rio Claro, Ilicínea, Santana da Vargem, Coqueiral, Cambuquira), num raio de até 150 km da sede. Preço médio: R$ 832,00 por visita técnica. Avaliação média 4,0 de 5 (212 avaliações). Disponibilidade: sob agendamento. Certificações/registros: Credenciado ATER.','recomendação de adubação, nutrição do cafeeiro, cafés especiais',4.0,212,832.0,'visita técnica','Boa Esperança','MG','Sul de Minas','regional','Varginha, Três Pontas, Guaxupé, Machado, Alfenas, Boa Esperança, Campos Gerais, Carmo de Minas, São Sebastião do Paraíso, Nepomuceno, Poços de Caldas, Nova Resende, Muzambinho, Cabo Verde, Monte Santo de Minas, Três Corações, Elói Mendes, Paraguaçu, Carmo do Rio Claro, Ilicínea, Santana da Vargem, Coqueiral, Cambuquira',150,45,'Credenciado ATER','sob agendamento','(35) 98292-5339',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(353,'servico','Gestão, certificação e serviços de apoio','Engenheiro ambiental','Aparecida Oliveira Castro','pessoa_fisica','Aparecida Oliveira Castro atua como engenheiro ambiental em Conceição do Castelo/ES, na região Montanhas do Espírito Santo, com 6 anos de experiência. Faz CAR, outorga de uso de água e licenciamento ambiental. Elabora planos de recuperação de áreas degradadas. Prioriza atendimento a propriedades familiares. Segue as boas práticas exigidas por certificadoras. Especialidades: PRAD, reserva legal. Atende toda a região Montanhas do Espírito Santo (Venda Nova do Imigrante, Brejetuba, Iúna, Domingos Martins, Castelo, Afonso Cláudio, Conceição do Castelo, Ibatiba, Irupi, Muniz Freire), num raio de até 200 km da sede. Preço médio: R$ 5.130,00 por projeto. Avaliação média 4,4 de 5 (5 avaliações). Disponibilidade: imediata.','PRAD, reserva legal',4.4,5,5130.0,'projeto','Conceição do Castelo','ES','Montanhas do Espírito Santo','regional','Venda Nova do Imigrante, Brejetuba, Iúna, Domingos Martins, Castelo, Afonso Cláudio, Conceição do Castelo, Ibatiba, Irupi, Muniz Freire',200,6,NULL,'imediata','(28) 99006-3042',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(354,'servico','Manejo e tratos culturais','Piloto de drone agrícola','Luiz Nascimento','pessoa_fisica','Luiz Nascimento atua como piloto de drone agrícola em Ibiá/MG, na região Cerrado Mineiro, com 31 anos de experiência. Realiza aplicações rápidas com baixo volume de calda. Gera mapas de vigor (NDVI) para identificar falhas e reboleiras de pragas. Emite nota fiscal e formaliza o serviço em contrato. Especialidades: mapeamento aéreo, pulverização com drone, NDVI, contagem de plantas. Atende toda a região Cerrado Mineiro (Patrocínio, Araguari, Monte Carmelo, Patos de Minas, Carmo do Paranaíba, Serra do Salitre, Campos Altos, Coromandel, Rio Paranaíba, Ibiá, Perdizes, Estrela do Sul, São Gotardo), num raio de até 200 km da sede. Preço médio: R$ 88,00 por hectare. Avaliação média 4,9 de 5 (39 avaliações). Disponibilidade: imediata. Certificações/registros: Registro no MAPA, Cadastro ANAC/DECEA, Curso CAAR.','mapeamento aéreo, pulverização com drone, NDVI, contagem de plantas',4.9,39,88.0,'hectare','Ibiá','MG','Cerrado Mineiro','regional','Patrocínio, Araguari, Monte Carmelo, Patos de Minas, Carmo do Paranaíba, Serra do Salitre, Campos Altos, Coromandel, Rio Paranaíba, Ibiá, Perdizes, Estrela do Sul, São Gotardo',200,31,'Registro no MAPA, Cadastro ANAC/DECEA, Curso CAAR','imediata','(34) 98274-5170',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(355,'produto','Máquinas e implementos','Revenda de pulverizadores','Santa Clara Pulverizadores','empresa','Santa Clara Pulverizadores é uma empresa sediada em São Gabriel da Palha/ES, na região Norte do Espírito Santo, no mercado há 44 anos. Segmento: Revenda de pulverizadores. Tem bicos e peças de reposição. Faz calibração e regulagem na entrega. Tem experiência com café conilon/robusta. Especialidades: turbo-atomizador, bicos e peças, pulverizador de barra. Atende toda a região Norte do Espírito Santo (Linhares, São Gabriel da Palha, Nova Venécia, Jaguaré, Vila Valério, Sooretama, Rio Bananal, Águia Branca), num raio de até 200 km da sede. Preço médio: R$ 73.000,00 por unidade. Avaliação média 4,1 de 5 (228 avaliações). Disponibilidade: pronta entrega.','turbo-atomizador, bicos e peças, pulverizador de barra',4.1,228,73000.0,'unidade','São Gabriel da Palha','ES','Norte do Espírito Santo','regional','Linhares, São Gabriel da Palha, Nova Venécia, Jaguaré, Vila Valério, Sooretama, Rio Bananal, Águia Branca',200,44,NULL,'pronta entrega','(27) 99775-2610',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(356,'servico','Qualidade e comercialização','Corretor de café','Tatiane Vilela Brandão','pessoa_fisica','Tatiane Vilela Brandão atua como corretor de café em Afonso Cláudio/ES, na região Montanhas do Espírito Santo, com 19 anos de experiência. Acompanha o mercado e orienta o melhor momento de venda. Faz a intermediação entre produtor e compradores, exportadores e torrefações. Atende muitos produtores de cafés especiais da região. Especialidades: contratos futuros, exportação. Atende toda a região Montanhas do Espírito Santo (Venda Nova do Imigrante, Brejetuba, Iúna, Domingos Martins, Castelo, Afonso Cláudio, Conceição do Castelo, Ibatiba, Irupi, Muniz Freire), num raio de até 100 km da sede. Cobra em média 1,15% (% do valor negociado). Avaliação média 4,5 de 5 (13 avaliações). Disponibilidade: imediata.','contratos futuros, exportação',4.5,13,1.15,'% do valor negociado','Afonso Cláudio','ES','Montanhas do Espírito Santo','regional','Venda Nova do Imigrante, Brejetuba, Iúna, Domingos Martins, Castelo, Afonso Cláudio, Conceição do Castelo, Ibatiba, Irupi, Muniz Freire',100,19,NULL,'imediata','(28) 98704-1989',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(357,'servico','Manejo e tratos culturais','Equipe de poda','Diego Tavares Carvalho','pessoa_fisica','Diego Tavares Carvalho atua como podador de café em Japira/PR, na região Norte Pioneiro do Paraná, com 23 anos de experiência. Faz desbrota manual nas lavouras podadas. Trabalha com equipe própria e motosserras e ferramentas de poda. Especialidades: poda programada de ciclo, poda com motosserra, desbrota. Atende produtores em Japira, Joaquim Távora, Ribeirão Claro, num raio de até 60 km. Preço médio: R$ 1.210,00 por hectare. Avaliação média 4,9 de 5 (24 avaliações). Disponibilidade: sob agendamento. Certificações/registros: Curso de operação de motosserra NR-12.','poda programada de ciclo, poda com motosserra, desbrota',4.9,24,1210.0,'hectare','Japira','PR','Norte Pioneiro do Paraná','local','Japira, Joaquim Távora, Ribeirão Claro',60,23,'Curso de operação de motosserra NR-12','sob agendamento','(43) 99254-7631',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(358,'produto','Mudas e sementes','Viveiro de mudas de café','Patrícia Castro','pessoa_fisica','Patrícia Castro atua como viveirista de mudas de café em Lavras/MG, na região Campo das Vertentes, com 4 anos de experiência. Faz mudas por encomenda com prazo de produção combinado. Trabalha com cultivares resistentes à ferrugem. Tem assistência técnica e pós-venda. Emite nota fiscal e entrega na propriedade. Especialidades: Topázio, conilon clonal, mudas enxertadas, Catuaí Amarelo. Atende toda a região Campo das Vertentes (Lavras, Perdões, Bom Sucesso, Ijaci, Santo Antônio do Amparo, Itumirim, Ingaí), num raio de até 120 km da sede. Preço médio: R$ 2,85 por muda. Avaliação média 3,8 de 5 (18 avaliações). Disponibilidade: estoque limitado. Certificações/registros: Registro RENASEM.','Topázio, conilon clonal, mudas enxertadas, Catuaí Amarelo',3.8,18,2.85,'muda','Lavras','MG','Campo das Vertentes','regional','Lavras, Perdões, Bom Sucesso, Ijaci, Santo Antônio do Amparo, Itumirim, Ingaí',120,4,'Registro RENASEM','estoque limitado','(35) 99578-1469',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(359,'servico','Gestão, certificação e serviços de apoio','Contador rural','Souza Contabilidade Rural','empresa','Souza Contabilidade Rural é uma empresa sediada em Cabo Verde/MG, na região Sul de Minas, no mercado há 42 anos. Segmento: Contador rural. Cuida do livro caixa do produtor e da declaração de Imposto de Renda. Orienta a escolha entre pessoa física e jurídica na atividade rural. Especialidades: abertura de CNPJ rural, ITR, folha de pagamento rural, Imposto de Renda rural. Atende toda a região Sul de Minas (Varginha, Três Pontas, Guaxupé, Machado, Alfenas, Boa Esperança, Campos Gerais, Carmo de Minas, São Sebastião do Paraíso, Nepomuceno, Poços de Caldas, Nova Resende, Muzambinho, Cabo Verde, Monte Santo de Minas, Três Corações, Elói Mendes, Paraguaçu, Carmo do Rio Claro, Ilicínea, Santana da Vargem, Coqueiral, Cambuquira), num raio de até 80 km da sede. Preço médio: R$ 667,00 por mês. Avaliação média 4,5 de 5 (380 avaliações). Disponibilidade: imediata. Certificações/registros: CRC ativo.','abertura de CNPJ rural, ITR, folha de pagamento rural, Imposto de Renda rural',4.5,380,667.0,'mês','Cabo Verde','MG','Sul de Minas','regional','Varginha, Três Pontas, Guaxupé, Machado, Alfenas, Boa Esperança, Campos Gerais, Carmo de Minas, São Sebastião do Paraíso, Nepomuceno, Poços de Caldas, Nova Resende, Muzambinho, Cabo Verde, Monte Santo de Minas, Três Corações, Elói Mendes, Paraguaçu, Carmo do Rio Claro, Ilicínea, Santana da Vargem, Coqueiral, Cambuquira',80,42,'CRC ativo','imediata','(35) 99132-5740',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(360,'servico','Pós-colheita e processamento','Serviço de beneficiamento de café','Pereira Beneficiamento de Café','empresa','Pereira Beneficiamento de Café é uma empresa sediada em Mococa/SP, na região Mogiana, no mercado há 3 anos. Segmento: Serviço de beneficiamento de café. Possui catadora eletrônica para retirada de defeitos. Presta serviço de beneficiamento com separação por peneira e densidade. Especialidades: catação eletrônica, padronização de lotes, rebeneficiamento, beneficiamento. Atende toda a região Mogiana (Franca, Pedregulho, Cristais Paulista, Altinópolis, Espírito Santo do Pinhal, Caconde, Ribeirão Corrente, Jeriquara, Patrocínio Paulista, Itirapuã, São Sebastião da Grama, Mococa), num raio de até 120 km da sede. Preço médio: R$ 9,33 por saca de 60 kg. Avaliação média 4,8 de 5 (371 avaliações). Disponibilidade: sob agendamento.','catação eletrônica, padronização de lotes, rebeneficiamento, beneficiamento',4.8,371,9.33,'saca de 60 kg','Mococa','SP','Mogiana','regional','Franca, Pedregulho, Cristais Paulista, Altinópolis, Espírito Santo do Pinhal, Caconde, Ribeirão Corrente, Jeriquara, Patrocínio Paulista, Itirapuã, São Sebastião da Grama, Mococa',120,3,NULL,'sob agendamento','(16) 99783-3156',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(361,'produto','Insumos agrícolas','Revenda de fertilizantes e corretivos','Agro Serra Azul','empresa','Agro Serra Azul é uma empresa sediada em Machado/MG, na região Sul de Minas, no mercado há 14 anos. Segmento: Revenda de fertilizantes e corretivos. Vende adubos formulados para café, calcário e gesso agrícola. Oferece entrega na propriedade e condições de pagamento na safra. Emite nota fiscal e entrega na propriedade. Especialidades: ureia, cloreto de potássio, formulados para café. Atende toda a região Sul de Minas (Varginha, Três Pontas, Guaxupé, Machado, Alfenas, Boa Esperança, Campos Gerais, Carmo de Minas, São Sebastião do Paraíso, Nepomuceno, Poços de Caldas, Nova Resende, Muzambinho, Cabo Verde, Monte Santo de Minas, Três Corações, Elói Mendes, Paraguaçu, Carmo do Rio Claro, Ilicínea, Santana da Vargem, Coqueiral, Cambuquira), num raio de até 200 km da sede. Preço médio: R$ 2.940,00 por tonelada. Avaliação média 3,8 de 5 (365 avaliações). Disponibilidade: sob encomenda.','ureia, cloreto de potássio, formulados para café',3.8,365,2940.0,'tonelada','Machado','MG','Sul de Minas','regional','Varginha, Três Pontas, Guaxupé, Machado, Alfenas, Boa Esperança, Campos Gerais, Carmo de Minas, São Sebastião do Paraíso, Nepomuceno, Poços de Caldas, Nova Resende, Muzambinho, Cabo Verde, Monte Santo de Minas, Três Corações, Elói Mendes, Paraguaçu, Carmo do Rio Claro, Ilicínea, Santana da Vargem, Coqueiral, Cambuquira',200,14,NULL,'sob encomenda','(35) 98114-3481',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(362,'servico','Colheita','Colhedor manual','Luiz Junqueira Andrade','pessoa_fisica','Luiz Junqueira Andrade atua como colhedor de café em Caratinga/MG, na região Matas de Minas, com 8 anos de experiência. Faz catação e varrição do café do chão após a colheita. Tem experiência em colheita em lavouras de montanha. Segue as boas práticas exigidas por certificadoras. Especialidades: colheita seletiva, colheita em montanha. Atende produtores em Caratinga, Lajinha, Espera Feliz, Manhuaçu, num raio de até 50 km. Preço médio: R$ 25,21 por medida de 60 L. Avaliação média 4,9 de 5 (21 avaliações). Disponibilidade: imediata. Certificações/registros: NR-31.','colheita seletiva, colheita em montanha',4.9,21,25.21,'medida de 60 L','Caratinga','MG','Matas de Minas','local','Caratinga, Lajinha, Espera Feliz, Manhuaçu',50,8,'NR-31','imediata','(33) 98848-7022',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(363,'produto','Tecnologia e comercialização','Equipamentos de classificação e prova','Rodrigues Laboratório de Café','empresa','Rodrigues Laboratório de Café é uma empresa sediada em Perdões/MG, na região Campo das Vertentes, no mercado há 19 anos. Segmento: Equipamentos de classificação e prova. Monta salas de prova para fazendas e cooperativas. Vende peneiras, mesas de prova e mini torradores para amostra. Oferece condições especiais antes da safra. Trabalha com marcas reconhecidas e garantia de fábrica. Especialidades: mini torrador, mesa de prova, moedor de prova. Atende e envia para todo o Brasil. Preço médio: R$ 18.000,00 por unidade. Avaliação média 4,3 de 5 (64 avaliações). Disponibilidade: pronta entrega.','mini torrador, mesa de prova, moedor de prova',4.3,64,18000.0,'unidade','Perdões','MG','Campo das Vertentes','nacional','Todo o Brasil',NULL,19,NULL,'pronta entrega','(35) 99253-6094',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(364,'servico','Planejamento e implantação da lavoura','Técnico agrícola','Mariana Tavares Nascimento','pessoa_fisica','Mariana Tavares Nascimento atua como técnico agrícola em lavouras de café em Barreiras/BA, na região Oeste da Bahia, com 24 anos de experiência. Faz o acompanhamento de campo e a coleta de amostras de solo e folha. Ajuda na regulagem de equipamentos de aplicação e calibração de adubadeiras. Emite nota fiscal e formaliza o serviço em contrato. Agenda as visitas com antecedência e cumpre os prazos combinados. Especialidades: monitoramento de pragas, regulagem de pulverizadores, controle de estoque de insumos, coleta de amostras de solo. Atende produtores em Barreiras, São Desidério, Luís Eduardo Magalhães, num raio de até 50 km. Preço médio: R$ 280,00 por visita técnica. Avaliação média 4,6 de 5 (22 avaliações). Disponibilidade: sob agendamento. Certificações/registros: Registro CFTA.','monitoramento de pragas, regulagem de pulverizadores, controle de estoque de insumos, coleta de amostras de solo',4.6,22,280.0,'visita técnica','Barreiras','BA','Oeste da Bahia','local','Barreiras, São Desidério, Luís Eduardo Magalhães',50,24,'Registro CFTA','sob agendamento','(77) 98238-3290',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(365,'servico','Qualidade e comercialização','Torrefação por encomenda','Carvalho Torrefação','empresa','Carvalho Torrefação é uma empresa sediada em Luís Eduardo Magalhães/BA, na região Oeste da Bahia, no mercado há 33 anos. Segmento: Torrefação por encomenda. Desenvolve perfis de torra de acordo com o lote. Oferece moagem, embalagem com válvula e rótulo. Agenda as visitas com antecedência e cumpre os prazos combinados. Tem equipe treinada e equipamentos revisados. Especialidades: marca própria, embalagem com válvula, perfis de torra. Atende e envia para todo o Brasil. Preço médio: R$ 13,90 por kg torrado. Avaliação média 4,5 de 5 (202 avaliações). Disponibilidade: sob agendamento.','marca própria, embalagem com válvula, perfis de torra',4.5,202,13.9,'kg torrado','Luís Eduardo Magalhães','BA','Oeste da Bahia','nacional','Todo o Brasil',NULL,33,NULL,'sob agendamento','(77) 98805-1053',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(366,'produto','Colheita e armazenagem (materiais)','Panos e ferramentas de colheita','Agreste Artigos Rurais','empresa','Agreste Artigos Rurais é uma empresa sediada em Perdizes/MG, na região Cerrado Mineiro, no mercado há 2 anos. Segmento: Panos e ferramentas de colheita. Vende panos de colheita, peneiras e rastelos. Faz entrega antes da safra. Emite nota fiscal e entrega na propriedade. Dá desconto em compras de volume e para cooperados. Especialidades: peneira, balaio. Atende toda a região Cerrado Mineiro (Patrocínio, Araguari, Monte Carmelo, Patos de Minas, Carmo do Paranaíba, Serra do Salitre, Campos Altos, Coromandel, Rio Paranaíba, Ibiá, Perdizes, Estrela do Sul, São Gotardo), num raio de até 200 km da sede. Preço médio: R$ 153,00 por unidade. Avaliação média 4,7 de 5 (272 avaliações). Disponibilidade: sob encomenda.','peneira, balaio',4.7,272,153.0,'unidade','Perdizes','MG','Cerrado Mineiro','regional','Patrocínio, Araguari, Monte Carmelo, Patos de Minas, Carmo do Paranaíba, Serra do Salitre, Campos Altos, Coromandel, Rio Paranaíba, Ibiá, Perdizes, Estrela do Sul, São Gotardo',200,2,NULL,'sob encomenda','(34) 98853-8121',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(367,'produto','Máquinas e implementos','Máquinas agrícolas usadas','Geraldo Carvalho','pessoa_fisica','Geraldo Carvalho atua como revendedor(a) autônomo(a) de máquinas agrícolas usadas em Carmo do Rio Claro/MG, na região Sul de Minas, com 31 anos de experiência. Faz a vistoria da máquina antes da venda. Vende tratores, colhedoras e implementos usados revisados. Mantém estoque o ano todo. Especialidades: troca e consignação, colhedoras usadas, implementos usados. Atende toda a região Sul de Minas (Varginha, Três Pontas, Guaxupé, Machado, Alfenas, Boa Esperança, Campos Gerais, Carmo de Minas, São Sebastião do Paraíso, Nepomuceno, Poços de Caldas, Nova Resende, Muzambinho, Cabo Verde, Monte Santo de Minas, Três Corações, Elói Mendes, Paraguaçu, Carmo do Rio Claro, Ilicínea, Santana da Vargem, Coqueiral, Cambuquira), num raio de até 80 km da sede. Preço médio: R$ 112.000,00 por unidade. Avaliação média 4,4 de 5 (19 avaliações). Disponibilidade: pronta entrega.','troca e consignação, colhedoras usadas, implementos usados',4.4,19,112000.0,'unidade','Carmo do Rio Claro','MG','Sul de Minas','regional','Varginha, Três Pontas, Guaxupé, Machado, Alfenas, Boa Esperança, Campos Gerais, Carmo de Minas, São Sebastião do Paraíso, Nepomuceno, Poços de Caldas, Nova Resende, Muzambinho, Cabo Verde, Monte Santo de Minas, Três Corações, Elói Mendes, Paraguaçu, Carmo do Rio Claro, Ilicínea, Santana da Vargem, Coqueiral, Cambuquira',80,31,NULL,'pronta entrega','(35) 98133-9876',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(368,'produto','Colheita e armazenagem (materiais)','Sacaria','Vilela Embalagens','empresa','Vilela Embalagens é uma empresa sediada em Japira/PR, na região Norte Pioneiro do Paraná, no mercado há 14 anos. Segmento: Sacaria. Tem big bags para armazenagem de café em coco. Faz sacaria personalizada com a marca da fazenda. Dá desconto em compras de volume e para cooperados. Especialidades: big bags, sacos de ráfia, sacaria personalizada, sacos de juta. Atende e envia para todo o Brasil. Preço médio: R$ 11,87 por unidade. Avaliação média 2,8 de 5 (26 avaliações). Disponibilidade: pronta entrega.','big bags, sacos de ráfia, sacaria personalizada, sacos de juta',2.8,26,11.87,'unidade','Japira','PR','Norte Pioneiro do Paraná','nacional','Todo o Brasil',NULL,14,NULL,'pronta entrega','(43) 99512-2491',0,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(369,'produto','Colheita e armazenagem (materiais)','Sacaria','Mesquita Embalagens','empresa','Mesquita Embalagens é uma empresa sediada em Muniz Freire/ES, na região Montanhas do Espírito Santo, no mercado há 45 anos. Segmento: Sacaria. Tem big bags para armazenagem de café em coco. Vende sacos de juta e ráfia para café beneficiado. Trabalha com marcas reconhecidas e garantia de fábrica. Especialidades: sacos de juta, big bags. Atende e envia para todo o Brasil. Preço médio: R$ 12,92 por unidade. Avaliação média 4,8 de 5 (355 avaliações). Disponibilidade: pronta entrega.','sacos de juta, big bags',4.8,355,12.92,'unidade','Muniz Freire','ES','Montanhas do Espírito Santo','nacional','Todo o Brasil',NULL,45,NULL,'pronta entrega','(28) 98707-6944',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(370,'servico','Planejamento e implantação da lavoura','Engenheiro agrônomo','AgroTec Mundo Novo','empresa','AgroTec Mundo Novo é uma empresa sediada em Perdões/MG, na região Campo das Vertentes, no mercado há 23 anos. Segmento: Engenheiro agrônomo. Ajuda a planejar a renovação de talhões improdutivos com análise de custo. Acompanha a lavoura com visitas periódicas e emite receituário agronômico. Atende muitos produtores de cafés especiais da região. Especialidades: planejamento de safra, cafés especiais. Atende toda a região Campo das Vertentes (Lavras, Perdões, Bom Sucesso, Ijaci, Santo Antônio do Amparo, Itumirim, Ingaí), num raio de até 120 km da sede. Preço médio: R$ 806,00 por visita técnica. Avaliação média 2,7 de 5 (76 avaliações). Disponibilidade: sob agendamento. Certificações/registros: CREA ativo.','planejamento de safra, cafés especiais',2.7,76,806.0,'visita técnica','Perdões','MG','Campo das Vertentes','regional','Lavras, Perdões, Bom Sucesso, Ijaci, Santo Antônio do Amparo, Itumirim, Ingaí',120,23,'CREA ativo','sob agendamento','(35) 99518-8239',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(371,'produto','Pós-colheita e beneficiamento (equipamentos)','Lonas para terreiro e secagem','Oliveira Lonas e Coberturas','empresa','Oliveira Lonas e Coberturas é uma empresa sediada em Machado/MG, na região Sul de Minas, no mercado há 20 anos. Segmento: Lonas para terreiro e secagem. Faz lonas sob medida com ilhós. Tem telas para terreiros suspensos. Atende de pequenos produtores a grandes fazendas. Tem assistência técnica e pós-venda. Especialidades: lona de terreiro, lona para cobertura. Atende e envia para todo o Brasil. Preço médio: R$ 11,01 por m². Avaliação média 4,7 de 5 (308 avaliações). Disponibilidade: sob encomenda.','lona de terreiro, lona para cobertura',4.7,308,11.01,'m²','Machado','MG','Sul de Minas','nacional','Todo o Brasil',NULL,20,NULL,'sob encomenda','(35) 99210-5450',1,'2026-09-24 20:42:33');
