INSERT INTO "fornecedores" VALUES(374,'produto','Irrigação e infraestrutura','Materiais para construção rural','Cafeeiro Materiais de Construção','empresa','Cafeeiro Materiais de Construção é uma empresa sediada em Simonésia/MG, na região Matas de Minas, no mercado há 2 anos. Segmento: Materiais para construção rural. Tem arame, mourões e material para cercas. Faz entrega na propriedade. Mantém estoque o ano todo. Especialidades: telhas, madeira, arame e mourões. Atende produtores em Simonésia, Lajinha, Alto Jequitibá, Carangola, num raio de até 30 km. Preço médio: R$ 7.740,00 por ticket médio. Avaliação média 4,8 de 5 (168 avaliações). Disponibilidade: pronta entrega.','telhas, madeira, arame e mourões',4.8,168,7740.0,'ticket médio','Simonésia','MG','Matas de Minas','local','Simonésia, Lajinha, Alto Jequitibá, Carangola',30,2,NULL,'pronta entrega','(33) 99740-1708',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(375,'servico','Qualidade e comercialização','Q-Grader / provador de café','Grão Nobre Cafés Especiais','empresa','Grão Nobre Cafés Especiais é uma empresa sediada em Domingos Martins/ES, na região Montanhas do Espírito Santo, no mercado há 20 anos. Segmento: Q-Grader / provador de café. Emite laudo sensorial com notas e descritores para venda de cafés especiais. Prepara lotes para concursos de qualidade. Agenda as visitas com antecedência e cumpre os prazos combinados. Prioriza atendimento a propriedades familiares. Especialidades: análise sensorial, perfil sensorial. Atende e envia para todo o Brasil. Preço médio: R$ 153,00 por amostra. Avaliação média 4,6 de 5 (304 avaliações). Disponibilidade: sob agendamento. Certificações/registros: Q-Robusta Grader (CQI).','análise sensorial, perfil sensorial',4.6,304,153.0,'amostra','Domingos Martins','ES','Montanhas do Espírito Santo','nacional','Todo o Brasil',NULL,20,'Q-Robusta Grader (CQI)','sob agendamento','(28) 99529-5284',1,'2026-09-24 20:42:33');
