INSERT INTO "fornecedores" VALUES(381,'produto','Pós-colheita e beneficiamento (equipamentos)','Máquinas de beneficiamento','Moreira Máquinas de Beneficiamento','empresa','Moreira Máquinas de Beneficiamento é uma empresa sediada em Rio Bananal/ES, na região Norte do Espírito Santo, no mercado há 37 anos. Segmento: Máquinas de beneficiamento. Vende linhas completas de beneficiamento para fazendas e armazéns. Faz o projeto da unidade de beneficiamento. Tem experiência com café conilon/robusta. Especialidades: catadora eletrônica, mesa densimétrica, peneira classificadora. Atende e envia para todo o Brasil. Preço médio: R$ 388.000,00 por unidade. Avaliação média 4,8 de 5 (276 avaliações). Disponibilidade: sob encomenda.','catadora eletrônica, mesa densimétrica, peneira classificadora',4.8,276,388000.0,'unidade','Rio Bananal','ES','Norte do Espírito Santo','nacional','Todo o Brasil',NULL,37,NULL,'sob encomenda','(27) 98524-3731',1,'2026-09-24 20:42:33');
