INSERT INTO "fornecedores" VALUES(396,'servico','Pós-colheita e processamento','Serviço de beneficiamento de café','Beneficiadora Vale Verde','empresa','Beneficiadora Vale Verde é uma empresa sediada em Ibatiba/ES, na região Montanhas do Espírito Santo, no mercado há 7 anos. Segmento: Serviço de beneficiamento de café. Presta serviço de beneficiamento com separação por peneira e densidade. Monta e padroniza lotes para venda. Tem equipe treinada e equipamentos revisados. Especialidades: separação por peneira, beneficiamento. Atende toda a região Montanhas do Espírito Santo (Venda Nova do Imigrante, Brejetuba, Iúna, Domingos Martins, Castelo, Afonso Cláudio, Conceição do Castelo, Ibatiba, Irupi, Muniz Freire), num raio de até 80 km da sede. Preço médio: R$ 10,14 por saca de 60 kg. Avaliação média 5,0 de 5 (167 avaliações). Disponibilidade: sob agendamento.','separação por peneira, beneficiamento',5.0,167,10.14,'saca de 60 kg','Ibatiba','ES','Montanhas do Espírito Santo','regional','Venda Nova do Imigrante, Brejetuba, Iúna, Domingos Martins, Castelo, Afonso Cláudio, Conceição do Castelo, Ibatiba, Irupi, Muniz Freire',80,7,NULL,'sob agendamento','(28) 99315-4130',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(397,'produto','Máquinas e implementos','Revenda de colhedoras de café','Nova Safra Colhedoras','empresa','Nova Safra Colhedoras é uma empresa sediada em Luís Eduardo Magalhães/BA, na região Oeste da Bahia, no mercado há 43 anos. Segmento: Revenda de colhedoras de café. Tem equipe de pós-venda e treinamento de operador. Vende colhedoras automotrizes e tracionadas para café. Acostumado a lavouras planas e altamente mecanizadas. Especialidades: colhedoras seminovas, recolhedora, colhedora automotriz. Atende toda a região Oeste da Bahia (Luís Eduardo Magalhães, Barreiras, São Desidério), num raio de até 200 km da sede. Preço médio: R$ 887.000,00 por unidade. Avaliação média 4,0 de 5 (210 avaliações). Disponibilidade: pronta entrega.','colhedoras seminovas, recolhedora, colhedora automotriz',4.0,210,887000.0,'unidade','Luís Eduardo Magalhães','BA','Oeste da Bahia','regional','Luís Eduardo Magalhães, Barreiras, São Desidério',200,43,NULL,'pronta entrega','(77) 99120-8238',0,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(398,'produto','Tecnologia e comercialização','Software de gestão rural','Boa Vista Agro Software','empresa','Boa Vista Agro Software é uma empresa sediada em Nova Venécia/ES, na região Norte do Espírito Santo, no mercado há 45 anos. Segmento: Software de gestão rural. Tem aplicativo para registro de atividades no campo. Oferece sistema para controlar custos, estoque e produção da fazenda. Tem experiência com café conilon/robusta. Especialidades: aplicativo móvel, rastreabilidade, controle de safra. Atende e envia para todo o Brasil. Preço médio: R$ 185,00 por mês. Avaliação média 3,9 de 5 (350 avaliações). Disponibilidade: pronta entrega.','aplicativo móvel, rastreabilidade, controle de safra',3.9,350,185.0,'mês','Nova Venécia','ES','Norte do Espírito Santo','nacional','Todo o Brasil',NULL,45,NULL,'pronta entrega','(27) 98594-7035',1,'2026-09-24 20:42:33');
