INSERT INTO "fornecedores" VALUES(403,'servico','Colheita','Transportador de café','Nova Safra Logística Rural','empresa','Nova Safra Logística Rural é uma empresa sediada em Nova Venécia/ES, na região Norte do Espírito Santo, no mercado há 45 anos. Segmento: Transportador de café. Trabalha com caminhão basculante e carreta. Faz o transporte do café da lavoura até o terreiro ou secador. Tem experiência com café conilon/robusta. Especialidades: transporte de café em big bag, carreta, frete para armazém. Atende toda a região Norte do Espírito Santo (Linhares, São Gabriel da Palha, Nova Venécia, Jaguaré, Vila Valério, Sooretama, Rio Bananal, Águia Branca), num raio de até 120 km da sede. Preço médio: R$ 320,00 por viagem. Avaliação média 3,8 de 5 (301 avaliações). Disponibilidade: imediata. Certificações/registros: ANTT, CNH categoria E.','transporte de café em big bag, carreta, frete para armazém',3.8,301,320.0,'viagem','Nova Venécia','ES','Norte do Espírito Santo','regional','Linhares, São Gabriel da Palha, Nova Venécia, Jaguaré, Vila Valério, Sooretama, Rio Bananal, Águia Branca',120,45,'ANTT, CNH categoria E','imediata','(27) 98149-4654',1,'2026-09-24 20:42:33');
