INSERT INTO "fornecedores" VALUES(405,'servico','Qualidade e comercialização','Torrefação por encomenda','Torrefação Nova Safra','empresa','Torrefação Nova Safra é uma empresa sediada em Viçosa/MG, na região Matas de Minas, no mercado há 11 anos. Segmento: Torrefação por encomenda. Oferece moagem, embalagem com válvula e rótulo. Desenvolve perfis de torra de acordo com o lote. Trabalha aos sábados durante a safra. Especialidades: torra sob encomenda, moagem, marca própria, embalagem com válvula. Atende e envia para todo o Brasil. Preço médio: R$ 22,87 por kg torrado. Avaliação média 4,9 de 5 (250 avaliações). Disponibilidade: sob agendamento.','torra sob encomenda, moagem, marca própria, embalagem com válvula',4.9,250,22.87,'kg torrado','Viçosa','MG','Matas de Minas','nacional','Todo o Brasil',NULL,11,NULL,'sob agendamento','(33) 98790-3248',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(406,'servico','Máquinas, estrutura e manutenção','Mecânico de máquinas agrícolas','Camila Castro','pessoa_fisica','Camila Castro atua como mecânico de máquinas agrícolas em Nova Venécia/ES, na região Norte do Espírito Santo, com 27 anos de experiência. Tem experiência com sistema hidráulico e motores diesel. Faz manutenção de tratores e implementos com atendimento na propriedade. Emite nota fiscal e formaliza o serviço em contrato. Tem equipe treinada e equipamentos revisados. Tem experiência com café conilon/robusta. Especialidades: atendimento no campo, pulverizadores. Atende produtores em Nova Venécia, Linhares, Jaguaré, Rio Bananal, num raio de até 40 km. Preço médio: R$ 104,00 por hora. Avaliação média 3,5 de 5 (5 avaliações). Disponibilidade: sob agendamento.','atendimento no campo, pulverizadores',3.5,5,104.0,'hora','Nova Venécia','ES','Norte do Espírito Santo','local','Nova Venécia, Linhares, Jaguaré, Rio Bananal',40,27,NULL,'sob agendamento','(27) 99645-5131',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(407,'servico','Máquinas, estrutura e manutenção','Construtor de terreiros e tulhas','Nascimento Construções Rurais','empresa','Nascimento Construções Rurais é uma empresa sediada em Espírito Santo do Pinhal/SP, na região Mogiana, no mercado há 22 anos. Segmento: Construtor de terreiros e tulhas. Executa tulhas e galpões para armazenagem. Monta terreiros suspensos para cafés especiais. Emite nota fiscal e formaliza o serviço em contrato. Agenda as visitas com antecedência e cumpre os prazos combinados. Especialidades: terreiro de concreto, terreiro suspenso, barracões. Atende produtores em Espírito Santo do Pinhal, Mococa, Altinópolis, Pedregulho, num raio de até 30 km. Preço médio: R$ 76,00 por m². Avaliação média 4,7 de 5 (103 avaliações). Disponibilidade: sob agendamento.','terreiro de concreto, terreiro suspenso, barracões',4.7,103,76.0,'m²','Espírito Santo do Pinhal','SP','Mogiana','local','Espírito Santo do Pinhal, Mococa, Altinópolis, Pedregulho',30,22,NULL,'sob agendamento','(16) 98581-5968',1,'2026-09-24 20:42:33');
