INSERT INTO "fornecedores" VALUES(409,'servico','Manejo e tratos culturais','Laboratório de análise de solo e foliar','Laboratório Aroeira','empresa','Laboratório Aroeira é uma empresa sediada em Ibiá/MG, na região Cerrado Mineiro, no mercado há 15 anos. Segmento: Laboratório de análise de solo e foliar. Oferece análise química completa com micronutrientes e matéria orgânica. Recebe amostras de solo e folha e entrega laudos em poucos dias úteis. Especialidades: análise física de solo, análise foliar. Atende toda a região Cerrado Mineiro (Patrocínio, Araguari, Monte Carmelo, Patos de Minas, Carmo do Paranaíba, Serra do Salitre, Campos Altos, Coromandel, Rio Paranaíba, Ibiá, Perdizes, Estrela do Sul, São Gotardo), num raio de até 200 km da sede. Preço médio: R$ 102,00 por amostra. Avaliação média 3,8 de 5 (94 avaliações). Disponibilidade: sob agendamento. Certificações/registros: Acreditação ISO 17025.','análise física de solo, análise foliar',3.8,94,102.0,'amostra','Ibiá','MG','Cerrado Mineiro','regional','Patrocínio, Araguari, Monte Carmelo, Patos de Minas, Carmo do Paranaíba, Serra do Salitre, Campos Altos, Coromandel, Rio Paranaíba, Ibiá, Perdizes, Estrela do Sul, São Gotardo',200,15,'Acreditação ISO 17025','sob agendamento','(34) 99895-1666',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(410,'produto','Insumos agrícolas','Fertilizantes foliares e micronutrientes','Dias Foliares','empresa','Dias Foliares é uma empresa sediada em São Miguel do Guaporé/RO, na região Matas de Rondônia, no mercado há 31 anos. Segmento: Fertilizantes foliares e micronutrientes. Vende foliares com boro, zinco e manganês para o cafeeiro. Oferece bioestimulantes para pré-florada e enchimento de grãos. Trabalha com marcas reconhecidas e garantia de fábrica. Tem experiência com café conilon/robusta. Especialidades: zinco, manganês, cálcio foliar, aminoácidos. Atende toda a região Matas de Rondônia (Cacoal, Ministro Andreazza, Alta Floresta D''Oeste, Rolim de Moura, Nova Brasilândia D''Oeste, São Miguel do Guaporé), num raio de até 80 km da sede. Preço médio: R$ 58,00 por litro. Avaliação média 3,9 de 5 (372 avaliações). Disponibilidade: sob encomenda.','zinco, manganês, cálcio foliar, aminoácidos',3.9,372,58.0,'litro','São Miguel do Guaporé','RO','Matas de Rondônia','regional','Cacoal, Ministro Andreazza, Alta Floresta D''Oeste, Rolim de Moura, Nova Brasilândia D''Oeste, São Miguel do Guaporé',80,31,NULL,'sob encomenda','(69) 99286-6264',1,'2026-09-24 20:42:33');
