INSERT INTO "fornecedores" VALUES(455,'produto','Tecnologia e comercialização','Cooperativa cafeeira','CoopPlanalto','empresa','CoopPlanalto é uma empresa sediada em Mucugê/BA, na região Chapada Diamantina, no mercado há 33 anos. Segmento: Cooperativa cafeeira. Oferece assistência técnica e armazenagem. Tem linhas de crédito para cooperados. Parcela no cartão ou aceita pagamento na safra. Especialidades: venda de insumos, armazenagem. Atende toda a região Chapada Diamantina (Piatã, Mucugê, Ibicoara, Barra da Estiva, Abaíra, Ituaçu), num raio de até 100 km da sede. Preço médio: R$ 886,00 por cota-parte de adesão. Avaliação média 3,5 de 5 (184 avaliações). Disponibilidade: pronta entrega.','venda de insumos, armazenagem',3.5,184,886.0,'cota-parte de adesão','Mucugê','BA','Chapada Diamantina','regional','Piatã, Mucugê, Ibicoara, Barra da Estiva, Abaíra, Ituaçu',100,33,NULL,'pronta entrega','(75) 99036-6716',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(456,'servico','Colheita','Empreiteiro de mão de obra rural','Tavares Serviços Rurais','empresa','Tavares Serviços Rurais é uma empresa sediada em Ibaiti/PR, na região Norte Pioneiro do Paraná, no mercado há 20 anos. Segmento: Empreiteiro de mão de obra rural. Fornece turmas completas de colheita com transporte e registro em carteira. Organiza as equipes e o controle de produção por medida colhida. Especialidades: turma de poda, mão de obra registrada. Atende toda a região Norte Pioneiro do Paraná (Pinhalão, Carlópolis, Tomazina, Ibaiti, Jacarezinho, Ribeirão Claro, Japira, Joaquim Távora), num raio de até 120 km da sede. Preço médio: R$ 193,00 por diária por trabalhador. Avaliação média 2,7 de 5 (319 avaliações). Disponibilidade: agenda cheia até o fim da safra. Certificações/registros: NR-31, Empresa com CNPJ e mão de obra registrada.','turma de poda, mão de obra registrada',2.7,319,193.0,'diária por trabalhador','Ibaiti','PR','Norte Pioneiro do Paraná','regional','Pinhalão, Carlópolis, Tomazina, Ibaiti, Jacarezinho, Ribeirão Claro, Japira, Joaquim Távora',120,20,'NR-31, Empresa com CNPJ e mão de obra registrada','agenda cheia até o fim da safra','(43) 98664-2363',1,'2026-09-24 20:42:33');
