INSERT INTO "fornecedores" VALUES(463,'produto','Colheita e armazenagem (materiais)','Sacaria','Rocha Embalagens','empresa','Rocha Embalagens é uma empresa sediada em Alfenas/MG, na região Sul de Minas, no mercado há 12 anos. Segmento: Sacaria. Vende sacos de juta e ráfia para café beneficiado. Faz sacaria personalizada com a marca da fazenda. Dá desconto em compras de volume e para cooperados. Especialidades: sacaria personalizada, big bags, sacos de ráfia. Atende e envia para todo o Brasil. Preço médio: R$ 22,82 por unidade. Avaliação média 4,5 de 5 (119 avaliações). Disponibilidade: pronta entrega.','sacaria personalizada, big bags, sacos de ráfia',4.5,119,22.82,'unidade','Alfenas','MG','Sul de Minas','nacional','Todo o Brasil',NULL,12,NULL,'pronta entrega','(35) 98133-7980',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(464,'produto','Colheita e armazenagem (materiais)','Embalagens herméticas para café','Vale Verde Embalagens','empresa','Vale Verde Embalagens é uma empresa sediada em São Gabriel da Palha/ES, na região Norte do Espírito Santo, no mercado há 20 anos. Segmento: Embalagens herméticas para café. Atende produtores que exportam microlotes. Vende sacos herméticos que preservam a qualidade de cafés especiais. Parcela no cartão ou aceita pagamento na safra. Tem assistência técnica e pós-venda. Tem experiência com café conilon/robusta. Especialidades: preservação de cafés especiais, sacos herméticos multicamada, embalagem para exportação. Atende e envia para todo o Brasil. Preço médio: R$ 37,15 por unidade. Avaliação média 4,4 de 5 (215 avaliações). Disponibilidade: sob encomenda.','preservação de cafés especiais, sacos herméticos multicamada, embalagem para exportação',4.4,215,37.15,'unidade','São Gabriel da Palha','ES','Norte do Espírito Santo','nacional','Todo o Brasil',NULL,20,NULL,'sob encomenda','(27) 99482-7122',0,'2026-09-24 20:42:33');
