INSERT INTO "fornecedores" VALUES(572,'servico','Planejamento e implantação da lavoura','Operador de máquinas para preparo de solo','Renata Teixeira Rodrigues','pessoa_fisica','Renata Teixeira Rodrigues atua como operador de máquinas para preparo de solo em Cabo Verde/MG, na região Sul de Minas, com 8 anos de experiência. Aplica calcário e gesso a lanço antes do plantio. Faz sulcamento e abertura de covas para implantação de lavouras novas. Faz orçamento sem compromisso na propriedade. Prioriza atendimento a propriedades familiares. Especialidades: gradagem, abertura de covas. Atende produtores em Cabo Verde, Coqueiral, Carmo de Minas, Nepomuceno, num raio de até 20 km. Preço médio: R$ 293,00 por hora-máquina. Avaliação média 4,7 de 5 (37 avaliações). Disponibilidade: imediata.','gradagem, abertura de covas',4.7,37,293.0,'hora-máquina','Cabo Verde','MG','Sul de Minas','local','Cabo Verde, Coqueiral, Carmo de Minas, Nepomuceno',20,8,NULL,'imediata','(35) 99441-5794',1,'2026-09-24 20:42:33');
