INSERT INTO "fornecedores" VALUES(580,'servico','Planejamento e implantação da lavoura','Operador de máquinas para preparo de solo','Patrícia Andrade','pessoa_fisica','Patrícia Andrade atua como operador de máquinas para preparo de solo em Sooretama/ES, na região Norte do Espírito Santo, com 26 anos de experiência. Aplica calcário e gesso a lanço antes do plantio. Presta serviço com trator e implementos próprios para preparar a área de plantio. Prioriza atendimento a propriedades familiares. Tem experiência com café conilon/robusta. Especialidades: aração, subsolagem, abertura de covas, gradagem. Atende produtores em Sooretama, Linhares, Nova Venécia, num raio de até 50 km. Preço médio: R$ 224,00 por hora-máquina. Avaliação média 3,6 de 5 (26 avaliações). Disponibilidade: sob agendamento. Certificações/registros: CNH categoria C, Curso de operador de máquinas agrícolas.','aração, subsolagem, abertura de covas, gradagem',3.6,26,224.0,'hora-máquina','Sooretama','ES','Norte do Espírito Santo','local','Sooretama, Linhares, Nova Venécia',50,26,'CNH categoria C, Curso de operador de máquinas agrícolas','sob agendamento','(27) 99046-7364',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(581,'produto','Colheita e armazenagem (materiais)','Embalagens herméticas para café','Hermetic Água Limpa','empresa','Hermetic Água Limpa é uma empresa sediada em Tomazina/PR, na região Norte Pioneiro do Paraná, no mercado há 9 anos. Segmento: Embalagens herméticas para café. Atende produtores que exportam microlotes. Envia para todo o Brasil. Emite nota fiscal e entrega na propriedade. Parcela no cartão ou aceita pagamento na safra. Especialidades: preservação de cafés especiais, sacos herméticos multicamada, embalagem para exportação. Atende e envia para todo o Brasil. Preço médio: R$ 38,84 por unidade. Avaliação média 4,4 de 5 (29 avaliações). Disponibilidade: sob encomenda.','preservação de cafés especiais, sacos herméticos multicamada, embalagem para exportação',4.4,29,38.84,'unidade','Tomazina','PR','Norte Pioneiro do Paraná','nacional','Todo o Brasil',NULL,9,NULL,'sob encomenda','(43) 99130-4868',1,'2026-09-24 20:42:33');
