INSERT INTO "fornecedores" VALUES(591,'servico','Máquinas, estrutura e manutenção','Mecânico de máquinas agrícolas','Serra da Mantiqueira Mecânica Rural','empresa','Serra da Mantiqueira Mecânica Rural é uma empresa sediada em Pinhalão/PR, na região Norte Pioneiro do Paraná, no mercado há 39 anos. Segmento: Mecânico de máquinas agrícolas. Faz manutenção de tratores e implementos com atendimento na propriedade. Atende emergências durante a safra. Prioriza atendimento a propriedades familiares. Especialidades: sistema hidráulico, atendimento no campo. Atende produtores em Pinhalão, Ibaiti, num raio de até 30 km. Preço médio: R$ 162,00 por hora. Avaliação média 3,9 de 5 (313 avaliações). Disponibilidade: imediata.','sistema hidráulico, atendimento no campo',3.9,313,162.0,'hora','Pinhalão','PR','Norte Pioneiro do Paraná','local','Pinhalão, Ibaiti',30,39,NULL,'imediata','(43) 98169-2649',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(592,'produto','Irrigação e infraestrutura','Energia solar rural','Terra Roxa Solar','empresa','Terra Roxa Solar é uma empresa sediada em Águia Branca/ES, na região Norte do Espírito Santo, no mercado há 40 anos. Segmento: Energia solar rural. Instala sistemas solares para reduzir a conta de energia de secadores e bombas. Faz o projeto e a homologação junto à distribuidora. Faz orçamento rápido pela plataforma. Tem experiência com café conilon/robusta. Especialidades: homologação, financiamento, bombeamento solar, energia solar fotovoltaica. Atende toda a região Norte do Espírito Santo (Linhares, São Gabriel da Palha, Nova Venécia, Jaguaré, Vila Valério, Sooretama, Rio Bananal, Águia Branca), num raio de até 120 km da sede. Preço médio: R$ 4.830,00 por kWp. Avaliação média 4,8 de 5 (142 avaliações). Disponibilidade: sob encomenda.','homologação, financiamento, bombeamento solar, energia solar fotovoltaica',4.8,142,4830.0,'kWp','Águia Branca','ES','Norte do Espírito Santo','regional','Linhares, São Gabriel da Palha, Nova Venécia, Jaguaré, Vila Valério, Sooretama, Rio Bananal, Águia Branca',120,40,NULL,'sob encomenda','(27) 98339-1920',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(593,'produto','Irrigação e infraestrutura','Sistemas de irrigação','Mendes Irrigação','empresa','Mendes Irrigação é uma empresa sediada em Rolim de Moura/RO, na região Matas de Rondônia, no mercado há 28 anos. Segmento: Sistemas de irrigação. Vende e instala sistemas de gotejamento para café. Faz o projeto sem custo na compra do sistema. Trabalha com marcas reconhecidas e garantia de fábrica. Tem experiência com café conilon/robusta. Especialidades: automação, tubos gotejadores. Atende toda a região Matas de Rondônia (Cacoal, Ministro Andreazza, Alta Floresta D''Oeste, Rolim de Moura, Nova Brasilândia D''Oeste, São Miguel do Guaporé), num raio de até 100 km da sede. Preço médio: R$ 12.000,00 por hectare. Avaliação média 3,6 de 5 (382 avaliações). Disponibilidade: estoque limitado.','automação, tubos gotejadores',3.6,382,12000.0,'hectare','Rolim de Moura','RO','Matas de Rondônia','regional','Cacoal, Ministro Andreazza, Alta Floresta D''Oeste, Rolim de Moura, Nova Brasilândia D''Oeste, São Miguel do Guaporé',100,28,NULL,'estoque limitado','(69) 99683-5709',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(594,'servico','Manejo e tratos culturais','Aplicador de defensivos','Sebastião Furtado Souza','pessoa_fisica','Sebastião Furtado Souza atua como aplicador de defensivos agrícolas em São Sebastião da Grama/SP, na região Mogiana, com 15 anos de experiência. Possui equipamento próprio calibrado para aplicações de fungicida e inseticida. Faz aplicação tratorizada com turbo-atomizador e aplicação costal em áreas declivosas. Acostumado a lavouras planas e altamente mecanizadas. Especialidades: aplicação costal, controle de broca, pulverização com turbo-atomizador, aplicação de herbicida. Atende produtores em São Sebastião da Grama, Jeriquara, Caconde, num raio de até 30 km. Preço médio: R$ 118,00 por hectare. Avaliação média 4,8 de 5 (6 avaliações). Disponibilidade: sob agendamento. Certificações/registros: NR-31.','aplicação costal, controle de broca, pulverização com turbo-atomizador, aplicação de herbicida',4.8,6,118.0,'hectare','São Sebastião da Grama','SP','Mogiana','local','São Sebastião da Grama, Jeriquara, Caconde',30,15,'NR-31','sob agendamento','(16) 98098-2771',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(595,'produto','Tecnologia e comercialização','Estações meteorológicas e sensores','Sol Nascente Agrotech','empresa','Sol Nascente Agrotech é uma empresa sediada em Lajinha/MG, na região Matas de Minas, no mercado há 25 anos. Segmento: Estações meteorológicas e sensores. Envia alertas de geada e chuva. Vende estações meteorológicas conectadas ao celular. Especialidades: monitoramento remoto, sensor de umidade do solo. Atende e envia para todo o Brasil. Preço médio: R$ 12.000,00 por unidade. Avaliação média 4,7 de 5 (385 avaliações). Disponibilidade: pronta entrega.','monitoramento remoto, sensor de umidade do solo',4.7,385,12000.0,'unidade','Lajinha','MG','Matas de Minas','nacional','Todo o Brasil',NULL,25,NULL,'pronta entrega','(33) 98654-2341',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(596,'servico','Pós-colheita e processamento','Operador de lavador e despolpador','Wellington Carvalho Freitas','pessoa_fisica','Wellington Carvalho Freitas atua como operador de lavador e despolpador em Lavras/MG, na região Campo das Vertentes, com 7 anos de experiência. Faz o descascamento e despolpamento para produção de cereja descascado. Opera o lavador para separar o café boia do cereja e verde. Trabalha aos sábados durante a safra. Tem equipe treinada e equipamentos revisados. Especialidades: fermentação controlada, despolpamento. Atende produtores em Lavras, Itumirim, Ijaci, Santo Antônio do Amparo, num raio de até 50 km. Preço médio: R$ 218,00 por diária. Avaliação média 4,3 de 5 (16 avaliações). Disponibilidade: sob agendamento. Certificações/registros: NR-12.','fermentação controlada, despolpamento',4.3,16,218.0,'diária','Lavras','MG','Campo das Vertentes','local','Lavras, Itumirim, Ijaci, Santo Antônio do Amparo',50,7,'NR-12','sob agendamento','(35) 98569-6150',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(597,'servico','Pós-colheita e processamento','Armazém de café','Armazéns Bourbon','empresa','Armazéns Bourbon é uma empresa sediada em Altinópolis/SP, na região Mogiana, no mercado há 31 anos. Segmento: Armazém de café. Oferece amostragem e rastreabilidade dos lotes. Emite certificados de depósito para operações de crédito. Especialidades: armazém geral, armazenagem em sacaria. Atende toda a região Mogiana (Franca, Pedregulho, Cristais Paulista, Altinópolis, Espírito Santo do Pinhal, Caconde, Ribeirão Corrente, Jeriquara, Patrocínio Paulista, Itirapuã, São Sebastião da Grama, Mococa), num raio de até 100 km da sede. Preço médio: R$ 3,79 por saca/mês. Avaliação média 4,4 de 5 (165 avaliações). Disponibilidade: imediata.','armazém geral, armazenagem em sacaria',4.4,165,3.79,'saca/mês','Altinópolis','SP','Mogiana','regional','Franca, Pedregulho, Cristais Paulista, Altinópolis, Espírito Santo do Pinhal, Caconde, Ribeirão Corrente, Jeriquara, Patrocínio Paulista, Itirapuã, São Sebastião da Grama, Mococa',100,31,NULL,'imediata','(16) 98466-4996',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(598,'servico','Colheita','Colhedor manual','Mariana Castro','pessoa_fisica','Mariana Castro atua como colhedor de café em Cristais Paulista/SP, na região Mogiana, com 18 anos de experiência. Tem experiência em colheita em lavouras de montanha. Trabalha na derriça no pano e na colheita seletiva de cereja madura. Emite nota fiscal e formaliza o serviço em contrato. Especialidades: derriça no pano, catação, colheita em montanha, colheita seletiva. Atende produtores em Cristais Paulista, Pedregulho, num raio de até 50 km. Preço médio: R$ 35,96 por medida de 60 L. Avaliação média 4,7 de 5 (27 avaliações). Disponibilidade: imediata. Certificações/registros: NR-31.','derriça no pano, catação, colheita em montanha, colheita seletiva',4.7,27,35.96,'medida de 60 L','Cristais Paulista','SP','Mogiana','local','Cristais Paulista, Pedregulho',50,18,'NR-31','imediata','(16) 98522-3916',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(599,'servico','Manejo e tratos culturais','Trabalhador rural para tratos culturais','Thiago Araújo Pimenta','pessoa_fisica','Thiago Araújo Pimenta atua como trabalhador rural diarista em Perdões/MG, na região Campo das Vertentes, com 22 anos de experiência. Faz replantio de falhas e amarração de mudas. Trabalha como diarista em capina, roçada e adubação manual. Faz orçamento sem compromisso na propriedade. Especialidades: replantio, arruação, esparramação. Atende produtores em Perdões, Ingaí, num raio de até 50 km. Preço médio: R$ 140,00 por diária. Avaliação média 4,8 de 5 (39 avaliações). Disponibilidade: agenda cheia até o fim da safra. Certificações/registros: NR-31.','replantio, arruação, esparramação',4.8,39,140.0,'diária','Perdões','MG','Campo das Vertentes','local','Perdões, Ingaí',50,22,'NR-31','agenda cheia até o fim da safra','(35) 98650-2111',1,'2026-09-24 20:42:33');
