INSERT INTO "fornecedores" VALUES(651,'servico','Pós-colheita e processamento','Operador de lavador e despolpador','Luiz Araújo Campos','pessoa_fisica','Luiz Araújo Campos atua como operador de lavador e despolpador em Sooretama/ES, na região Norte do Espírito Santo, com 5 anos de experiência. Acompanha processos de fermentação controlada. Opera o lavador para separar o café boia do cereja e verde. Tem experiência com café conilon/robusta. Especialidades: separação de boia, fermentação controlada. Atende produtores em Sooretama, Jaguaré, num raio de até 60 km. Preço médio: R$ 179,00 por diária. Avaliação média 3,9 de 5 (18 avaliações). Disponibilidade: imediata. Certificações/registros: NR-12, NR-31.','separação de boia, fermentação controlada',3.9,18,179.0,'diária','Sooretama','ES','Norte do Espírito Santo','local','Sooretama, Jaguaré',60,5,'NR-12, NR-31','imediata','(27) 99636-6930',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(652,'produto','Máquinas e implementos','Revenda de pulverizadores','Oliveira Agrícola','empresa','Oliveira Agrícola é uma empresa sediada em Ministro Andreazza/RO, na região Matas de Rondônia, no mercado há 19 anos. Segmento: Revenda de pulverizadores. Tem bicos e peças de reposição. Faz calibração e regulagem na entrega. Trabalha com marcas reconhecidas e garantia de fábrica. Tem experiência com café conilon/robusta. Especialidades: pulverizador costal, turbo-atomizador. Atende toda a região Matas de Rondônia (Cacoal, Ministro Andreazza, Alta Floresta D''Oeste, Rolim de Moura, Nova Brasilândia D''Oeste, São Miguel do Guaporé), num raio de até 120 km da sede. Preço médio: R$ 18.000,00 por unidade. Avaliação média 4,6 de 5 (117 avaliações). Disponibilidade: sob encomenda.','pulverizador costal, turbo-atomizador',4.6,117,18000.0,'unidade','Ministro Andreazza','RO','Matas de Rondônia','regional','Cacoal, Ministro Andreazza, Alta Floresta D''Oeste, Rolim de Moura, Nova Brasilândia D''Oeste, São Miguel do Guaporé',120,19,NULL,'sob encomenda','(69) 99298-1256',1,'2026-09-24 20:42:33');
