INSERT INTO "fornecedores" VALUES(657,'produto','Máquinas e implementos','Derriçadeiras e roçadeiras portáteis','Bernardes Equipamentos Agrícolas','empresa','Bernardes Equipamentos Agrícolas é uma empresa sediada em Rio Bananal/ES, na região Norte do Espírito Santo, no mercado há 4 anos. Segmento: Derriçadeiras e roçadeiras portáteis. Vende derriçadeiras a gasolina e elétricas a bateria. Tem assistência técnica e peças de reposição na loja. Tem experiência com café conilon/robusta. Especialidades: assistência técnica, derriçadeira a gasolina. Atende toda a região Norte do Espírito Santo (Linhares, São Gabriel da Palha, Nova Venécia, Jaguaré, Vila Valério, Sooretama, Rio Bananal, Águia Branca), num raio de até 120 km da sede. Preço médio: R$ 3.540,00 por unidade. Avaliação média 4,8 de 5 (340 avaliações). Disponibilidade: sob encomenda.','assistência técnica, derriçadeira a gasolina',4.8,340,3540.0,'unidade','Rio Bananal','ES','Norte do Espírito Santo','regional','Linhares, São Gabriel da Palha, Nova Venécia, Jaguaré, Vila Valério, Sooretama, Rio Bananal, Águia Branca',120,4,NULL,'sob encomenda','(27) 98990-2684',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(658,'produto','Tecnologia e comercialização','Medidores de umidade de grãos','Moreira Medidores','empresa','Moreira Medidores é uma empresa sediada em Ribeirão Corrente/SP, na região Mogiana, no mercado há 3 anos. Segmento: Medidores de umidade de grãos. Vende medidores para controlar o ponto de secagem do café. Envia para todo o Brasil. Faz orçamento rápido pela plataforma. Especialidades: determinador de umidade, calibração. Atende e envia para todo o Brasil. Preço médio: R$ 3.350,00 por unidade. Avaliação média 4,8 de 5 (356 avaliações). Disponibilidade: pronta entrega.','determinador de umidade, calibração',4.8,356,3350.0,'unidade','Ribeirão Corrente','SP','Mogiana','nacional','Todo o Brasil',NULL,3,NULL,'pronta entrega','(16) 98091-3113',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(659,'servico','Colheita','Colhedor manual','Mariana Freitas Figueiredo','pessoa_fisica','Mariana Freitas Figueiredo atua como colhedor de café em Ibiá/MG, na região Cerrado Mineiro, com 15 anos de experiência. Tem experiência em colheita em lavouras de montanha. Faz catação e varrição do café do chão após a colheita. Atende pequenos, médios e grandes produtores. Segue as boas práticas exigidas por certificadoras. Especialidades: colheita seletiva, varrição, catação, derriça no pano. Atende produtores em Ibiá, Campos Altos, num raio de até 50 km. Preço médio: R$ 39,68 por medida de 60 L. Avaliação média 4,5 de 5 (18 avaliações). Disponibilidade: sob agendamento. Certificações/registros: NR-31.','colheita seletiva, varrição, catação, derriça no pano',4.5,18,39.68,'medida de 60 L','Ibiá','MG','Cerrado Mineiro','local','Ibiá, Campos Altos',50,15,'NR-31','sob agendamento','(34) 98605-1781',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(660,'servico','Planejamento e implantação da lavoura','Técnico agrícola','Renata Ribeiro Rezende','pessoa_fisica','Renata Ribeiro Rezende atua como técnico agrícola em lavouras de café em São Gabriel da Palha/ES, na região Norte do Espírito Santo, com 33 anos de experiência. Faz o acompanhamento de campo e a coleta de amostras de solo e folha. Monitora pragas como bicho-mineiro e broca e repassa relatórios ao produtor. Emite nota fiscal e formaliza o serviço em contrato. Tem experiência com café conilon/robusta. Especialidades: regulagem de pulverizadores, acompanhamento de lavoura. Atende produtores em São Gabriel da Palha, Águia Branca, Sooretama, Linhares, num raio de até 40 km. Preço médio: R$ 229,00 por visita técnica. Avaliação média 4,6 de 5 (8 avaliações). Disponibilidade: imediata. Certificações/registros: Registro CFTA.','regulagem de pulverizadores, acompanhamento de lavoura',4.6,8,229.0,'visita técnica','São Gabriel da Palha','ES','Norte do Espírito Santo','local','São Gabriel da Palha, Águia Branca, Sooretama, Linhares',40,33,'Registro CFTA','imediata','(27) 98057-6221',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(661,'servico','Qualidade e comercialização','Classificador de café','Planalto Classificação de Café','empresa','Planalto Classificação de Café é uma empresa sediada em Águia Branca/ES, na região Norte do Espírito Santo, no mercado há 24 anos. Segmento: Classificador de café. Ajuda o produtor a entender o que desvaloriza o lote. Emite laudo de classificação para negociação do café. Emite nota fiscal e formaliza o serviço em contrato. Tem referências de produtores da região. Tem experiência com café conilon/robusta. Especialidades: contagem de defeitos, classificação por peneira, classificação oficial, classificação por tipo. Atende toda a região Norte do Espírito Santo (Linhares, São Gabriel da Palha, Nova Venécia, Jaguaré, Vila Valério, Sooretama, Rio Bananal, Águia Branca), num raio de até 120 km da sede. Preço médio: R$ 37,38 por amostra. Avaliação média 5,0 de 5 (150 avaliações). Disponibilidade: imediata.','contagem de defeitos, classificação por peneira, classificação oficial, classificação por tipo',5.0,150,37.38,'amostra','Águia Branca','ES','Norte do Espírito Santo','regional','Linhares, São Gabriel da Palha, Nova Venécia, Jaguaré, Vila Valério, Sooretama, Rio Bananal, Águia Branca',120,24,NULL,'imediata','(27) 99442-4313',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(662,'produto','Irrigação e infraestrutura','Materiais para construção rural','Bela Vista Materiais de Construção','empresa','Bela Vista Materiais de Construção é uma empresa sediada em Altinópolis/SP, na região Mogiana, no mercado há 43 anos. Segmento: Materiais para construção rural. Faz entrega na propriedade. Tem arame, mourões e material para cercas. Especialidades: madeira, arame e mourões, telhas. Atende produtores em Altinópolis, Mococa, num raio de até 60 km. Preço médio: R$ 3.450,00 por ticket médio. Avaliação média 4,4 de 5 (73 avaliações). Disponibilidade: sob encomenda.','madeira, arame e mourões, telhas',4.4,73,3450.0,'ticket médio','Altinópolis','SP','Mogiana','local','Altinópolis, Mococa',60,43,NULL,'sob encomenda','(16) 99558-5300',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(663,'servico','Gestão, certificação e serviços de apoio','Engenheiro ambiental','Barbosa Meio Ambiente','empresa','Barbosa Meio Ambiente é uma empresa sediada em Nova Resende/MG, na região Sul de Minas, no mercado há 23 anos. Segmento: Engenheiro ambiental. Elabora planos de recuperação de áreas degradadas. Regulariza reserva legal e APP da propriedade. Especialidades: licenciamento ambiental, outorga de água, reserva legal. Atende toda a região Sul de Minas (Varginha, Três Pontas, Guaxupé, Machado, Alfenas, Boa Esperança, Campos Gerais, Carmo de Minas, São Sebastião do Paraíso, Nepomuceno, Poços de Caldas, Nova Resende, Muzambinho, Cabo Verde, Monte Santo de Minas, Três Corações, Elói Mendes, Paraguaçu, Carmo do Rio Claro, Ilicínea, Santana da Vargem, Coqueiral, Cambuquira), num raio de até 150 km da sede. Preço médio: R$ 3.280,00 por projeto. Avaliação média 4,7 de 5 (395 avaliações). Disponibilidade: sob agendamento. Certificações/registros: CREA ativo.','licenciamento ambiental, outorga de água, reserva legal',4.7,395,3280.0,'projeto','Nova Resende','MG','Sul de Minas','regional','Varginha, Três Pontas, Guaxupé, Machado, Alfenas, Boa Esperança, Campos Gerais, Carmo de Minas, São Sebastião do Paraíso, Nepomuceno, Poços de Caldas, Nova Resende, Muzambinho, Cabo Verde, Monte Santo de Minas, Três Corações, Elói Mendes, Paraguaçu, Carmo do Rio Claro, Ilicínea, Santana da Vargem, Coqueiral, Cambuquira',150,23,'CREA ativo','sob agendamento','(35) 99707-5234',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(664,'produto','Tecnologia e comercialização','Cooperativa cafeeira','Cooperativa Colheita Farta','empresa','Cooperativa Colheita Farta é uma empresa sediada em Sooretama/ES, na região Norte do Espírito Santo, no mercado há 16 anos. Segmento: Cooperativa cafeeira. Compra o café do cooperado e vende insumos com preço de cooperativa. Oferece assistência técnica e armazenagem. Tem experiência com café conilon/robusta. Especialidades: venda de insumos, assistência técnica. Atende toda a região Norte do Espírito Santo (Linhares, São Gabriel da Palha, Nova Venécia, Jaguaré, Vila Valério, Sooretama, Rio Bananal, Águia Branca), num raio de até 80 km da sede. Preço médio: R$ 2.360,00 por cota-parte de adesão. Avaliação média 4,3 de 5 (91 avaliações). Disponibilidade: sob encomenda.','venda de insumos, assistência técnica',4.3,91,2360.0,'cota-parte de adesão','Sooretama','ES','Norte do Espírito Santo','regional','Linhares, São Gabriel da Palha, Nova Venécia, Jaguaré, Vila Valério, Sooretama, Rio Bananal, Águia Branca',80,16,NULL,'sob encomenda','(27) 98929-7113',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(665,'servico','Pós-colheita e processamento','Terreirista','Camila Pimenta','pessoa_fisica','Camila Pimenta atua como terreirista em São Desidério/BA, na região Oeste da Bahia, com 4 anos de experiência. Cuida da cobertura com lona em caso de chuva. Tem experiência com secagem em terreiro suspenso para cafés especiais. Tem referências de produtores da região. Agenda as visitas com antecedência e cumpre os prazos combinados. Especialidades: cobertura noturna, secagem em terreiro suspenso. Atende produtores em São Desidério, Luís Eduardo Magalhães, num raio de até 40 km. Preço médio: R$ 187,00 por diária. Avaliação média 5,0 de 5 (18 avaliações). Disponibilidade: imediata. Certificações/registros: NR-31.','cobertura noturna, secagem em terreiro suspenso',5.0,18,187.0,'diária','São Desidério','BA','Oeste da Bahia','local','São Desidério, Luís Eduardo Magalhães',40,4,'NR-31','imediata','(77) 98031-5598',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(666,'servico','Colheita','Operador de derriçadeira','Luiz Costa Teixeira','pessoa_fisica','Luiz Costa Teixeira atua como operador de derriçadeira portátil em Barreiras/BA, na região Oeste da Bahia, com 19 anos de experiência. Opera derriçadeira portátil própria e rende mais que a colheita manual. Trabalha junto com a turma no pano para acelerar a colheita. Especialidades: manutenção de derriçadeira, derriçadeira portátil, colheita semimecanizada. Atende produtores em Barreiras, Luís Eduardo Magalhães, num raio de até 50 km. Preço médio: R$ 246,00 por diária. Avaliação média 4,0 de 5 (19 avaliações). Disponibilidade: imediata. Certificações/registros: NR-31.','manutenção de derriçadeira, derriçadeira portátil, colheita semimecanizada',4.0,19,246.0,'diária','Barreiras','BA','Oeste da Bahia','local','Barreiras, Luís Eduardo Magalhães',50,19,'NR-31','imediata','(77) 99670-5496',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(667,'servico','Máquinas, estrutura e manutenção','Construtor de terreiros e tulhas','Carvalho Construções Rurais','empresa','Carvalho Construções Rurais é uma empresa sediada em Manhuaçu/MG, na região Matas de Minas, no mercado há 42 anos. Segmento: Construtor de terreiros e tulhas. Executa tulhas e galpões para armazenagem. Monta terreiros suspensos para cafés especiais. Especialidades: tulhas, terreiro suspenso, terreiro de concreto. Atende produtores em Manhuaçu, Luisburgo, Espera Feliz, num raio de até 20 km. Preço médio: R$ 122,00 por m². Avaliação média 4,6 de 5 (63 avaliações). Disponibilidade: sob agendamento.','tulhas, terreiro suspenso, terreiro de concreto',4.6,63,122.0,'m²','Manhuaçu','MG','Matas de Minas','local','Manhuaçu, Luisburgo, Espera Feliz',20,42,NULL,'sob agendamento','(33) 98829-3463',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(668,'servico','Manejo e tratos culturais','Consultor em manejo de pragas e doenças','Rafael Costa','pessoa_fisica','Rafael Costa atua como consultor em manejo integrado de pragas em Irupi/ES, na região Montanhas do Espírito Santo, com 9 anos de experiência. Implanta programas de manejo integrado de pragas (MIP) com uso de controle biológico. Ajuda a reduzir custos com defensivos por meio de amostragem e níveis de controle. Segue as boas práticas exigidas por certificadoras. Especialidades: cercosporiose, ferrugem. Atende toda a região Montanhas do Espírito Santo (Venda Nova do Imigrante, Brejetuba, Iúna, Domingos Martins, Castelo, Afonso Cláudio, Conceição do Castelo, Ibatiba, Irupi, Muniz Freire), num raio de até 150 km da sede. Preço médio: R$ 584,00 por visita técnica. Avaliação média 3,2 de 5 (17 avaliações). Disponibilidade: imediata. Certificações/registros: Mestrado em fitopatologia, CREA ativo.','cercosporiose, ferrugem',3.2,17,584.0,'visita técnica','Irupi','ES','Montanhas do Espírito Santo','regional','Venda Nova do Imigrante, Brejetuba, Iúna, Domingos Martins, Castelo, Afonso Cláudio, Conceição do Castelo, Ibatiba, Irupi, Muniz Freire',150,9,'Mestrado em fitopatologia, CREA ativo','imediata','(28) 99421-3332',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(669,'servico','Qualidade e comercialização','Classificador de café','Pimenta Classificação','empresa','Pimenta Classificação é uma empresa sediada em Serra do Salitre/MG, na região Cerrado Mineiro, no mercado há 3 anos. Segmento: Classificador de café. Faz a classificação por tipo, peneira e defeitos conforme a tabela oficial. Ajuda o produtor a entender o que desvaloriza o lote. Faz orçamento sem compromisso na propriedade. Especialidades: classificação por peneira, classificação por tipo, contagem de defeitos, classificação oficial. Atende toda a região Cerrado Mineiro (Patrocínio, Araguari, Monte Carmelo, Patos de Minas, Carmo do Paranaíba, Serra do Salitre, Campos Altos, Coromandel, Rio Paranaíba, Ibiá, Perdizes, Estrela do Sul, São Gotardo), num raio de até 80 km da sede. Preço médio: R$ 40,84 por amostra. Avaliação média 5,0 de 5 (268 avaliações). Disponibilidade: imediata. Certificações/registros: Classificador credenciado MAPA.','classificação por peneira, classificação por tipo, contagem de defeitos, classificação oficial',5.0,268,40.84,'amostra','Serra do Salitre','MG','Cerrado Mineiro','regional','Patrocínio, Araguari, Monte Carmelo, Patos de Minas, Carmo do Paranaíba, Serra do Salitre, Campos Altos, Coromandel, Rio Paranaíba, Ibiá, Perdizes, Estrela do Sul, São Gotardo',80,3,'Classificador credenciado MAPA','imediata','(34) 99679-9370',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(670,'servico','Gestão, certificação e serviços de apoio','Consultor de gestão rural','Bourbon Gestão Rural','empresa','Bourbon Gestão Rural é uma empresa sediada em São Desidério/BA, na região Oeste da Bahia, no mercado há 4 anos. Segmento: Consultor de gestão rural. Levanta o custo de produção por saca e monta o fluxo de caixa da fazenda. Acompanha indicadores e ajuda na tomada de decisão. Especialidades: custo de produção, sucessão familiar, fluxo de caixa. Atende toda a região Oeste da Bahia (Luís Eduardo Magalhães, Barreiras, São Desidério), num raio de até 120 km da sede. Preço médio: R$ 1.980,00 por mês. Avaliação média 4,9 de 5 (116 avaliações). Disponibilidade: sob agendamento.','custo de produção, sucessão familiar, fluxo de caixa',4.9,116,1980.0,'mês','São Desidério','BA','Oeste da Bahia','regional','Luís Eduardo Magalhães, Barreiras, São Desidério',120,4,NULL,'sob agendamento','(77) 98509-7730',1,'2026-09-24 20:42:33');
