INSERT INTO "fornecedores" VALUES(672,'produto','Insumos agrícolas','Revenda de defensivos agrícolas','Três Irmãos Defensivos','empresa','Três Irmãos Defensivos é uma empresa sediada em Santo Antônio do Amparo/MG, na região Campo das Vertentes, no mercado há 31 anos. Segmento: Revenda de defensivos agrícolas. Vende fungicidas, inseticidas e herbicidas registrados para café. Emite receituário agronômico na hora da compra. Mantém estoque o ano todo. Especialidades: fungicidas, acaricidas. Atende toda a região Campo das Vertentes (Lavras, Perdões, Bom Sucesso, Ijaci, Santo Antônio do Amparo, Itumirim, Ingaí), num raio de até 200 km da sede. Preço médio: R$ 312,00 por litro (média do portfólio). Avaliação média 4,5 de 5 (224 avaliações). Disponibilidade: pronta entrega. Certificações/registros: Revenda registrada no IMA/órgão estadual.','fungicidas, acaricidas',4.5,224,312.0,'litro (média do portfólio)','Santo Antônio do Amparo','MG','Campo das Vertentes','regional','Lavras, Perdões, Bom Sucesso, Ijaci, Santo Antônio do Amparo, Itumirim, Ingaí',200,31,'Revenda registrada no IMA/órgão estadual','pronta entrega','(35) 98829-7638',1,'2026-09-24 20:42:33');
