INSERT INTO "fornecedores" VALUES(675,'produto','Irrigação e infraestrutura','Energia solar rural','Aroma do Campo Solar','empresa','Aroma do Campo Solar é uma empresa sediada em Pedregulho/SP, na região Mogiana, no mercado há 31 anos. Segmento: Energia solar rural. Faz o projeto e a homologação junto à distribuidora. Instala sistemas solares para reduzir a conta de energia de secadores e bombas. Dá desconto em compras de volume e para cooperados. Especialidades: energia solar fotovoltaica, financiamento, homologação, bombeamento solar. Atende toda a região Mogiana (Franca, Pedregulho, Cristais Paulista, Altinópolis, Espírito Santo do Pinhal, Caconde, Ribeirão Corrente, Jeriquara, Patrocínio Paulista, Itirapuã, São Sebastião da Grama, Mococa), num raio de até 120 km da sede. Preço médio: R$ 3.950,00 por kWp. Avaliação média 4,7 de 5 (384 avaliações). Disponibilidade: pronta entrega.','energia solar fotovoltaica, financiamento, homologação, bombeamento solar',4.7,384,3950.0,'kWp','Pedregulho','SP','Mogiana','regional','Franca, Pedregulho, Cristais Paulista, Altinópolis, Espírito Santo do Pinhal, Caconde, Ribeirão Corrente, Jeriquara, Patrocínio Paulista, Itirapuã, São Sebastião da Grama, Mococa',120,31,NULL,'pronta entrega','(16) 98776-8422',1,'2026-09-24 20:42:33');
