INSERT INTO "fornecedores" VALUES(705,'produto','Irrigação e infraestrutura','Sistemas de irrigação','Grão de Ouro Irrigação','empresa','Grão de Ouro Irrigação é uma empresa sediada em Jeriquara/SP, na região Mogiana, no mercado há 11 anos. Segmento: Sistemas de irrigação. Vende e instala sistemas de gotejamento para café. Faz o projeto sem custo na compra do sistema. Mantém estoque o ano todo. Especialidades: filtros, fertirrigação, automação. Atende toda a região Mogiana (Franca, Pedregulho, Cristais Paulista, Altinópolis, Espírito Santo do Pinhal, Caconde, Ribeirão Corrente, Jeriquara, Patrocínio Paulista, Itirapuã, São Sebastião da Grama, Mococa), num raio de até 100 km da sede. Preço médio: R$ 24.000,00 por hectare. Avaliação média 4,1 de 5 (115 avaliações). Disponibilidade: pronta entrega.','filtros, fertirrigação, automação',4.1,115,24000.0,'hectare','Jeriquara','SP','Mogiana','regional','Franca, Pedregulho, Cristais Paulista, Altinópolis, Espírito Santo do Pinhal, Caconde, Ribeirão Corrente, Jeriquara, Patrocínio Paulista, Itirapuã, São Sebastião da Grama, Mococa',100,11,NULL,'pronta entrega','(16) 99631-1236',1,'2026-09-24 20:42:33');
