INSERT INTO "fornecedores" VALUES(752,'servico','Gestão, certificação e serviços de apoio','Consultor de certificações','Gustavo Araújo Rocha','pessoa_fisica','Gustavo Araújo Rocha atua como consultor de certificações em Perdizes/MG, na região Cerrado Mineiro, com 9 anos de experiência. Treina a equipe para cumprir os requisitos socioambientais. Prepara a propriedade para auditorias de certificação. Tem equipe treinada e equipamentos revisados. Especialidades: Certifica Minas Café, boas práticas agrícolas, orgânico, Rainforest Alliance. Atende e envia para todo o Brasil. Preço médio: R$ 11.000,00 por projeto. Avaliação média 4,7 de 5 (29 avaliações). Disponibilidade: imediata. Certificações/registros: Auditor líder certificado, CREA ativo.','Certifica Minas Café, boas práticas agrícolas, orgânico, Rainforest Alliance',4.7,29,11000.0,'projeto','Perdizes','MG','Cerrado Mineiro','nacional','Todo o Brasil',NULL,9,'Auditor líder certificado, CREA ativo','imediata','(34) 98096-7670',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(753,'servico','Planejamento e implantação da lavoura','Operador de máquinas para preparo de solo','Aparecida Araújo','pessoa_fisica','Aparecida Araújo atua como operador de máquinas para preparo de solo em São Sebastião do Paraíso/MG, na região Sul de Minas, com 5 anos de experiência. Aplica calcário e gesso a lanço antes do plantio. Faz sulcamento e abertura de covas para implantação de lavouras novas. Tem referências de produtores da região. Especialidades: gradagem, abertura de covas, calagem e gessagem. Atende produtores em São Sebastião do Paraíso, Nova Resende, num raio de até 20 km. Preço médio: R$ 250,00 por hora-máquina. Avaliação média 4,3 de 5 (30 avaliações). Disponibilidade: imediata. Certificações/registros: CNH categoria C, Curso de operador de máquinas agrícolas.','gradagem, abertura de covas, calagem e gessagem',4.3,30,250.0,'hora-máquina','São Sebastião do Paraíso','MG','Sul de Minas','local','São Sebastião do Paraíso, Nova Resende',20,5,'CNH categoria C, Curso de operador de máquinas agrícolas','imediata','(35) 98155-6580',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(754,'servico','Planejamento e implantação da lavoura','Engenheiro agrônomo','Mariana Rocha Nascimento','pessoa_fisica','Mariana Rocha Nascimento atua como engenheiro(a) agrônomo(a) em cafeicultura em Alta Floresta D''Oeste/RO, na região Matas de Rondônia, com 8 anos de experiência. Orienta a escolha de cultivares, espaçamento e densidade de plantio. Acompanha a lavoura com visitas periódicas e emite receituário agronômico. Segue as boas práticas exigidas por certificadoras. Aceita pagamento via Pix, transferência ou parcelado até a colheita. Tem experiência com café conilon/robusta. Especialidades: implantação de lavouras, manejo de pragas e doenças, renovação de lavouras, cafés especiais. Atende toda a região Matas de Rondônia (Cacoal, Ministro Andreazza, Alta Floresta D''Oeste, Rolim de Moura, Nova Brasilândia D''Oeste, São Miguel do Guaporé), num raio de até 200 km da sede. Preço médio: R$ 455,00 por visita técnica. Avaliação média 4,8 de 5 (11 avaliações). Disponibilidade: sob agendamento. Certificações/registros: Credenciado ATER, CREA ativo, Pós-graduação em cafeicultura.','implantação de lavouras, manejo de pragas e doenças, renovação de lavouras, cafés especiais',4.8,11,455.0,'visita técnica','Alta Floresta D''Oeste','RO','Matas de Rondônia','regional','Cacoal, Ministro Andreazza, Alta Floresta D''Oeste, Rolim de Moura, Nova Brasilândia D''Oeste, São Miguel do Guaporé',200,8,'Credenciado ATER, CREA ativo, Pós-graduação em cafeicultura','sob agendamento','(69) 98565-7798',1,'2026-09-24 20:42:33');
