INSERT INTO "fornecedores" VALUES(790,'produto','Colheita e armazenagem (materiais)','Sacaria','Santa Clara Sacaria','empresa','Santa Clara Sacaria é uma empresa sediada em Nova Venécia/ES, na região Norte do Espírito Santo, no mercado há 16 anos. Segmento: Sacaria. Faz sacaria personalizada com a marca da fazenda. Vende sacos de juta e ráfia para café beneficiado. Tem experiência com café conilon/robusta. Especialidades: sacos de ráfia, sacos de juta, sacaria personalizada. Atende e envia para todo o Brasil. Preço médio: R$ 9,84 por unidade. Avaliação média 4,8 de 5 (385 avaliações). Disponibilidade: sob encomenda.','sacos de ráfia, sacos de juta, sacaria personalizada',4.8,385,9.84,'unidade','Nova Venécia','ES','Norte do Espírito Santo','nacional','Todo o Brasil',NULL,16,NULL,'sob encomenda','(27) 99813-1871',0,'2026-09-24 20:42:33');
