INSERT INTO "fornecedores" VALUES(792,'produto','Máquinas e implementos','Revenda de colhedoras de café','Martins Máquinas para Café','empresa','Martins Máquinas para Café é uma empresa sediada em Ituaçu/BA, na região Chapada Diamantina, no mercado há 17 anos. Segmento: Revenda de colhedoras de café. Trabalha com consórcio e financiamento. Tem equipe de pós-venda e treinamento de operador. Especialidades: colhedora tracionada, colhedora automotriz. Atende toda a região Chapada Diamantina (Piatã, Mucugê, Ibicoara, Barra da Estiva, Abaíra, Ituaçu), num raio de até 150 km da sede. Preço médio: R$ 1.347.000,00 por unidade. Avaliação média 4,4 de 5 (80 avaliações). Disponibilidade: pronta entrega.','colhedora tracionada, colhedora automotriz',4.4,80,1347000.0,'unidade','Ituaçu','BA','Chapada Diamantina','regional','Piatã, Mucugê, Ibicoara, Barra da Estiva, Abaíra, Ituaçu',150,17,NULL,'pronta entrega','(75) 99302-9467',1,'2026-09-24 20:42:33');
