INSERT INTO "fornecedores" VALUES(803,'produto','Pós-colheita e beneficiamento (equipamentos)','Secadores de café','Barbosa Equipamentos para Café','empresa','Barbosa Equipamentos para Café é uma empresa sediada em São Gotardo/MG, na região Cerrado Mineiro, no mercado há 12 anos. Segmento: Secadores de café. Oferece assistência técnica e peças. Fabrica e instala secadores rotativos e de leito fixo. Atende de pequenos produtores a grandes fazendas. Especialidades: instalação, secador vertical, secador de leito fixo, secador rotativo. Atende e envia para todo o Brasil. Preço médio: R$ 214.000,00 por unidade. Avaliação média 5,0 de 5 (129 avaliações). Disponibilidade: pronta entrega.','instalação, secador vertical, secador de leito fixo, secador rotativo',5.0,129,214000.0,'unidade','São Gotardo','MG','Cerrado Mineiro','nacional','Todo o Brasil',NULL,12,NULL,'pronta entrega','(34) 98262-4921',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(804,'servico','Máquinas, estrutura e manutenção','Mecânico de máquinas agrícolas','Geraldo Silva','pessoa_fisica','Geraldo Silva atua como mecânico de máquinas agrícolas em Rio Paranaíba/MG, na região Cerrado Mineiro, com 5 anos de experiência. Atende emergências durante a safra. Faz manutenção de tratores e implementos com atendimento na propriedade. Agenda as visitas com antecedência e cumpre os prazos combinados. Atende pequenos, médios e grandes produtores. Especialidades: colhedoras, tratores, atendimento no campo. Atende produtores em Rio Paranaíba, Monte Carmelo, num raio de até 20 km. Preço médio: R$ 133,00 por hora. Avaliação média 4,8 de 5 (25 avaliações). Disponibilidade: sob agendamento.','colhedoras, tratores, atendimento no campo',4.8,25,133.0,'hora','Rio Paranaíba','MG','Cerrado Mineiro','local','Rio Paranaíba, Monte Carmelo',20,5,NULL,'sob agendamento','(34) 98723-3890',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(805,'servico','Qualidade e comercialização','Classificador de café','Café Forte Classificação de Café','empresa','Café Forte Classificação de Café é uma empresa sediada em Afonso Cláudio/ES, na região Montanhas do Espírito Santo, no mercado há 12 anos. Segmento: Classificador de café. Emite laudo de classificação para negociação do café. Faz a classificação por tipo, peneira e defeitos conforme a tabela oficial. Segue as boas práticas exigidas por certificadoras. Especialidades: contagem de defeitos, classificação por tipo, classificação oficial. Atende toda a região Montanhas do Espírito Santo (Venda Nova do Imigrante, Brejetuba, Iúna, Domingos Martins, Castelo, Afonso Cláudio, Conceição do Castelo, Ibatiba, Irupi, Muniz Freire), num raio de até 100 km da sede. Preço médio: R$ 38,13 por amostra. Avaliação média 4,8 de 5 (388 avaliações). Disponibilidade: imediata.','contagem de defeitos, classificação por tipo, classificação oficial',4.8,388,38.13,'amostra','Afonso Cláudio','ES','Montanhas do Espírito Santo','regional','Venda Nova do Imigrante, Brejetuba, Iúna, Domingos Martins, Castelo, Afonso Cláudio, Conceição do Castelo, Ibatiba, Irupi, Muniz Freire',100,12,NULL,'imediata','(28) 98100-8320',1,'2026-09-24 20:42:33');
