INSERT INTO "fornecedores" VALUES(814,'servico','Manejo e tratos culturais','Piloto de drone agrícola','Mateus Ribeiro Moreira','pessoa_fisica','Mateus Ribeiro Moreira atua como piloto de drone agrícola em Abaíra/BA, na região Chapada Diamantina, com 34 anos de experiência. Realiza aplicações rápidas com baixo volume de calda. Gera mapas de vigor (NDVI) para identificar falhas e reboleiras de pragas. Especialidades: contagem de plantas, pulverização com drone, NDVI. Atende toda a região Chapada Diamantina (Piatã, Mucugê, Ibicoara, Barra da Estiva, Abaíra, Ituaçu), num raio de até 200 km da sede. Preço médio: R$ 109,00 por hectare. Avaliação média 4,6 de 5 (17 avaliações). Disponibilidade: sob agendamento. Certificações/registros: Cadastro ANAC/DECEA.','contagem de plantas, pulverização com drone, NDVI',4.6,17,109.0,'hectare','Abaíra','BA','Chapada Diamantina','regional','Piatã, Mucugê, Ibicoara, Barra da Estiva, Abaíra, Ituaçu',200,34,'Cadastro ANAC/DECEA','sob agendamento','(75) 99230-3338',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(815,'servico','Qualidade e comercialização','Torrefação por encomenda','Martins Torrefação','empresa','Martins Torrefação é uma empresa sediada em Conceição do Castelo/ES, na região Montanhas do Espírito Santo, no mercado há 11 anos. Segmento: Torrefação por encomenda. Torra o café do produtor para ele vender com marca própria. Desenvolve perfis de torra de acordo com o lote. Tem equipe treinada e equipamentos revisados. Especialidades: torra sob encomenda, embalagem com válvula, perfis de torra, marca própria. Atende e envia para todo o Brasil. Preço médio: R$ 17,27 por kg torrado. Avaliação média 3,7 de 5 (128 avaliações). Disponibilidade: imediata.','torra sob encomenda, embalagem com válvula, perfis de torra, marca própria',3.7,128,17.27,'kg torrado','Conceição do Castelo','ES','Montanhas do Espírito Santo','nacional','Todo o Brasil',NULL,11,NULL,'imediata','(28) 99797-8695',1,'2026-09-24 20:42:33');
