INSERT INTO "fornecedores" VALUES(873,'produto','Tecnologia e comercialização','Equipamentos de classificação e prova','Nascimento Laboratório de Café','empresa','Nascimento Laboratório de Café é uma empresa sediada em Patrocínio/MG, na região Cerrado Mineiro, no mercado há 9 anos. Segmento: Equipamentos de classificação e prova. Monta salas de prova para fazendas e cooperativas. Oferece treinamento básico de classificação. Trabalha com marcas reconhecidas e garantia de fábrica. Especialidades: mini torrador, kit de classificação. Atende e envia para todo o Brasil. Preço médio: R$ 2.040,00 por unidade. Avaliação média 5,0 de 5 (85 avaliações). Disponibilidade: sob encomenda.','mini torrador, kit de classificação',5.0,85,2040.0,'unidade','Patrocínio','MG','Cerrado Mineiro','nacional','Todo o Brasil',NULL,9,NULL,'sob encomenda','(34) 98261-4801',1,'2026-09-24 20:42:33');
