INSERT INTO "fornecedores" VALUES(922,'produto','Máquinas e implementos','Peças para máquinas agrícolas','Cafeeiro Peças Agrícolas','empresa','Cafeeiro Peças Agrícolas é uma empresa sediada em Muniz Freire/ES, na região Montanhas do Espírito Santo, no mercado há 34 anos. Segmento: Peças para máquinas agrícolas. Monta mangueiras hidráulicas na hora. Faz entrega rápida na safra. Emite nota fiscal e entrega na propriedade. Dá desconto em compras de volume e para cooperados. Especialidades: peças de colhedora, correias, mangueiras hidráulicas. Atende toda a região Montanhas do Espírito Santo (Venda Nova do Imigrante, Brejetuba, Iúna, Domingos Martins, Castelo, Afonso Cláudio, Conceição do Castelo, Ibatiba, Irupi, Muniz Freire), num raio de até 100 km da sede. Preço médio: R$ 765,00 por ticket médio. Avaliação média 4,3 de 5 (109 avaliações). Disponibilidade: sob encomenda.','peças de colhedora, correias, mangueiras hidráulicas',4.3,109,765.0,'ticket médio','Muniz Freire','ES','Montanhas do Espírito Santo','regional','Venda Nova do Imigrante, Brejetuba, Iúna, Domingos Martins, Castelo, Afonso Cláudio, Conceição do Castelo, Ibatiba, Irupi, Muniz Freire',100,34,NULL,'sob encomenda','(28) 98441-5157',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(923,'servico','Colheita','Empreiteiro de mão de obra rural','Junqueira Serviços Rurais','empresa','Junqueira Serviços Rurais é uma empresa sediada em Simonésia/MG, na região Matas de Minas, no mercado há 7 anos. Segmento: Empreiteiro de mão de obra rural. Atende pedidos de turmas grandes no pico da safra. Fornece turmas completas de colheita com transporte e registro em carteira. Especialidades: alojamento e transporte, mão de obra registrada, turma de colheita. Atende toda a região Matas de Minas (Manhuaçu, Viçosa, Caratinga, Espera Feliz, Simonésia, Manhumirim, Carangola, Alto Jequitibá, Lajinha, Luisburgo), num raio de até 200 km da sede. Preço médio: R$ 163,00 por diária por trabalhador. Avaliação média 3,1 de 5 (293 avaliações). Disponibilidade: agenda cheia até o fim da safra. Certificações/registros: NR-31, Empresa com CNPJ e mão de obra registrada.','alojamento e transporte, mão de obra registrada, turma de colheita',3.1,293,163.0,'diária por trabalhador','Simonésia','MG','Matas de Minas','regional','Manhuaçu, Viçosa, Caratinga, Espera Feliz, Simonésia, Manhumirim, Carangola, Alto Jequitibá, Lajinha, Luisburgo',200,7,'NR-31, Empresa com CNPJ e mão de obra registrada','agenda cheia até o fim da safra','(33) 99655-1175',1,'2026-09-24 20:42:33');
