INSERT INTO "fornecedores" VALUES(1181,'produto','Tecnologia e comercialização','Equipamentos de classificação e prova','Rocha Laboratório de Café','empresa','Rocha Laboratório de Café é uma empresa sediada em Pedregulho/SP, na região Mogiana, no mercado há 9 anos. Segmento: Equipamentos de classificação e prova. Monta salas de prova para fazendas e cooperativas. Vende peneiras, mesas de prova e mini torradores para amostra. Parcela no cartão ou aceita pagamento na safra. Especialidades: kit de classificação, peneiras de classificação, mesa de prova, mini torrador. Atende e envia para todo o Brasil. Preço médio: R$ 9.280,00 por unidade. Avaliação média 4,5 de 5 (179 avaliações). Disponibilidade: sob encomenda.','kit de classificação, peneiras de classificação, mesa de prova, mini torrador',4.5,179,9280.0,'unidade','Pedregulho','SP','Mogiana','nacional','Todo o Brasil',NULL,9,NULL,'sob encomenda','(16) 99857-2737',1,'2026-09-24 20:42:33');
