INSERT INTO "fornecedores" VALUES(1183,'produto','Irrigação e infraestrutura','Materiais para construção rural','Araújo Materiais Rurais','empresa','Araújo Materiais Rurais é uma empresa sediada em Brejetuba/ES, na região Montanhas do Espírito Santo, no mercado há 21 anos. Segmento: Materiais para construção rural. Faz entrega na propriedade. Vende materiais para terreiros, tulhas e galpões. Faz orçamento rápido pela plataforma. Especialidades: madeira, cimento. Atende toda a região Montanhas do Espírito Santo (Venda Nova do Imigrante, Brejetuba, Iúna, Domingos Martins, Castelo, Afonso Cláudio, Conceição do Castelo, Ibatiba, Irupi, Muniz Freire), num raio de até 200 km da sede. Preço médio: R$ 11.000,00 por ticket médio. Avaliação média 3,0 de 5 (203 avaliações). Disponibilidade: pronta entrega.','madeira, cimento',3.0,203,11000.0,'ticket médio','Brejetuba','ES','Montanhas do Espírito Santo','regional','Venda Nova do Imigrante, Brejetuba, Iúna, Domingos Martins, Castelo, Afonso Cláudio, Conceição do Castelo, Ibatiba, Irupi, Muniz Freire',200,21,NULL,'pronta entrega','(28) 98896-1439',0,'2026-09-24 20:42:33');
