INSERT INTO "fornecedores" VALUES(1212,'produto','Insumos agrícolas','Fertilizantes foliares e micronutrientes','Rocha Foliares','empresa','Rocha Foliares é uma empresa sediada em Bom Sucesso/MG, na região Campo das Vertentes, no mercado há 10 anos. Segmento: Fertilizantes foliares e micronutrientes. Oferece bioestimulantes para pré-florada e enchimento de grãos. Tem técnico para acompanhar os resultados. Dá desconto em compras de volume e para cooperados. Especialidades: aminoácidos, bioestimulantes, boro. Atende toda a região Campo das Vertentes (Lavras, Perdões, Bom Sucesso, Ijaci, Santo Antônio do Amparo, Itumirim, Ingaí), num raio de até 200 km da sede. Preço médio: R$ 102,00 por litro. Avaliação média 4,5 de 5 (344 avaliações). Disponibilidade: pronta entrega.','aminoácidos, bioestimulantes, boro',4.5,344,102.0,'litro','Bom Sucesso','MG','Campo das Vertentes','regional','Lavras, Perdões, Bom Sucesso, Ijaci, Santo Antônio do Amparo, Itumirim, Ingaí',200,10,NULL,'pronta entrega','(35) 99960-1052',1,'2026-09-24 20:42:33');
