INSERT INTO "fornecedores" VALUES(1329,'produto','Irrigação e infraestrutura','Sistemas de irrigação','Catuaí Irrigação','empresa','Catuaí Irrigação é uma empresa sediada em Araguari/MG, na região Cerrado Mineiro, no mercado há 37 anos. Segmento: Sistemas de irrigação. Tem bombas, filtros e automação de irrigação. Vende e instala sistemas de gotejamento para café. Atende de pequenos produtores a grandes fazendas. Trabalha com marcas reconhecidas e garantia de fábrica. Especialidades: tubos gotejadores, fertirrigação, bombas, filtros. Atende toda a região Cerrado Mineiro (Patrocínio, Araguari, Monte Carmelo, Patos de Minas, Carmo do Paranaíba, Serra do Salitre, Campos Altos, Coromandel, Rio Paranaíba, Ibiá, Perdizes, Estrela do Sul, São Gotardo), num raio de até 100 km da sede. Preço médio: R$ 15.000,00 por hectare. Avaliação média 4,4 de 5 (145 avaliações). Disponibilidade: sob encomenda.','tubos gotejadores, fertirrigação, bombas, filtros',4.4,145,15000.0,'hectare','Araguari','MG','Cerrado Mineiro','regional','Patrocínio, Araguari, Monte Carmelo, Patos de Minas, Carmo do Paranaíba, Serra do Salitre, Campos Altos, Coromandel, Rio Paranaíba, Ibiá, Perdizes, Estrela do Sul, São Gotardo',100,37,NULL,'sob encomenda','(34) 99083-3045',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(1330,'produto','Tecnologia e comercialização','Equipamentos de classificação e prova','Nova Safra Equipamentos de Prova','empresa','Nova Safra Equipamentos de Prova é uma empresa sediada em Iúna/ES, na região Montanhas do Espírito Santo, no mercado há 36 anos. Segmento: Equipamentos de classificação e prova. Vende peneiras, mesas de prova e mini torradores para amostra. Monta salas de prova para fazendas e cooperativas. Dá desconto em compras de volume e para cooperados. Emite nota fiscal e entrega na propriedade. Especialidades: mesa de prova, moedor de prova, mini torrador, peneiras de classificação. Atende e envia para todo o Brasil. Preço médio: R$ 7.530,00 por unidade. Avaliação média 3,7 de 5 (184 avaliações). Disponibilidade: sob encomenda.','mesa de prova, moedor de prova, mini torrador, peneiras de classificação',3.7,184,7530.0,'unidade','Iúna','ES','Montanhas do Espírito Santo','nacional','Todo o Brasil',NULL,36,NULL,'sob encomenda','(28) 98839-9352',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(1331,'produto','Irrigação e infraestrutura','Materiais para construção rural','Mendes Materiais Rurais','empresa','Mendes Materiais Rurais é uma empresa sediada em São Miguel do Guaporé/RO, na região Matas de Rondônia, no mercado há 22 anos. Segmento: Materiais para construção rural. Tem arame, mourões e material para cercas. Faz entrega na propriedade. Oferece condições especiais antes da safra. Parcela no cartão ou aceita pagamento na safra. Tem experiência com café conilon/robusta. Especialidades: estruturas metálicas, telhas, arame e mourões. Atende produtores em São Miguel do Guaporé, Cacoal, Rolim de Moura, Alta Floresta D''Oeste, num raio de até 60 km. Preço médio: R$ 6.610,00 por ticket médio. Avaliação média 5,0 de 5 (121 avaliações). Disponibilidade: estoque limitado.','estruturas metálicas, telhas, arame e mourões',5.0,121,6610.0,'ticket médio','São Miguel do Guaporé','RO','Matas de Rondônia','local','São Miguel do Guaporé, Cacoal, Rolim de Moura, Alta Floresta D''Oeste',60,22,NULL,'estoque limitado','(69) 99386-1638',1,'2026-09-24 20:42:33');
