INSERT INTO "fornecedores" VALUES(1355,'produto','Irrigação e infraestrutura','Energia solar rural','Sítio Novo Solar','empresa','Sítio Novo Solar é uma empresa sediada em Patrocínio Paulista/SP, na região Mogiana, no mercado há 12 anos. Segmento: Energia solar rural. Faz o projeto e a homologação junto à distribuidora. Trabalha com linhas de financiamento rural. Trabalha com marcas reconhecidas e garantia de fábrica. Especialidades: bombeamento solar, homologação. Atende toda a região Mogiana (Franca, Pedregulho, Cristais Paulista, Altinópolis, Espírito Santo do Pinhal, Caconde, Ribeirão Corrente, Jeriquara, Patrocínio Paulista, Itirapuã, São Sebastião da Grama, Mococa), num raio de até 200 km da sede. Preço médio: R$ 5.080,00 por kWp. Avaliação média 4,8 de 5 (289 avaliações). Disponibilidade: pronta entrega.','bombeamento solar, homologação',4.8,289,5080.0,'kWp','Patrocínio Paulista','SP','Mogiana','regional','Franca, Pedregulho, Cristais Paulista, Altinópolis, Espírito Santo do Pinhal, Caconde, Ribeirão Corrente, Jeriquara, Patrocínio Paulista, Itirapuã, São Sebastião da Grama, Mococa',200,12,NULL,'pronta entrega','(16) 98875-9873',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(1356,'produto','Pós-colheita e beneficiamento (equipamentos)','Máquinas de beneficiamento','Brandão Máquinas de Beneficiamento','empresa','Brandão Máquinas de Beneficiamento é uma empresa sediada em Castelo/ES, na região Montanhas do Espírito Santo, no mercado há 31 anos. Segmento: Máquinas de beneficiamento. Vende linhas completas de beneficiamento para fazendas e armazéns. Tem catadoras eletrônicas e mesas densimétricas. Tem assistência técnica e pós-venda. Oferece condições especiais antes da safra. Especialidades: descascador de café seco, elevadores, peneira classificadora. Atende e envia para todo o Brasil. Preço médio: R$ 135.000,00 por unidade. Avaliação média 3,3 de 5 (213 avaliações). Disponibilidade: pronta entrega.','descascador de café seco, elevadores, peneira classificadora',3.3,213,135000.0,'unidade','Castelo','ES','Montanhas do Espírito Santo','nacional','Todo o Brasil',NULL,31,NULL,'pronta entrega','(28) 99094-6597',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(1357,'servico','Máquinas, estrutura e manutenção','Mecânico de máquinas agrícolas','Oliveira Mecânica Agrícola','empresa','Oliveira Mecânica Agrícola é uma empresa sediada em Muniz Freire/ES, na região Montanhas do Espírito Santo, no mercado há 32 anos. Segmento: Mecânico de máquinas agrícolas. Faz manutenção de tratores e implementos com atendimento na propriedade. Atende emergências durante a safra. Especialidades: colhedoras, sistema hidráulico. Atende produtores em Muniz Freire, Venda Nova do Imigrante, num raio de até 20 km. Preço médio: R$ 97,00 por hora. Avaliação média 4,9 de 5 (325 avaliações). Disponibilidade: sob agendamento.','colhedoras, sistema hidráulico',4.9,325,97.0,'hora','Muniz Freire','ES','Montanhas do Espírito Santo','local','Muniz Freire, Venda Nova do Imigrante',20,32,NULL,'sob agendamento','(28) 98762-8682',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(1358,'servico','Manejo e tratos culturais','Aplicador de defensivos','Fernando Ribeiro','pessoa_fisica','Fernando Ribeiro atua como aplicador de defensivos agrícolas em Patrocínio Paulista/SP, na região Mogiana, com 13 anos de experiência. Faz aplicação tratorizada com turbo-atomizador e aplicação costal em áreas declivosas. Trabalha com EPI completo e respeita intervalo de reentrada e carência. Faz orçamento sem compromisso na propriedade. Acostumado a lavouras planas e altamente mecanizadas. Especialidades: pulverização com turbo-atomizador, aplicação foliar. Atende produtores em Patrocínio Paulista, Jeriquara, num raio de até 30 km. Preço médio: R$ 171,00 por hectare. Avaliação média 4,3 de 5 (27 avaliações). Disponibilidade: sob agendamento. Certificações/registros: Curso de aplicação segura de agrotóxicos, NR-31.','pulverização com turbo-atomizador, aplicação foliar',4.3,27,171.0,'hectare','Patrocínio Paulista','SP','Mogiana','local','Patrocínio Paulista, Jeriquara',30,13,'Curso de aplicação segura de agrotóxicos, NR-31','sob agendamento','(16) 99130-6343',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(1359,'produto','Tecnologia e comercialização','Estações meteorológicas e sensores','ClimaCachoeira','empresa','ClimaCachoeira é uma empresa sediada em Três Pontas/MG, na região Sul de Minas, no mercado há 32 anos. Segmento: Estações meteorológicas e sensores. Vende estações meteorológicas conectadas ao celular. Tem sensores de umidade do solo para manejo de irrigação. Especialidades: pluviômetro digital, estação meteorológica, alerta de geada. Atende e envia para todo o Brasil. Preço médio: R$ 3.160,00 por unidade. Avaliação média 4,9 de 5 (81 avaliações). Disponibilidade: pronta entrega.','pluviômetro digital, estação meteorológica, alerta de geada',4.9,81,3160.0,'unidade','Três Pontas','MG','Sul de Minas','nacional','Todo o Brasil',NULL,32,NULL,'pronta entrega','(35) 99125-8467',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(1360,'produto','Máquinas e implementos','Revenda de colhedoras de café','Araújo Máquinas para Café','empresa','Araújo Máquinas para Café é uma empresa sediada em Espírito Santo do Pinhal/SP, na região Mogiana, no mercado há 2 anos. Segmento: Revenda de colhedoras de café. Vende colhedoras automotrizes e tracionadas para café. Trabalha com consórcio e financiamento. Acostumado a lavouras planas e altamente mecanizadas. Especialidades: recolhedora, colhedoras seminovas, colhedora automotriz. Atende toda a região Mogiana (Franca, Pedregulho, Cristais Paulista, Altinópolis, Espírito Santo do Pinhal, Caconde, Ribeirão Corrente, Jeriquara, Patrocínio Paulista, Itirapuã, São Sebastião da Grama, Mococa), num raio de até 80 km da sede. Preço médio: R$ 1.855.000,00 por unidade. Avaliação média 4,6 de 5 (283 avaliações). Disponibilidade: sob encomenda.','recolhedora, colhedoras seminovas, colhedora automotriz',4.6,283,1855000.0,'unidade','Espírito Santo do Pinhal','SP','Mogiana','regional','Franca, Pedregulho, Cristais Paulista, Altinópolis, Espírito Santo do Pinhal, Caconde, Ribeirão Corrente, Jeriquara, Patrocínio Paulista, Itirapuã, São Sebastião da Grama, Mococa',80,2,NULL,'sob encomenda','(16) 98583-6431',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(1361,'servico','Manejo e tratos culturais','Aplicador de defensivos','Chapadão Aplicações Agrícolas','empresa','Chapadão Aplicações Agrícolas é uma empresa sediada em Piatã/BA, na região Chapada Diamantina, no mercado há 16 anos. Segmento: Aplicador de defensivos. Faz aplicação tratorizada com turbo-atomizador e aplicação costal em áreas declivosas. Trabalha com EPI completo e respeita intervalo de reentrada e carência. Prioriza atendimento a propriedades familiares. Segue as boas práticas exigidas por certificadoras. Especialidades: controle de broca, aplicação foliar, controle de ferrugem, pulverização com turbo-atomizador. Atende toda a região Chapada Diamantina (Piatã, Mucugê, Ibicoara, Barra da Estiva, Abaíra, Ituaçu), num raio de até 120 km da sede. Preço médio: R$ 125,00 por hectare. Avaliação média 3,8 de 5 (344 avaliações). Disponibilidade: imediata.','controle de broca, aplicação foliar, controle de ferrugem, pulverização com turbo-atomizador',3.8,344,125.0,'hectare','Piatã','BA','Chapada Diamantina','regional','Piatã, Mucugê, Ibicoara, Barra da Estiva, Abaíra, Ituaçu',120,16,NULL,'imediata','(75) 98826-7755',0,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(1362,'servico','Colheita','Transportador de café','Bela Vista Logística Rural','empresa','Bela Vista Logística Rural é uma empresa sediada em Ibatiba/ES, na região Montanhas do Espírito Santo, no mercado há 19 anos. Segmento: Transportador de café. Faz o transporte do café da lavoura até o terreiro ou secador. Leva café beneficiado até armazéns e cooperativas. Segue as boas práticas exigidas por certificadoras. Especialidades: caminhão basculante, transporte de café em big bag, frete lavoura-terreiro, carreta. Atende toda a região Montanhas do Espírito Santo (Venda Nova do Imigrante, Brejetuba, Iúna, Domingos Martins, Castelo, Afonso Cláudio, Conceição do Castelo, Ibatiba, Irupi, Muniz Freire), num raio de até 100 km da sede. Preço médio: R$ 543,00 por viagem. Avaliação média 3,6 de 5 (301 avaliações). Disponibilidade: sob agendamento. Certificações/registros: CNH categoria E.','caminhão basculante, transporte de café em big bag, frete lavoura-terreiro, carreta',3.6,301,543.0,'viagem','Ibatiba','ES','Montanhas do Espírito Santo','regional','Venda Nova do Imigrante, Brejetuba, Iúna, Domingos Martins, Castelo, Afonso Cláudio, Conceição do Castelo, Ibatiba, Irupi, Muniz Freire',100,19,'CNH categoria E','sob agendamento','(28) 98744-5696',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(1363,'servico','Máquinas, estrutura e manutenção','Construtor de terreiros e tulhas','Terra Boa Construtora Rural','empresa','Terra Boa Construtora Rural é uma empresa sediada em Patos de Minas/MG, na região Cerrado Mineiro, no mercado há 41 anos. Segmento: Construtor de terreiros e tulhas. Constrói terreiros de concreto com caimento correto e drenagem. Monta terreiros suspensos para cafés especiais. Faz orçamento sem compromisso na propriedade. Especialidades: terreiro suspenso, terreiro de concreto, barracões. Atende produtores em Patos de Minas, Araguari, Carmo do Paranaíba, Coromandel, num raio de até 50 km. Preço médio: R$ 97,00 por m². Avaliação média 5,0 de 5 (72 avaliações). Disponibilidade: sob agendamento.','terreiro suspenso, terreiro de concreto, barracões',5.0,72,97.0,'m²','Patos de Minas','MG','Cerrado Mineiro','local','Patos de Minas, Araguari, Carmo do Paranaíba, Coromandel',50,41,NULL,'sob agendamento','(34) 99072-8747',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(1364,'servico','Máquinas, estrutura e manutenção','Soldador e serralheiro rural','Geraldo Vilela Oliveira','pessoa_fisica','Geraldo Vilela Oliveira atua como soldador e serralheiro em Bom Sucesso/MG, na região Campo das Vertentes, com 4 anos de experiência. Fabrica estruturas metálicas para galpões e terreiros suspensos. Atende na propriedade com máquina de solda portátil. Prioriza atendimento a propriedades familiares. Segue as boas práticas exigidas por certificadoras. Especialidades: solda de implementos, portões e cercas. Atende produtores em Bom Sucesso, Ingaí, num raio de até 20 km. Preço médio: R$ 92,00 por hora. Avaliação média 4,5 de 5 (7 avaliações). Disponibilidade: imediata.','solda de implementos, portões e cercas',4.5,7,92.0,'hora','Bom Sucesso','MG','Campo das Vertentes','local','Bom Sucesso, Ingaí',20,4,NULL,'imediata','(35) 99208-6702',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(1365,'servico','Máquinas, estrutura e manutenção','Eletricista rural','Aparecida Ribeiro','pessoa_fisica','Aparecida Ribeiro atua como eletricista rural em Nepomuceno/MG, na região Sul de Minas, com 27 anos de experiência. Faz manutenção preventiva antes da safra. Monta quadros de comando para motores. Especialidades: bombas de irrigação, instalação de secadores, quadros de comando, motores elétricos. Atende produtores em Nepomuceno, Boa Esperança, Varginha, Três Corações, num raio de até 40 km. Preço médio: R$ 107,00 por hora. Avaliação média 4,6 de 5 (39 avaliações). Disponibilidade: imediata. Certificações/registros: NR-10.','bombas de irrigação, instalação de secadores, quadros de comando, motores elétricos',4.6,39,107.0,'hora','Nepomuceno','MG','Sul de Minas','local','Nepomuceno, Boa Esperança, Varginha, Três Corações',40,27,'NR-10','imediata','(35) 98676-2686',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(1366,'produto','Insumos agrícolas','Adubos orgânicos','Rosângela Figueiredo','pessoa_fisica','Rosângela Figueiredo atua como produtor(a) e vendedor(a) de adubos orgânicos em São Desidério/BA, na região Oeste da Bahia, com 4 anos de experiência. Fornece material para lavouras orgânicas e convencionais. Vende cama de frango, esterco curtido e composto orgânico. Especialidades: palha de café, composto orgânico. Atende produtores em São Desidério, Barreiras, Luís Eduardo Magalhães, num raio de até 30 km. Preço médio: R$ 464,00 por tonelada. Avaliação média 3,8 de 5 (5 avaliações). Disponibilidade: pronta entrega.','palha de café, composto orgânico',3.8,5,464.0,'tonelada','São Desidério','BA','Oeste da Bahia','local','São Desidério, Barreiras, Luís Eduardo Magalhães',30,4,NULL,'pronta entrega','(77) 98111-3557',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(1367,'produto','Pós-colheita e beneficiamento (equipamentos)','Lonas para terreiro e secagem','Grão Nobre Lonas','empresa','Grão Nobre Lonas é uma empresa sediada em Venda Nova do Imigrante/ES, na região Montanhas do Espírito Santo, no mercado há 23 anos. Segmento: Lonas para terreiro e secagem. Faz lonas sob medida com ilhós. Vende lonas para secagem e cobertura do café no terreiro. Especialidades: lona sob medida, lona para cobertura. Atende e envia para todo o Brasil. Preço médio: R$ 10,80 por m². Avaliação média 3,6 de 5 (279 avaliações). Disponibilidade: pronta entrega.','lona sob medida, lona para cobertura',3.6,279,10.8,'m²','Venda Nova do Imigrante','ES','Montanhas do Espírito Santo','nacional','Todo o Brasil',NULL,23,NULL,'pronta entrega','(28) 99579-5512',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(1368,'servico','Colheita','Colhedor manual','Thiago Bernardes','pessoa_fisica','Thiago Bernardes atua como colhedor de café em Manhuaçu/MG, na região Matas de Minas, com 21 anos de experiência. Faz catação e varrição do café do chão após a colheita. Trabalha na derriça no pano e na colheita seletiva de cereja madura. Segue as boas práticas exigidas por certificadoras. Aceita pagamento via Pix, transferência ou parcelado até a colheita. Especialidades: derriça no pano, catação, varrição. Atende produtores em Manhuaçu, Luisburgo, Manhumirim, Simonésia, num raio de até 50 km. Preço médio: R$ 37,75 por medida de 60 L. Avaliação média 4,6 de 5 (15 avaliações). Disponibilidade: sob agendamento. Certificações/registros: NR-31.','derriça no pano, catação, varrição',4.6,15,37.75,'medida de 60 L','Manhuaçu','MG','Matas de Minas','local','Manhuaçu, Luisburgo, Manhumirim, Simonésia',50,21,'NR-31','sob agendamento','(33) 98172-1605',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(1369,'produto','Colheita e armazenagem (materiais)','Panos e ferramentas de colheita','Vista Alegre Artigos Rurais','empresa','Vista Alegre Artigos Rurais é uma empresa sediada em Ijaci/MG, na região Campo das Vertentes, no mercado há 34 anos. Segmento: Panos e ferramentas de colheita. Tem kits completos para turmas de colheita. Faz entrega antes da safra. Tem assistência técnica e pós-venda. Especialidades: pano de colheita, balaio. Atende toda a região Campo das Vertentes (Lavras, Perdões, Bom Sucesso, Ijaci, Santo Antônio do Amparo, Itumirim, Ingaí), num raio de até 120 km da sede. Preço médio: R$ 226,00 por unidade. Avaliação média 5,0 de 5 (353 avaliações). Disponibilidade: pronta entrega.','pano de colheita, balaio',5.0,353,226.0,'unidade','Ijaci','MG','Campo das Vertentes','regional','Lavras, Perdões, Bom Sucesso, Ijaci, Santo Antônio do Amparo, Itumirim, Ingaí',120,34,NULL,'pronta entrega','(35) 99119-6512',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(1370,'servico','Gestão, certificação e serviços de apoio','Consultor de gestão rural','Colheita Farta Gestão Rural','empresa','Colheita Farta Gestão Rural é uma empresa sediada em Paraguaçu/MG, na região Sul de Minas, no mercado há 27 anos. Segmento: Consultor de gestão rural. Apoia o planejamento de investimentos e a sucessão familiar. Levanta o custo de produção por saca e monta o fluxo de caixa da fazenda. Faz orçamento sem compromisso na propriedade. Emite nota fiscal e formaliza o serviço em contrato. Especialidades: fluxo de caixa, planejamento financeiro. Atende toda a região Sul de Minas (Varginha, Três Pontas, Guaxupé, Machado, Alfenas, Boa Esperança, Campos Gerais, Carmo de Minas, São Sebastião do Paraíso, Nepomuceno, Poços de Caldas, Nova Resende, Muzambinho, Cabo Verde, Monte Santo de Minas, Três Corações, Elói Mendes, Paraguaçu, Carmo do Rio Claro, Ilicínea, Santana da Vargem, Coqueiral, Cambuquira), num raio de até 200 km da sede. Preço médio: R$ 2.020,00 por mês. Avaliação média 4,4 de 5 (47 avaliações). Disponibilidade: sob agendamento.','fluxo de caixa, planejamento financeiro',4.4,47,2020.0,'mês','Paraguaçu','MG','Sul de Minas','regional','Varginha, Três Pontas, Guaxupé, Machado, Alfenas, Boa Esperança, Campos Gerais, Carmo de Minas, São Sebastião do Paraíso, Nepomuceno, Poços de Caldas, Nova Resende, Muzambinho, Cabo Verde, Monte Santo de Minas, Três Corações, Elói Mendes, Paraguaçu, Carmo do Rio Claro, Ilicínea, Santana da Vargem, Coqueiral, Cambuquira',200,27,NULL,'sob agendamento','(35) 98724-1206',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(1371,'produto','Máquinas e implementos','Derriçadeiras e roçadeiras portáteis','Horizonte Motopeças','empresa','Horizonte Motopeças é uma empresa sediada em Nova Brasilândia D''Oeste/RO, na região Matas de Rondônia, no mercado há 26 anos. Segmento: Derriçadeiras e roçadeiras portáteis. Faz revisão pré-safra das máquinas. Tem assistência técnica e peças de reposição na loja. Oferece condições especiais antes da safra. Tem experiência com café conilon/robusta. Especialidades: derriçadeira elétrica a bateria, derriçadeira a gasolina, assistência técnica. Atende toda a região Matas de Rondônia (Cacoal, Ministro Andreazza, Alta Floresta D''Oeste, Rolim de Moura, Nova Brasilândia D''Oeste, São Miguel do Guaporé), num raio de até 200 km da sede. Preço médio: R$ 2.340,00 por unidade. Avaliação média 4,7 de 5 (147 avaliações). Disponibilidade: estoque limitado.','derriçadeira elétrica a bateria, derriçadeira a gasolina, assistência técnica',4.7,147,2340.0,'unidade','Nova Brasilândia D''Oeste','RO','Matas de Rondônia','regional','Cacoal, Ministro Andreazza, Alta Floresta D''Oeste, Rolim de Moura, Nova Brasilândia D''Oeste, São Miguel do Guaporé',200,26,NULL,'estoque limitado','(69) 98876-9979',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(1372,'servico','Planejamento e implantação da lavoura','Engenheiro agrônomo','Cláudia Gomes Campos','pessoa_fisica','Cláudia Gomes Campos atua como engenheiro(a) agrônomo(a) em cafeicultura em Ijaci/MG, na região Campo das Vertentes, com 26 anos de experiência. Faz interpretação de análises de solo e foliar e monta o plano de adubação da safra. Ajuda a planejar a renovação de talhões improdutivos com análise de custo. Aceita pagamento via Pix, transferência ou parcelado até a colheita. Faz orçamento sem compromisso na propriedade. Especialidades: implantação de lavouras, renovação de lavouras. Atende toda a região Campo das Vertentes (Lavras, Perdões, Bom Sucesso, Ijaci, Santo Antônio do Amparo, Itumirim, Ingaí), num raio de até 150 km da sede. Preço médio: R$ 601,00 por visita técnica. Avaliação média 4,8 de 5 (38 avaliações). Disponibilidade: sob agendamento. Certificações/registros: CREA ativo, Credenciado ATER, Pós-graduação em cafeicultura.','implantação de lavouras, renovação de lavouras',4.8,38,601.0,'visita técnica','Ijaci','MG','Campo das Vertentes','regional','Lavras, Perdões, Bom Sucesso, Ijaci, Santo Antônio do Amparo, Itumirim, Ingaí',150,26,'CREA ativo, Credenciado ATER, Pós-graduação em cafeicultura','sob agendamento','(35) 99825-8251',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(1373,'servico','Manejo e tratos culturais','Consultor em manejo de pragas e doenças','Pedro Andrade','pessoa_fisica','Pedro Andrade atua como consultor em manejo integrado de pragas em Varginha/MG, na região Sul de Minas, com 20 anos de experiência. Implanta programas de manejo integrado de pragas (MIP) com uso de controle biológico. Faz monitoramento de bicho-mineiro, broca e ferrugem e define o momento certo de aplicar. Segue as boas práticas exigidas por certificadoras. Especialidades: nematoides, bicho-mineiro, MIP, cercosporiose. Atende toda a região Sul de Minas (Varginha, Três Pontas, Guaxupé, Machado, Alfenas, Boa Esperança, Campos Gerais, Carmo de Minas, São Sebastião do Paraíso, Nepomuceno, Poços de Caldas, Nova Resende, Muzambinho, Cabo Verde, Monte Santo de Minas, Três Corações, Elói Mendes, Paraguaçu, Carmo do Rio Claro, Ilicínea, Santana da Vargem, Coqueiral, Cambuquira), num raio de até 150 km da sede. Preço médio: R$ 517,00 por visita técnica. Avaliação média 4,7 de 5 (4 avaliações). Disponibilidade: agenda cheia até o fim da safra. Certificações/registros: Mestrado em fitopatologia.','nematoides, bicho-mineiro, MIP, cercosporiose',4.7,4,517.0,'visita técnica','Varginha','MG','Sul de Minas','regional','Varginha, Três Pontas, Guaxupé, Machado, Alfenas, Boa Esperança, Campos Gerais, Carmo de Minas, São Sebastião do Paraíso, Nepomuceno, Poços de Caldas, Nova Resende, Muzambinho, Cabo Verde, Monte Santo de Minas, Três Corações, Elói Mendes, Paraguaçu, Carmo do Rio Claro, Ilicínea, Santana da Vargem, Coqueiral, Cambuquira',150,20,'Mestrado em fitopatologia','agenda cheia até o fim da safra','(35) 98064-8051',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(1374,'servico','Gestão, certificação e serviços de apoio','Consultor de certificações','Fernando Silva','pessoa_fisica','Fernando Silva atua como consultor de certificações em Ibicoara/BA, na região Chapada Diamantina, com 8 anos de experiência. Prepara a propriedade para auditorias de certificação. Treina a equipe para cumprir os requisitos socioambientais. Tem referências de produtores da região. Especialidades: orgânico, boas práticas agrícolas. Atende e envia para todo o Brasil. Preço médio: R$ 9.290,00 por projeto. Avaliação média 4,3 de 5 (37 avaliações). Disponibilidade: imediata. Certificações/registros: Auditor líder certificado.','orgânico, boas práticas agrícolas',4.3,37,9290.0,'projeto','Ibicoara','BA','Chapada Diamantina','nacional','Todo o Brasil',NULL,8,'Auditor líder certificado','imediata','(75) 99256-2536',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(1375,'produto','Pós-colheita e beneficiamento (equipamentos)','Lavadores e despolpadores','Rio Verde Máquinas Pós-Colheita','empresa','Rio Verde Máquinas Pós-Colheita é uma empresa sediada em Santo Antônio do Amparo/MG, na região Campo das Vertentes, no mercado há 11 anos. Segmento: Lavadores e despolpadores. Tem tanques para fermentação controlada. Faz a instalação e treinamento do operador. Especialidades: tanques de fermentação, despolpador, lavador, descascador de cereja. Atende e envia para todo o Brasil. Preço médio: R$ 127.000,00 por unidade. Avaliação média 3,6 de 5 (85 avaliações). Disponibilidade: pronta entrega.','tanques de fermentação, despolpador, lavador, descascador de cereja',3.6,85,127000.0,'unidade','Santo Antônio do Amparo','MG','Campo das Vertentes','nacional','Todo o Brasil',NULL,11,NULL,'pronta entrega','(35) 99117-9577',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(1376,'servico','Planejamento e implantação da lavoura','Operador de máquinas para preparo de solo','Marcos Rodrigues','pessoa_fisica','Marcos Rodrigues atua como operador de máquinas para preparo de solo em Rio Bananal/ES, na região Norte do Espírito Santo, com 16 anos de experiência. Aplica calcário e gesso a lanço antes do plantio. Presta serviço com trator e implementos próprios para preparar a área de plantio. Tem equipe treinada e equipamentos revisados. Tem referências de produtores da região. Tem experiência com café conilon/robusta. Especialidades: calagem e gessagem, subsolagem, gradagem, abertura de covas. Atende produtores em Rio Bananal, Sooretama, Vila Valério, num raio de até 60 km. Preço médio: R$ 216,00 por hora-máquina. Avaliação média 4,7 de 5 (40 avaliações). Disponibilidade: sob agendamento. Certificações/registros: CNH categoria C.','calagem e gessagem, subsolagem, gradagem, abertura de covas',4.7,40,216.0,'hora-máquina','Rio Bananal','ES','Norte do Espírito Santo','local','Rio Bananal, Sooretama, Vila Valério',60,16,'CNH categoria C','sob agendamento','(27) 98452-8303',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(1377,'produto','Insumos agrícolas','Revenda de fertilizantes e corretivos','Dias Insumos Agrícolas','empresa','Dias Insumos Agrícolas é uma empresa sediada em Lajinha/MG, na região Matas de Minas, no mercado há 31 anos. Segmento: Revenda de fertilizantes e corretivos. Tem agrônomo para recomendação de adubação sem custo adicional. Oferece entrega na propriedade e condições de pagamento na safra. Faz orçamento rápido pela plataforma. Emite nota fiscal e entrega na propriedade. Especialidades: calcário, cloreto de potássio. Atende toda a região Matas de Minas (Manhuaçu, Viçosa, Caratinga, Espera Feliz, Simonésia, Manhumirim, Carangola, Alto Jequitibá, Lajinha, Luisburgo), num raio de até 100 km da sede. Preço médio: R$ 2.620,00 por tonelada. Avaliação média 3,6 de 5 (52 avaliações). Disponibilidade: pronta entrega.','calcário, cloreto de potássio',3.6,52,2620.0,'tonelada','Lajinha','MG','Matas de Minas','regional','Manhuaçu, Viçosa, Caratinga, Espera Feliz, Simonésia, Manhumirim, Carangola, Alto Jequitibá, Lajinha, Luisburgo',100,31,NULL,'pronta entrega','(33) 98522-5201',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(1378,'produto','Máquinas e implementos','Concessionária de tratores cafeeiros','Souza Máquinas Agrícolas','empresa','Souza Máquinas Agrícolas é uma empresa sediada em Cristais Paulista/SP, na região Mogiana, no mercado há 21 anos. Segmento: Concessionária de tratores cafeeiros. Auxilia no financiamento por linhas de crédito rural. Vende tratores estreitos próprios para as entrelinhas do café. Parcela no cartão ou aceita pagamento na safra. Acostumado a lavouras planas e altamente mecanizadas. Especialidades: tratores estreitos, tratores cafeeiros, financiamento. Atende toda a região Mogiana (Franca, Pedregulho, Cristais Paulista, Altinópolis, Espírito Santo do Pinhal, Caconde, Ribeirão Corrente, Jeriquara, Patrocínio Paulista, Itirapuã, São Sebastião da Grama, Mococa), num raio de até 80 km da sede. Preço médio: R$ 212.000,00 por unidade. Avaliação média 4,6 de 5 (333 avaliações). Disponibilidade: pronta entrega.','tratores estreitos, tratores cafeeiros, financiamento',4.6,333,212000.0,'unidade','Cristais Paulista','SP','Mogiana','regional','Franca, Pedregulho, Cristais Paulista, Altinópolis, Espírito Santo do Pinhal, Caconde, Ribeirão Corrente, Jeriquara, Patrocínio Paulista, Itirapuã, São Sebastião da Grama, Mococa',80,21,NULL,'pronta entrega','(16) 98279-8939',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(1379,'servico','Qualidade e comercialização','Q-Grader / provador de café','Pedro Almeida','pessoa_fisica','Pedro Almeida atua como provador de café (Q-Grader) em Alto Jequitibá/MG, na região Matas de Minas, com 24 anos de experiência. Faz a prova de xícara e pontua o café pelo protocolo SCA. Emite laudo sensorial com notas e descritores para venda de cafés especiais. Atende muitos produtores de cafés especiais da região. Especialidades: pontuação SCA, prova de xícara, preparação para concursos, cafés especiais. Atende e envia para todo o Brasil. Preço médio: R$ 280,00 por amostra. Avaliação média 4,4 de 5 (22 avaliações). Disponibilidade: agenda cheia até o fim da safra.','pontuação SCA, prova de xícara, preparação para concursos, cafés especiais',4.4,22,280.0,'amostra','Alto Jequitibá','MG','Matas de Minas','nacional','Todo o Brasil',NULL,24,NULL,'agenda cheia até o fim da safra','(33) 99398-3955',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(1380,'produto','EPI e ferramentas','Ferramentas manuais','Fazendinha Ferragens','empresa','Fazendinha Ferragens é uma empresa sediada em Barreiras/BA, na região Oeste da Bahia, no mercado há 26 anos. Segmento: Ferramentas manuais. Atende produtores e turmas de trabalho. Vende ferramentas para capina e poda. Emite nota fiscal e entrega na propriedade. Especialidades: foice, enxada, motosserra, tesoura de poda. Atende toda a região Oeste da Bahia (Luís Eduardo Magalhães, Barreiras, São Desidério), num raio de até 80 km da sede. Preço médio: R$ 186,00 por unidade. Avaliação média 3,9 de 5 (372 avaliações). Disponibilidade: pronta entrega.','foice, enxada, motosserra, tesoura de poda',3.9,372,186.0,'unidade','Barreiras','BA','Oeste da Bahia','regional','Luís Eduardo Magalhães, Barreiras, São Desidério',80,26,NULL,'pronta entrega','(77) 99874-9457',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(1381,'servico','Gestão, certificação e serviços de apoio','Consultor de crédito rural','Antônio Lima Fonseca','pessoa_fisica','Antônio Lima Fonseca atua como consultor de crédito rural em Japira/PR, na região Norte Pioneiro do Paraná, com 26 anos de experiência. Elabora projetos de custeio e investimento para bancos e cooperativas. Ajuda na renegociação de dívidas rurais. Agenda as visitas com antecedência e cumpre os prazos combinados. Especialidades: Funcafé, investimento, Pronaf. Atende toda a região Norte Pioneiro do Paraná (Pinhalão, Carlópolis, Tomazina, Ibaiti, Jacarezinho, Ribeirão Claro, Japira, Joaquim Távora), num raio de até 120 km da sede. Cobra em média 2,04% (% do crédito). Avaliação média 4,3 de 5 (37 avaliações). Disponibilidade: sob agendamento. Certificações/registros: Certificação CPA-10.','Funcafé, investimento, Pronaf',4.3,37,2.04,'% do crédito','Japira','PR','Norte Pioneiro do Paraná','regional','Pinhalão, Carlópolis, Tomazina, Ibaiti, Jacarezinho, Ribeirão Claro, Japira, Joaquim Távora',120,26,'Certificação CPA-10','sob agendamento','(43) 98389-1674',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(1382,'produto','Insumos agrícolas','Adubos orgânicos','Patrícia Fonseca Bernardes','pessoa_fisica','Patrícia Fonseca Bernardes atua como produtor(a) e vendedor(a) de adubos orgânicos em Monte Carmelo/MG, na região Cerrado Mineiro, com 2 anos de experiência. Faz entrega a granel com caminhão basculante. Vende cama de frango, esterco curtido e composto orgânico. Emite nota fiscal e entrega na propriedade. Especialidades: cama de frango, composto orgânico, torta de mamona. Atende produtores em Monte Carmelo, Ibiá, num raio de até 40 km. Preço médio: R$ 398,00 por tonelada. Avaliação média 3,7 de 5 (30 avaliações). Disponibilidade: pronta entrega.','cama de frango, composto orgânico, torta de mamona',3.7,30,398.0,'tonelada','Monte Carmelo','MG','Cerrado Mineiro','local','Monte Carmelo, Ibiá',40,2,NULL,'pronta entrega','(34) 98503-4461',0,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(1383,'produto','Mudas e sementes','Sementes de adubação verde','Sol Nascente Sementes','empresa','Sol Nascente Sementes é uma empresa sediada em Viçosa/MG, na região Matas de Minas, no mercado há 40 anos. Segmento: Sementes de adubação verde. Tem mixes prontos para melhorar a estrutura do solo. Vende sementes para cobertura nas entrelinhas do café. Tem assistência técnica e pós-venda. Especialidades: feijão-de-porco, mucuna, mix de cobertura. Atende e envia para todo o Brasil. Preço médio: R$ 18,13 por kg. Avaliação média 4,8 de 5 (162 avaliações). Disponibilidade: sob encomenda.','feijão-de-porco, mucuna, mix de cobertura',4.8,162,18.13,'kg','Viçosa','MG','Matas de Minas','nacional','Todo o Brasil',NULL,40,NULL,'sob encomenda','(33) 98876-1081',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(1384,'servico','Gestão, certificação e serviços de apoio','Técnico em segurança do trabalho rural','João Figueiredo Castro','pessoa_fisica','João Figueiredo Castro atua como técnico em segurança do trabalho em Elói Mendes/MG, na região Sul de Minas, com 28 anos de experiência. Adequa a propriedade à NR-31 e elabora o PGRTR. Ministra treinamentos para aplicadores e operadores de máquinas. Agenda as visitas com antecedência e cumpre os prazos combinados. Especialidades: adequação de alojamentos, PGRTR. Atende toda a região Sul de Minas (Varginha, Três Pontas, Guaxupé, Machado, Alfenas, Boa Esperança, Campos Gerais, Carmo de Minas, São Sebastião do Paraíso, Nepomuceno, Poços de Caldas, Nova Resende, Muzambinho, Cabo Verde, Monte Santo de Minas, Três Corações, Elói Mendes, Paraguaçu, Carmo do Rio Claro, Ilicínea, Santana da Vargem, Coqueiral, Cambuquira), num raio de até 200 km da sede. Preço médio: R$ 341,00 por visita técnica. Avaliação média 3,8 de 5 (8 avaliações). Disponibilidade: imediata. Certificações/registros: Registro no MTE.','adequação de alojamentos, PGRTR',3.8,8,341.0,'visita técnica','Elói Mendes','MG','Sul de Minas','regional','Varginha, Três Pontas, Guaxupé, Machado, Alfenas, Boa Esperança, Campos Gerais, Carmo de Minas, São Sebastião do Paraíso, Nepomuceno, Poços de Caldas, Nova Resende, Muzambinho, Cabo Verde, Monte Santo de Minas, Três Corações, Elói Mendes, Paraguaçu, Carmo do Rio Claro, Ilicínea, Santana da Vargem, Coqueiral, Cambuquira',200,28,'Registro no MTE','imediata','(35) 99913-9880',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(1385,'produto','Insumos agrícolas','Revenda de fertilizantes e corretivos','Lima Insumos Agrícolas','empresa','Lima Insumos Agrícolas é uma empresa sediada em Patrocínio/MG, na região Cerrado Mineiro, no mercado há 38 anos. Segmento: Revenda de fertilizantes e corretivos. Vende adubos formulados para café, calcário e gesso agrícola. Oferece entrega na propriedade e condições de pagamento na safra. Atende de pequenos produtores a grandes fazendas. Mantém estoque o ano todo. Especialidades: calcário, ureia, adubo NPK. Atende toda a região Cerrado Mineiro (Patrocínio, Araguari, Monte Carmelo, Patos de Minas, Carmo do Paranaíba, Serra do Salitre, Campos Altos, Coromandel, Rio Paranaíba, Ibiá, Perdizes, Estrela do Sul, São Gotardo), num raio de até 200 km da sede. Preço médio: R$ 1.870,00 por tonelada. Avaliação média 3,7 de 5 (180 avaliações). Disponibilidade: estoque limitado.','calcário, ureia, adubo NPK',3.7,180,1870.0,'tonelada','Patrocínio','MG','Cerrado Mineiro','regional','Patrocínio, Araguari, Monte Carmelo, Patos de Minas, Carmo do Paranaíba, Serra do Salitre, Campos Altos, Coromandel, Rio Paranaíba, Ibiá, Perdizes, Estrela do Sul, São Gotardo',200,38,NULL,'estoque limitado','(34) 99153-1201',0,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(1386,'produto','Insumos agrícolas','Bioinsumos e controle biológico','BioBom Retiro','empresa','BioBom Retiro é uma empresa sediada em Cabo Verde/MG, na região Sul de Minas, no mercado há 29 anos. Segmento: Bioinsumos e controle biológico. Tem linhas à base de Trichoderma e Bacillus para saúde do solo. Dá suporte técnico para integrar biológicos ao manejo químico. Faz orçamento rápido pela plataforma. Especialidades: fungos entomopatogênicos, Beauveria bassiana. Atende e envia para todo o Brasil. Preço médio: R$ 231,00 por litro. Avaliação média 4,4 de 5 (190 avaliações). Disponibilidade: sob encomenda.','fungos entomopatogênicos, Beauveria bassiana',4.4,190,231.0,'litro','Cabo Verde','MG','Sul de Minas','nacional','Todo o Brasil',NULL,29,NULL,'sob encomenda','(35) 98128-6996',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(1387,'produto','EPI e ferramentas','Equipamentos de proteção individual (EPI)','Rubi EPI','empresa','Rubi EPI é uma empresa sediada em Rio Paranaíba/MG, na região Cerrado Mineiro, no mercado há 21 anos. Segmento: Equipamentos de proteção individual (EPI). Tem EPI para operadores de máquinas e motosserra. Vende kits completos de EPI para aplicação de defensivos. Especialidades: luvas, kit de aplicação, máscaras. Atende toda a região Cerrado Mineiro (Patrocínio, Araguari, Monte Carmelo, Patos de Minas, Carmo do Paranaíba, Serra do Salitre, Campos Altos, Coromandel, Rio Paranaíba, Ibiá, Perdizes, Estrela do Sul, São Gotardo), num raio de até 80 km da sede. Preço médio: R$ 188,00 por kit. Avaliação média 4,5 de 5 (295 avaliações). Disponibilidade: sob encomenda.','luvas, kit de aplicação, máscaras',4.5,295,188.0,'kit','Rio Paranaíba','MG','Cerrado Mineiro','regional','Patrocínio, Araguari, Monte Carmelo, Patos de Minas, Carmo do Paranaíba, Serra do Salitre, Campos Altos, Coromandel, Rio Paranaíba, Ibiá, Perdizes, Estrela do Sul, São Gotardo',80,21,NULL,'sob encomenda','(34) 98970-1310',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(1388,'produto','Máquinas e implementos','Revenda de colhedoras de café','Grão Nobre Colhedoras','empresa','Grão Nobre Colhedoras é uma empresa sediada em Águia Branca/ES, na região Norte do Espírito Santo, no mercado há 9 anos. Segmento: Revenda de colhedoras de café. Vende colhedoras automotrizes e tracionadas para café. Tem equipe de pós-venda e treinamento de operador. Faz orçamento rápido pela plataforma. Oferece condições especiais antes da safra. Tem experiência com café conilon/robusta. Especialidades: recolhedora, colhedora tracionada, colhedora automotriz, colhedoras seminovas. Atende toda a região Norte do Espírito Santo (Linhares, São Gabriel da Palha, Nova Venécia, Jaguaré, Vila Valério, Sooretama, Rio Bananal, Águia Branca), num raio de até 120 km da sede. Preço médio: R$ 1.554.000,00 por unidade. Avaliação média 3,7 de 5 (347 avaliações). Disponibilidade: pronta entrega.','recolhedora, colhedora tracionada, colhedora automotriz, colhedoras seminovas',3.7,347,1554000.0,'unidade','Águia Branca','ES','Norte do Espírito Santo','regional','Linhares, São Gabriel da Palha, Nova Venécia, Jaguaré, Vila Valério, Sooretama, Rio Bananal, Águia Branca',120,9,NULL,'pronta entrega','(27) 99835-7849',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(1389,'produto','Insumos agrícolas','Revenda de fertilizantes e corretivos','Ouro Verde Fertilizantes','empresa','Ouro Verde Fertilizantes é uma empresa sediada em Simonésia/MG, na região Matas de Minas, no mercado há 38 anos. Segmento: Revenda de fertilizantes e corretivos. Oferece entrega na propriedade e condições de pagamento na safra. Vende adubos formulados para café, calcário e gesso agrícola. Tem assistência técnica e pós-venda. Oferece condições especiais antes da safra. Especialidades: cloreto de potássio, adubo NPK. Atende toda a região Matas de Minas (Manhuaçu, Viçosa, Caratinga, Espera Feliz, Simonésia, Manhumirim, Carangola, Alto Jequitibá, Lajinha, Luisburgo), num raio de até 150 km da sede. Preço médio: R$ 2.390,00 por tonelada. Avaliação média 3,4 de 5 (125 avaliações). Disponibilidade: sob encomenda.','cloreto de potássio, adubo NPK',3.4,125,2390.0,'tonelada','Simonésia','MG','Matas de Minas','regional','Manhuaçu, Viçosa, Caratinga, Espera Feliz, Simonésia, Manhumirim, Carangola, Alto Jequitibá, Lajinha, Luisburgo',150,38,NULL,'sob encomenda','(33) 98600-3158',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(1390,'produto','Colheita e armazenagem (materiais)','Sacaria','Nova Safra Sacaria','empresa','Nova Safra Sacaria é uma empresa sediada em Carlópolis/PR, na região Norte Pioneiro do Paraná, no mercado há 13 anos. Segmento: Sacaria. Vende sacos de juta e ráfia para café beneficiado. Faz sacaria personalizada com a marca da fazenda. Mantém estoque o ano todo. Oferece condições especiais antes da safra. Especialidades: sacos de juta, sacos de ráfia. Atende e envia para todo o Brasil. Preço médio: R$ 36,66 por unidade. Avaliação média 4,7 de 5 (369 avaliações). Disponibilidade: pronta entrega.','sacos de juta, sacos de ráfia',4.7,369,36.66,'unidade','Carlópolis','PR','Norte Pioneiro do Paraná','nacional','Todo o Brasil',NULL,13,NULL,'pronta entrega','(43) 99153-1727',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(1391,'produto','Insumos agrícolas','Adubos orgânicos','João Furtado','pessoa_fisica','João Furtado atua como produtor(a) e vendedor(a) de adubos orgânicos em Altinópolis/SP, na região Mogiana, com 2 anos de experiência. Faz entrega a granel com caminhão basculante. Vende cama de frango, esterco curtido e composto orgânico. Faz orçamento rápido pela plataforma. Trabalha com marcas reconhecidas e garantia de fábrica. Especialidades: esterco bovino, composto orgânico. Atende produtores em Altinópolis, Espírito Santo do Pinhal, São Sebastião da Grama, num raio de até 60 km. Preço médio: R$ 796,00 por tonelada. Avaliação média 5,0 de 5 (22 avaliações). Disponibilidade: sob encomenda.','esterco bovino, composto orgânico',5.0,22,796.0,'tonelada','Altinópolis','SP','Mogiana','local','Altinópolis, Espírito Santo do Pinhal, São Sebastião da Grama',60,2,NULL,'sob encomenda','(16) 99354-4716',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(1392,'servico','Gestão, certificação e serviços de apoio','Engenheiro ambiental','Mateus Silva','pessoa_fisica','Mateus Silva atua como engenheiro ambiental em Perdões/MG, na região Campo das Vertentes, com 24 anos de experiência. Faz CAR, outorga de uso de água e licenciamento ambiental. Regulariza reserva legal e APP da propriedade. Aceita pagamento via Pix, transferência ou parcelado até a colheita. Tem referências de produtores da região. Especialidades: CAR, outorga de água, licenciamento ambiental. Atende toda a região Campo das Vertentes (Lavras, Perdões, Bom Sucesso, Ijaci, Santo Antônio do Amparo, Itumirim, Ingaí), num raio de até 120 km da sede. Preço médio: R$ 5.940,00 por projeto. Avaliação média 4,7 de 5 (36 avaliações). Disponibilidade: sob agendamento. Certificações/registros: CREA ativo.','CAR, outorga de água, licenciamento ambiental',4.7,36,5940.0,'projeto','Perdões','MG','Campo das Vertentes','regional','Lavras, Perdões, Bom Sucesso, Ijaci, Santo Antônio do Amparo, Itumirim, Ingaí',120,24,'CREA ativo','sob agendamento','(35) 99146-6495',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(1393,'servico','Máquinas, estrutura e manutenção','Eletricista rural','Gustavo Bernardes Mesquita','pessoa_fisica','Gustavo Bernardes Mesquita atua como eletricista rural em Monte Santo de Minas/MG, na região Sul de Minas, com 27 anos de experiência. Faz manutenção preventiva antes da safra. Monta quadros de comando para motores. Especialidades: motores elétricos, bombas de irrigação. Atende produtores em Monte Santo de Minas, Poços de Caldas, num raio de até 40 km. Preço médio: R$ 96,00 por hora. Avaliação média 4,3 de 5 (6 avaliações). Disponibilidade: sob agendamento. Certificações/registros: NR-10.','motores elétricos, bombas de irrigação',4.3,6,96.0,'hora','Monte Santo de Minas','MG','Sul de Minas','local','Monte Santo de Minas, Poços de Caldas',40,27,'NR-10','sob agendamento','(35) 99156-2062',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(1394,'produto','Insumos agrícolas','Revenda de fertilizantes e corretivos','Boa Colheita Fertilizantes','empresa','Boa Colheita Fertilizantes é uma empresa sediada em Barreiras/BA, na região Oeste da Bahia, no mercado há 38 anos. Segmento: Revenda de fertilizantes e corretivos. Oferece entrega na propriedade e condições de pagamento na safra. Tem agrônomo para recomendação de adubação sem custo adicional. Oferece condições especiais antes da safra. Especialidades: adubo NPK, gesso agrícola, formulados para café, ureia. Atende toda a região Oeste da Bahia (Luís Eduardo Magalhães, Barreiras, São Desidério), num raio de até 80 km da sede. Preço médio: R$ 3.920,00 por tonelada. Avaliação média 3,9 de 5 (273 avaliações). Disponibilidade: sob encomenda.','adubo NPK, gesso agrícola, formulados para café, ureia',3.9,273,3920.0,'tonelada','Barreiras','BA','Oeste da Bahia','regional','Luís Eduardo Magalhães, Barreiras, São Desidério',80,38,NULL,'sob encomenda','(77) 98259-4504',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(1395,'servico','Manejo e tratos culturais','Trabalhador rural para tratos culturais','Ana Oliveira Junqueira','pessoa_fisica','Ana Oliveira Junqueira atua como trabalhador rural diarista em Tomazina/PR, na região Norte Pioneiro do Paraná, com 6 anos de experiência. Trabalha como diarista em capina, roçada e adubação manual. Faz replantio de falhas e amarração de mudas. Prioriza atendimento a propriedades familiares. Especialidades: capina, roçada. Atende produtores em Tomazina, Japira, num raio de até 40 km. Preço médio: R$ 162,00 por diária. Avaliação média 4,3 de 5 (22 avaliações). Disponibilidade: imediata.','capina, roçada',4.3,22,162.0,'diária','Tomazina','PR','Norte Pioneiro do Paraná','local','Tomazina, Japira',40,6,NULL,'imediata','(43) 99838-7208',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(1396,'servico','Manejo e tratos culturais','Equipe de poda','Fernando Dias Pimenta','pessoa_fisica','Fernando Dias Pimenta atua como podador de café em Espírito Santo do Pinhal/SP, na região Mogiana, com 27 anos de experiência. Trabalha com equipe própria e motosserras e ferramentas de poda. Executa recepa, esqueletamento e decote conforme recomendação agronômica. Prioriza atendimento a propriedades familiares. Especialidades: decote, poda programada de ciclo, desbrota, esqueletamento. Atende produtores em Espírito Santo do Pinhal, Patrocínio Paulista, São Sebastião da Grama, num raio de até 40 km. Preço médio: R$ 1.490,00 por hectare. Avaliação média 4,7 de 5 (27 avaliações). Disponibilidade: imediata. Certificações/registros: NR-31, Curso de operação de motosserra NR-12.','decote, poda programada de ciclo, desbrota, esqueletamento',4.7,27,1490.0,'hectare','Espírito Santo do Pinhal','SP','Mogiana','local','Espírito Santo do Pinhal, Patrocínio Paulista, São Sebastião da Grama',40,27,'NR-31, Curso de operação de motosserra NR-12','imediata','(16) 99638-3450',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(1397,'produto','Pós-colheita e beneficiamento (equipamentos)','Lenha, cavaco e pellets para secagem','Renata Rezende','pessoa_fisica','Renata Rezende atua como fornecedor(a) de lenha e biomassa para secagem em Luís Eduardo Magalhães/BA, na região Oeste da Bahia, com 20 anos de experiência. Faz entrega programada durante a safra. Vende lenha de eucalipto de reflorestamento para fornalhas. Faz orçamento rápido pela plataforma. Especialidades: cavaco, pellets. Atende produtores em Luís Eduardo Magalhães, São Desidério, num raio de até 60 km. Preço médio: R$ 179,00 por m³. Avaliação média 4,6 de 5 (33 avaliações). Disponibilidade: sob encomenda.','cavaco, pellets',4.6,33,179.0,'m³','Luís Eduardo Magalhães','BA','Oeste da Bahia','local','Luís Eduardo Magalhães, São Desidério',60,20,NULL,'sob encomenda','(77) 98168-6782',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(1398,'servico','Pós-colheita e processamento','Armazém de café','Gomes Armazéns Gerais','empresa','Gomes Armazéns Gerais é uma empresa sediada em São Desidério/BA, na região Oeste da Bahia, no mercado há 3 anos. Segmento: Armazém de café. Oferece amostragem e rastreabilidade dos lotes. Emite certificados de depósito para operações de crédito. Especialidades: armazenagem em big bag, controle de umidade, armazenagem em sacaria, armazém geral. Atende toda a região Oeste da Bahia (Luís Eduardo Magalhães, Barreiras, São Desidério), num raio de até 80 km da sede. Preço médio: R$ 1,92 por saca/mês. Avaliação média 4,8 de 5 (199 avaliações). Disponibilidade: imediata. Certificações/registros: Armazém certificado MAPA.','armazenagem em big bag, controle de umidade, armazenagem em sacaria, armazém geral',4.8,199,1.92,'saca/mês','São Desidério','BA','Oeste da Bahia','regional','Luís Eduardo Magalhães, Barreiras, São Desidério',80,3,'Armazém certificado MAPA','imediata','(77) 99231-7378',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(1399,'produto','Pós-colheita e beneficiamento (equipamentos)','Lonas para terreiro e secagem','Mesquita Lonas e Coberturas','empresa','Mesquita Lonas e Coberturas é uma empresa sediada em Ribeirão Corrente/SP, na região Mogiana, no mercado há 6 anos. Segmento: Lonas para terreiro e secagem. Faz lonas sob medida com ilhós. Tem telas para terreiros suspensos. Tem assistência técnica e pós-venda. Mantém estoque o ano todo. Especialidades: lona para cobertura, lona de terreiro. Atende e envia para todo o Brasil. Preço médio: R$ 7,79 por m². Avaliação média 4,4 de 5 (177 avaliações). Disponibilidade: sob encomenda.','lona para cobertura, lona de terreiro',4.4,177,7.79,'m²','Ribeirão Corrente','SP','Mogiana','nacional','Todo o Brasil',NULL,6,NULL,'sob encomenda','(16) 98967-5403',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(1400,'produto','Pós-colheita e beneficiamento (equipamentos)','Secadores de café','Campos Equipamentos para Café','empresa','Campos Equipamentos para Café é uma empresa sediada em Japira/PR, na região Norte Pioneiro do Paraná, no mercado há 44 anos. Segmento: Secadores de café. Dimensiona o secador de acordo com a produção da fazenda. Fabrica e instala secadores rotativos e de leito fixo. Oferece condições especiais antes da safra. Especialidades: instalação, secador de leito fixo. Atende e envia para todo o Brasil. Preço médio: R$ 232.000,00 por unidade. Avaliação média 4,9 de 5 (399 avaliações). Disponibilidade: sob encomenda.','instalação, secador de leito fixo',4.9,399,232000.0,'unidade','Japira','PR','Norte Pioneiro do Paraná','nacional','Todo o Brasil',NULL,44,NULL,'sob encomenda','(43) 99079-4577',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(1401,'produto','Insumos agrícolas','Revenda de defensivos agrícolas','Cafeeiro Defensivos','empresa','Cafeeiro Defensivos é uma empresa sediada em Espírito Santo do Pinhal/SP, na região Mogiana, no mercado há 26 anos. Segmento: Revenda de defensivos agrícolas. Recebe embalagens vazias para devolução. Vende fungicidas, inseticidas e herbicidas registrados para café. Dá desconto em compras de volume e para cooperados. Especialidades: inseticidas, adjuvantes, acaricidas, fungicidas. Atende toda a região Mogiana (Franca, Pedregulho, Cristais Paulista, Altinópolis, Espírito Santo do Pinhal, Caconde, Ribeirão Corrente, Jeriquara, Patrocínio Paulista, Itirapuã, São Sebastião da Grama, Mococa), num raio de até 100 km da sede. Preço médio: R$ 214,00 por litro (média do portfólio). Avaliação média 3,9 de 5 (121 avaliações). Disponibilidade: sob encomenda. Certificações/registros: Revenda registrada no IMA/órgão estadual.','inseticidas, adjuvantes, acaricidas, fungicidas',3.9,121,214.0,'litro (média do portfólio)','Espírito Santo do Pinhal','SP','Mogiana','regional','Franca, Pedregulho, Cristais Paulista, Altinópolis, Espírito Santo do Pinhal, Caconde, Ribeirão Corrente, Jeriquara, Patrocínio Paulista, Itirapuã, São Sebastião da Grama, Mococa',100,26,'Revenda registrada no IMA/órgão estadual','sob encomenda','(16) 98883-9256',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(1402,'servico','Máquinas, estrutura e manutenção','Construtor de terreiros e tulhas','José Rocha Siqueira','pessoa_fisica','José Rocha Siqueira atua como pedreiro especializado em estruturas rurais em Patrocínio Paulista/SP, na região Mogiana, com 32 anos de experiência. Executa tulhas e galpões para armazenagem. Monta terreiros suspensos para cafés especiais. Especialidades: barracões, galpões, terreiro suspenso, terreiro de concreto. Atende produtores em Patrocínio Paulista, Itirapuã, num raio de até 30 km. Preço médio: R$ 92,00 por m². Avaliação média 4,5 de 5 (28 avaliações). Disponibilidade: sob agendamento.','barracões, galpões, terreiro suspenso, terreiro de concreto',4.5,28,92.0,'m²','Patrocínio Paulista','SP','Mogiana','local','Patrocínio Paulista, Itirapuã',30,32,NULL,'sob agendamento','(16) 99653-3400',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(1403,'servico','Máquinas, estrutura e manutenção','Técnico de manutenção de secadores e beneficiadoras','José Carvalho Almeida','pessoa_fisica','José Carvalho Almeida atua como técnico de manutenção de secadores e máquinas de beneficiamento em Ministro Andreazza/RO, na região Matas de Rondônia, com 31 anos de experiência. Atende chamados durante a safra. Faz a revisão pré-safra de secadores, fornalhas e elevadores. Emite nota fiscal e formaliza o serviço em contrato. Agenda as visitas com antecedência e cumpre os prazos combinados. Tem experiência com café conilon/robusta. Especialidades: fornalhas, revisão pré-safra. Atende toda a região Matas de Rondônia (Cacoal, Ministro Andreazza, Alta Floresta D''Oeste, Rolim de Moura, Nova Brasilândia D''Oeste, São Miguel do Guaporé), num raio de até 80 km da sede. Preço médio: R$ 154,00 por hora. Avaliação média 3,8 de 5 (27 avaliações). Disponibilidade: imediata. Certificações/registros: NR-12.','fornalhas, revisão pré-safra',3.8,27,154.0,'hora','Ministro Andreazza','RO','Matas de Rondônia','regional','Cacoal, Ministro Andreazza, Alta Floresta D''Oeste, Rolim de Moura, Nova Brasilândia D''Oeste, São Miguel do Guaporé',80,31,'NR-12','imediata','(69) 99080-5795',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(1404,'servico','Planejamento e implantação da lavoura','Engenheiro agrônomo','Moreira Consultoria Agronômica','empresa','Moreira Consultoria Agronômica é uma empresa sediada em Ribeirão Corrente/SP, na região Mogiana, no mercado há 39 anos. Segmento: Engenheiro agrônomo. Ajuda a planejar a renovação de talhões improdutivos com análise de custo. Acompanha a lavoura com visitas periódicas e emite receituário agronômico. Tem referências de produtores da região. Especialidades: recomendação de adubação, cafés especiais, planejamento de safra. Atende toda a região Mogiana (Franca, Pedregulho, Cristais Paulista, Altinópolis, Espírito Santo do Pinhal, Caconde, Ribeirão Corrente, Jeriquara, Patrocínio Paulista, Itirapuã, São Sebastião da Grama, Mococa), num raio de até 80 km da sede. Preço médio: R$ 667,00 por visita técnica. Avaliação média 4,0 de 5 (10 avaliações). Disponibilidade: sob agendamento. Certificações/registros: CREA ativo.','recomendação de adubação, cafés especiais, planejamento de safra',4.0,10,667.0,'visita técnica','Ribeirão Corrente','SP','Mogiana','regional','Franca, Pedregulho, Cristais Paulista, Altinópolis, Espírito Santo do Pinhal, Caconde, Ribeirão Corrente, Jeriquara, Patrocínio Paulista, Itirapuã, São Sebastião da Grama, Mococa',80,39,'CREA ativo','sob agendamento','(16) 99651-9821',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(1405,'servico','Gestão, certificação e serviços de apoio','Consultor de crédito rural','Adilson Furtado Lima','pessoa_fisica','Adilson Furtado Lima atua como consultor de crédito rural em Barra da Estiva/BA, na região Chapada Diamantina, com 25 anos de experiência. Ajuda na renegociação de dívidas rurais. Elabora projetos de custeio e investimento para bancos e cooperativas. Especialidades: custeio, Funcafé, investimento, Pronaf. Atende toda a região Chapada Diamantina (Piatã, Mucugê, Ibicoara, Barra da Estiva, Abaíra, Ituaçu), num raio de até 120 km da sede. Cobra em média 2,19% (% do crédito). Avaliação média 3,7 de 5 (4 avaliações). Disponibilidade: sob agendamento. Certificações/registros: CREA ativo.','custeio, Funcafé, investimento, Pronaf',3.7,4,2.19,'% do crédito','Barra da Estiva','BA','Chapada Diamantina','regional','Piatã, Mucugê, Ibicoara, Barra da Estiva, Abaíra, Ituaçu',120,25,'CREA ativo','sob agendamento','(75) 98479-6576',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(1406,'servico','Gestão, certificação e serviços de apoio','Técnico em segurança do trabalho rural','Pedro Rodrigues Carvalho','pessoa_fisica','Pedro Rodrigues Carvalho atua como técnico em segurança do trabalho em Carmo de Minas/MG, na região Sul de Minas, com 7 anos de experiência. Orienta sobre EPI e condições de alojamento da colheita. Ministra treinamentos para aplicadores e operadores de máquinas. Especialidades: NR-31, treinamentos de segurança. Atende toda a região Sul de Minas (Varginha, Três Pontas, Guaxupé, Machado, Alfenas, Boa Esperança, Campos Gerais, Carmo de Minas, São Sebastião do Paraíso, Nepomuceno, Poços de Caldas, Nova Resende, Muzambinho, Cabo Verde, Monte Santo de Minas, Três Corações, Elói Mendes, Paraguaçu, Carmo do Rio Claro, Ilicínea, Santana da Vargem, Coqueiral, Cambuquira), num raio de até 100 km da sede. Preço médio: R$ 554,00 por visita técnica. Avaliação média 4,7 de 5 (28 avaliações). Disponibilidade: imediata. Certificações/registros: Registro no MTE.','NR-31, treinamentos de segurança',4.7,28,554.0,'visita técnica','Carmo de Minas','MG','Sul de Minas','regional','Varginha, Três Pontas, Guaxupé, Machado, Alfenas, Boa Esperança, Campos Gerais, Carmo de Minas, São Sebastião do Paraíso, Nepomuceno, Poços de Caldas, Nova Resende, Muzambinho, Cabo Verde, Monte Santo de Minas, Três Corações, Elói Mendes, Paraguaçu, Carmo do Rio Claro, Ilicínea, Santana da Vargem, Coqueiral, Cambuquira',100,7,'Registro no MTE','imediata','(35) 98017-2703',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(1407,'produto','Colheita e armazenagem (materiais)','Sacaria','Chapadão Sacaria','empresa','Chapadão Sacaria é uma empresa sediada em Abaíra/BA, na região Chapada Diamantina, no mercado há 24 anos. Segmento: Sacaria. Tem big bags para armazenagem de café em coco. Faz sacaria personalizada com a marca da fazenda. Especialidades: big bags, sacaria personalizada, sacos de ráfia, sacos de juta. Atende e envia para todo o Brasil. Preço médio: R$ 48,92 por unidade. Avaliação média 4,3 de 5 (111 avaliações). Disponibilidade: pronta entrega.','big bags, sacaria personalizada, sacos de ráfia, sacos de juta',4.3,111,48.92,'unidade','Abaíra','BA','Chapada Diamantina','nacional','Todo o Brasil',NULL,24,NULL,'pronta entrega','(75) 99881-7796',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(1408,'produto','Mudas e sementes','Viveiro de mudas de café','Carlos Andrade','pessoa_fisica','Carlos Andrade atua como viveirista de mudas de café em Ituaçu/BA, na região Chapada Diamantina, com 13 anos de experiência. Faz mudas por encomenda com prazo de produção combinado. Trabalha com cultivares resistentes à ferrugem. Especialidades: mudas enxertadas, Catuaí Vermelho, Mundo Novo. Atende toda a região Chapada Diamantina (Piatã, Mucugê, Ibicoara, Barra da Estiva, Abaíra, Ituaçu), num raio de até 100 km da sede. Preço médio: R$ 2,21 por muda. Avaliação média 4,7 de 5 (37 avaliações). Disponibilidade: pronta entrega. Certificações/registros: Registro RENASEM.','mudas enxertadas, Catuaí Vermelho, Mundo Novo',4.7,37,2.21,'muda','Ituaçu','BA','Chapada Diamantina','regional','Piatã, Mucugê, Ibicoara, Barra da Estiva, Abaíra, Ituaçu',100,13,'Registro RENASEM','pronta entrega','(75) 99807-3328',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(1409,'servico','Manejo e tratos culturais','Laboratório de análise de solo e foliar','Laboratório Cafezal','empresa','Laboratório Cafezal é uma empresa sediada em Barra da Estiva/BA, na região Chapada Diamantina, no mercado há 23 anos. Segmento: Laboratório de análise de solo e foliar. Tem pontos de coleta e parceria com cooperativas da região. Oferece análise química completa com micronutrientes e matéria orgânica. Prioriza atendimento a propriedades familiares. Especialidades: análise de solo, análise de fertilizantes, análise física de solo, análise de micronutrientes. Atende toda a região Chapada Diamantina (Piatã, Mucugê, Ibicoara, Barra da Estiva, Abaíra, Ituaçu), num raio de até 80 km da sede. Preço médio: R$ 47,77 por amostra. Avaliação média 4,0 de 5 (251 avaliações). Disponibilidade: agenda cheia até o fim da safra.','análise de solo, análise de fertilizantes, análise física de solo, análise de micronutrientes',4.0,251,47.77,'amostra','Barra da Estiva','BA','Chapada Diamantina','regional','Piatã, Mucugê, Ibicoara, Barra da Estiva, Abaíra, Ituaçu',80,23,NULL,'agenda cheia até o fim da safra','(75) 99266-1750',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(1410,'servico','Qualidade e comercialização','Consultor de cafés especiais','Grão de Ouro Specialty Coffee','empresa','Grão de Ouro Specialty Coffee é uma empresa sediada em Abaíra/BA, na região Chapada Diamantina, no mercado há 2 anos. Segmento: Consultor de cafés especiais. Treina a equipe em colheita seletiva e secagem para qualidade. Implanta processos de fermentação controlada e anaeróbica para elevar a pontuação. Especialidades: colheita seletiva, processos naturais e anaeróbicos, fermentação controlada. Atende e envia para todo o Brasil. Preço médio: R$ 932,00 por visita técnica. Avaliação média 5,0 de 5 (238 avaliações). Disponibilidade: sob agendamento. Certificações/registros: Barista certificado SCA, Q-Arabica Grader (CQI).','colheita seletiva, processos naturais e anaeróbicos, fermentação controlada',5.0,238,932.0,'visita técnica','Abaíra','BA','Chapada Diamantina','nacional','Todo o Brasil',NULL,2,'Barista certificado SCA, Q-Arabica Grader (CQI)','sob agendamento','(75) 99137-3571',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(1411,'produto','EPI e ferramentas','Equipamentos de proteção individual (EPI)','Ribeiro Segurança do Trabalho','empresa','Ribeiro Segurança do Trabalho é uma empresa sediada em Ibicoara/BA, na região Chapada Diamantina, no mercado há 4 anos. Segmento: Equipamentos de proteção individual (EPI). Tem EPI para operadores de máquinas e motosserra. Emite certificados de aprovação (CA) dos produtos. Parcela no cartão ou aceita pagamento na safra. Especialidades: botas, óculos, kit de aplicação. Atende toda a região Chapada Diamantina (Piatã, Mucugê, Ibicoara, Barra da Estiva, Abaíra, Ituaçu), num raio de até 200 km da sede. Preço médio: R$ 229,00 por kit. Avaliação média 4,1 de 5 (115 avaliações). Disponibilidade: estoque limitado.','botas, óculos, kit de aplicação',4.1,115,229.0,'kit','Ibicoara','BA','Chapada Diamantina','regional','Piatã, Mucugê, Ibicoara, Barra da Estiva, Abaíra, Ituaçu',200,4,NULL,'estoque limitado','(75) 99067-5540',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(1412,'servico','Gestão, certificação e serviços de apoio','Engenheiro ambiental','Jequitibá Engenharia Ambiental','empresa','Jequitibá Engenharia Ambiental é uma empresa sediada em Machado/MG, na região Sul de Minas, no mercado há 11 anos. Segmento: Engenheiro ambiental. Regulariza reserva legal e APP da propriedade. Elabora planos de recuperação de áreas degradadas. Especialidades: PRAD, CAR, reserva legal. Atende toda a região Sul de Minas (Varginha, Três Pontas, Guaxupé, Machado, Alfenas, Boa Esperança, Campos Gerais, Carmo de Minas, São Sebastião do Paraíso, Nepomuceno, Poços de Caldas, Nova Resende, Muzambinho, Cabo Verde, Monte Santo de Minas, Três Corações, Elói Mendes, Paraguaçu, Carmo do Rio Claro, Ilicínea, Santana da Vargem, Coqueiral, Cambuquira), num raio de até 80 km da sede. Preço médio: R$ 2.180,00 por projeto. Avaliação média 4,4 de 5 (75 avaliações). Disponibilidade: imediata. Certificações/registros: CREA ativo.','PRAD, CAR, reserva legal',4.4,75,2180.0,'projeto','Machado','MG','Sul de Minas','regional','Varginha, Três Pontas, Guaxupé, Machado, Alfenas, Boa Esperança, Campos Gerais, Carmo de Minas, São Sebastião do Paraíso, Nepomuceno, Poços de Caldas, Nova Resende, Muzambinho, Cabo Verde, Monte Santo de Minas, Três Corações, Elói Mendes, Paraguaçu, Carmo do Rio Claro, Ilicínea, Santana da Vargem, Coqueiral, Cambuquira',80,11,'CREA ativo','imediata','(35) 98381-6239',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(1413,'servico','Manejo e tratos culturais','Aplicador de defensivos','Vanessa Freitas','pessoa_fisica','Vanessa Freitas atua como aplicador de defensivos agrícolas em Paraguaçu/MG, na região Sul de Minas, com 14 anos de experiência. Faz aplicação tratorizada com turbo-atomizador e aplicação costal em áreas declivosas. Possui equipamento próprio calibrado para aplicações de fungicida e inseticida. Tem equipe treinada e equipamentos revisados. Agenda as visitas com antecedência e cumpre os prazos combinados. Especialidades: controle de broca, aplicação foliar, aplicação de herbicida, aplicação costal. Atende produtores em Paraguaçu, Santana da Vargem, num raio de até 60 km. Preço médio: R$ 152,00 por hectare. Avaliação média 4,0 de 5 (17 avaliações). Disponibilidade: imediata. Certificações/registros: Curso de aplicação segura de agrotóxicos, NR-31.','controle de broca, aplicação foliar, aplicação de herbicida, aplicação costal',4.0,17,152.0,'hectare','Paraguaçu','MG','Sul de Minas','local','Paraguaçu, Santana da Vargem',60,14,'Curso de aplicação segura de agrotóxicos, NR-31','imediata','(35) 98727-5783',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(1414,'produto','Máquinas e implementos','Concessionária de tratores cafeeiros','Araújo Máquinas Agrícolas','empresa','Araújo Máquinas Agrícolas é uma empresa sediada em Barreiras/BA, na região Oeste da Bahia, no mercado há 30 anos. Segmento: Concessionária de tratores cafeeiros. Tem oficina própria e assistência técnica no campo. Vende tratores estreitos próprios para as entrelinhas do café. Faz orçamento rápido pela plataforma. Acostumado a lavouras planas e altamente mecanizadas. Especialidades: tratores estreitos, assistência técnica, peças originais, tratores cafeeiros. Atende toda a região Oeste da Bahia (Luís Eduardo Magalhães, Barreiras, São Desidério), num raio de até 200 km da sede. Preço médio: R$ 279.000,00 por unidade. Avaliação média 4,1 de 5 (253 avaliações). Disponibilidade: pronta entrega.','tratores estreitos, assistência técnica, peças originais, tratores cafeeiros',4.1,253,279000.0,'unidade','Barreiras','BA','Oeste da Bahia','regional','Luís Eduardo Magalhães, Barreiras, São Desidério',200,30,NULL,'pronta entrega','(77) 98087-2359',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(1415,'produto','Mudas e sementes','Viveiro de mudas de café','Martins Mudas de Café','empresa','Martins Mudas de Café é uma empresa sediada em Águia Branca/ES, na região Norte do Espírito Santo, no mercado há 6 anos. Segmento: Viveiro de mudas de café. Trabalha com cultivares resistentes à ferrugem. Faz mudas por encomenda com prazo de produção combinado. Tem experiência com café conilon/robusta. Especialidades: Catuaí Vermelho, Arara, conilon clonal. Atende toda a região Norte do Espírito Santo (Linhares, São Gabriel da Palha, Nova Venécia, Jaguaré, Vila Valério, Sooretama, Rio Bananal, Águia Branca), num raio de até 150 km da sede. Preço médio: R$ 1,68 por muda. Avaliação média 4,5 de 5 (27 avaliações). Disponibilidade: pronta entrega. Certificações/registros: Registro RENASEM.','Catuaí Vermelho, Arara, conilon clonal',4.5,27,1.68,'muda','Águia Branca','ES','Norte do Espírito Santo','regional','Linhares, São Gabriel da Palha, Nova Venécia, Jaguaré, Vila Valério, Sooretama, Rio Bananal, Águia Branca',150,6,'Registro RENASEM','pronta entrega','(27) 98641-3776',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(1416,'produto','Insumos agrícolas','Revenda de defensivos agrícolas','Ribeiro Agroquímica','empresa','Ribeiro Agroquímica é uma empresa sediada em Alto Jequitibá/MG, na região Matas de Minas, no mercado há 20 anos. Segmento: Revenda de defensivos agrícolas. Vende fungicidas, inseticidas e herbicidas registrados para café. Emite receituário agronômico na hora da compra. Oferece condições especiais antes da safra. Especialidades: adjuvantes, herbicidas. Atende toda a região Matas de Minas (Manhuaçu, Viçosa, Caratinga, Espera Feliz, Simonésia, Manhumirim, Carangola, Alto Jequitibá, Lajinha, Luisburgo), num raio de até 80 km da sede. Preço médio: R$ 90,00 por litro (média do portfólio). Avaliação média 3,6 de 5 (227 avaliações). Disponibilidade: estoque limitado. Certificações/registros: Revenda registrada no IMA/órgão estadual.','adjuvantes, herbicidas',3.6,227,90.0,'litro (média do portfólio)','Alto Jequitibá','MG','Matas de Minas','regional','Manhuaçu, Viçosa, Caratinga, Espera Feliz, Simonésia, Manhumirim, Carangola, Alto Jequitibá, Lajinha, Luisburgo',80,20,'Revenda registrada no IMA/órgão estadual','estoque limitado','(33) 98016-4396',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(1417,'servico','Gestão, certificação e serviços de apoio','Contador rural','Carlos Siqueira Rezende','pessoa_fisica','Carlos Siqueira Rezende atua como contador rural em Paraguaçu/MG, na região Sul de Minas, com 26 anos de experiência. Cuida do livro caixa do produtor e da declaração de Imposto de Renda. Faz a folha de pagamento dos safristas e o eSocial. Faz orçamento sem compromisso na propriedade. Aceita pagamento via Pix, transferência ou parcelado até a colheita. Especialidades: ITR, folha de pagamento rural, Imposto de Renda rural. Atende toda a região Sul de Minas (Varginha, Três Pontas, Guaxupé, Machado, Alfenas, Boa Esperança, Campos Gerais, Carmo de Minas, São Sebastião do Paraíso, Nepomuceno, Poços de Caldas, Nova Resende, Muzambinho, Cabo Verde, Monte Santo de Minas, Três Corações, Elói Mendes, Paraguaçu, Carmo do Rio Claro, Ilicínea, Santana da Vargem, Coqueiral, Cambuquira), num raio de até 120 km da sede. Preço médio: R$ 358,00 por mês. Avaliação média 3,3 de 5 (23 avaliações). Disponibilidade: imediata.','ITR, folha de pagamento rural, Imposto de Renda rural',3.3,23,358.0,'mês','Paraguaçu','MG','Sul de Minas','regional','Varginha, Três Pontas, Guaxupé, Machado, Alfenas, Boa Esperança, Campos Gerais, Carmo de Minas, São Sebastião do Paraíso, Nepomuceno, Poços de Caldas, Nova Resende, Muzambinho, Cabo Verde, Monte Santo de Minas, Três Corações, Elói Mendes, Paraguaçu, Carmo do Rio Claro, Ilicínea, Santana da Vargem, Coqueiral, Cambuquira',120,26,NULL,'imediata','(35) 99010-6070',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(1418,'servico','Qualidade e comercialização','Corretor de café','Maria Mendes','pessoa_fisica','Maria Mendes atua como corretor de café em Iúna/ES, na região Montanhas do Espírito Santo, com 29 anos de experiência. Acompanha o mercado e orienta o melhor momento de venda. Faz a intermediação entre produtor e compradores, exportadores e torrefações. Faz orçamento sem compromisso na propriedade. Especialidades: exportação, cafés especiais, contratos futuros. Atende toda a região Montanhas do Espírito Santo (Venda Nova do Imigrante, Brejetuba, Iúna, Domingos Martins, Castelo, Afonso Cláudio, Conceição do Castelo, Ibatiba, Irupi, Muniz Freire), num raio de até 120 km da sede. Cobra em média 0,66% (% do valor negociado). Avaliação média 4,1 de 5 (29 avaliações). Disponibilidade: imediata.','exportação, cafés especiais, contratos futuros',4.1,29,0.66,'% do valor negociado','Iúna','ES','Montanhas do Espírito Santo','regional','Venda Nova do Imigrante, Brejetuba, Iúna, Domingos Martins, Castelo, Afonso Cláudio, Conceição do Castelo, Ibatiba, Irupi, Muniz Freire',120,29,NULL,'imediata','(28) 98961-5607',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(1419,'produto','Máquinas e implementos','Revenda de pulverizadores','Teixeira Agrícola','empresa','Teixeira Agrícola é uma empresa sediada em Perdizes/MG, na região Cerrado Mineiro, no mercado há 14 anos. Segmento: Revenda de pulverizadores. Tem bicos e peças de reposição. Vende pulverizadores costais e turbo-atomizadores para café. Oferece condições especiais antes da safra. Especialidades: pulverizador de barra, bicos e peças, pulverizador costal, turbo-atomizador. Atende toda a região Cerrado Mineiro (Patrocínio, Araguari, Monte Carmelo, Patos de Minas, Carmo do Paranaíba, Serra do Salitre, Campos Altos, Coromandel, Rio Paranaíba, Ibiá, Perdizes, Estrela do Sul, São Gotardo), num raio de até 150 km da sede. Preço médio: R$ 90.000,00 por unidade. Avaliação média 4,9 de 5 (263 avaliações). Disponibilidade: pronta entrega.','pulverizador de barra, bicos e peças, pulverizador costal, turbo-atomizador',4.9,263,90000.0,'unidade','Perdizes','MG','Cerrado Mineiro','regional','Patrocínio, Araguari, Monte Carmelo, Patos de Minas, Carmo do Paranaíba, Serra do Salitre, Campos Altos, Coromandel, Rio Paranaíba, Ibiá, Perdizes, Estrela do Sul, São Gotardo',150,14,NULL,'pronta entrega','(34) 98802-5910',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(1420,'servico','Qualidade e comercialização','Consultor de cafés especiais','Paulo Martins Carvalho','pessoa_fisica','Paulo Martins Carvalho atua como consultor de cafés especiais em Lavras/MG, na região Campo das Vertentes, com 5 anos de experiência. Treina a equipe em colheita seletiva e secagem para qualidade. Ajuda a acessar compradores e concursos de cafés especiais. Especialidades: rastreabilidade, fermentação controlada, processos naturais e anaeróbicos. Atende toda a região Campo das Vertentes (Lavras, Perdões, Bom Sucesso, Ijaci, Santo Antônio do Amparo, Itumirim, Ingaí), num raio de até 80 km da sede. Preço médio: R$ 949,00 por visita técnica. Avaliação média 3,8 de 5 (40 avaliações). Disponibilidade: agenda cheia até o fim da safra. Certificações/registros: Barista certificado SCA, Q-Arabica Grader (CQI).','rastreabilidade, fermentação controlada, processos naturais e anaeróbicos',3.8,40,949.0,'visita técnica','Lavras','MG','Campo das Vertentes','regional','Lavras, Perdões, Bom Sucesso, Ijaci, Santo Antônio do Amparo, Itumirim, Ingaí',80,5,'Barista certificado SCA, Q-Arabica Grader (CQI)','agenda cheia até o fim da safra','(35) 99300-1686',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(1421,'servico','Máquinas, estrutura e manutenção','Mecânico de máquinas agrícolas','Pedro Rodrigues','pessoa_fisica','Pedro Rodrigues atua como mecânico de máquinas agrícolas em São Miguel do Guaporé/RO, na região Matas de Rondônia, com 4 anos de experiência. Faz manutenção de tratores e implementos com atendimento na propriedade. Tem experiência com sistema hidráulico e motores diesel. Tem equipe treinada e equipamentos revisados. Tem experiência com café conilon/robusta. Especialidades: sistema hidráulico, colhedoras. Atende produtores em São Miguel do Guaporé, Nova Brasilândia D''Oeste, num raio de até 50 km. Preço médio: R$ 151,00 por hora. Avaliação média 4,8 de 5 (39 avaliações). Disponibilidade: imediata.','sistema hidráulico, colhedoras',4.8,39,151.0,'hora','São Miguel do Guaporé','RO','Matas de Rondônia','local','São Miguel do Guaporé, Nova Brasilândia D''Oeste',50,4,NULL,'imediata','(69) 98338-6075',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(1422,'servico','Planejamento e implantação da lavoura','Engenheiro agrônomo','Figueiredo Consultoria Agronômica','empresa','Figueiredo Consultoria Agronômica é uma empresa sediada em Boa Esperança/MG, na região Sul de Minas, no mercado há 28 anos. Segmento: Engenheiro agrônomo. Ajuda a planejar a renovação de talhões improdutivos com análise de custo. Faz interpretação de análises de solo e foliar e monta o plano de adubação da safra. Aceita pagamento via Pix, transferência ou parcelado até a colheita. Prioriza atendimento a propriedades familiares. Especialidades: manejo de pragas e doenças, implantação de lavouras, nutrição do cafeeiro, recomendação de adubação. Atende toda a região Sul de Minas (Varginha, Três Pontas, Guaxupé, Machado, Alfenas, Boa Esperança, Campos Gerais, Carmo de Minas, São Sebastião do Paraíso, Nepomuceno, Poços de Caldas, Nova Resende, Muzambinho, Cabo Verde, Monte Santo de Minas, Três Corações, Elói Mendes, Paraguaçu, Carmo do Rio Claro, Ilicínea, Santana da Vargem, Coqueiral, Cambuquira), num raio de até 80 km da sede. Preço médio: R$ 473,00 por visita técnica. Avaliação média 4,6 de 5 (152 avaliações). Disponibilidade: sob agendamento. Certificações/registros: Pós-graduação em cafeicultura, Credenciado ATER, CREA ativo.','manejo de pragas e doenças, implantação de lavouras, nutrição do cafeeiro, recomendação de adubação',4.6,152,473.0,'visita técnica','Boa Esperança','MG','Sul de Minas','regional','Varginha, Três Pontas, Guaxupé, Machado, Alfenas, Boa Esperança, Campos Gerais, Carmo de Minas, São Sebastião do Paraíso, Nepomuceno, Poços de Caldas, Nova Resende, Muzambinho, Cabo Verde, Monte Santo de Minas, Três Corações, Elói Mendes, Paraguaçu, Carmo do Rio Claro, Ilicínea, Santana da Vargem, Coqueiral, Cambuquira',80,28,'Pós-graduação em cafeicultura, Credenciado ATER, CREA ativo','sob agendamento','(35) 98571-6753',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(1423,'produto','Colheita e armazenagem (materiais)','Embalagens herméticas para café','Ipê Amarelo Embalagens','empresa','Ipê Amarelo Embalagens é uma empresa sediada em Piatã/BA, na região Chapada Diamantina, no mercado há 45 anos. Segmento: Embalagens herméticas para café. Vende sacos herméticos que preservam a qualidade de cafés especiais. Atende produtores que exportam microlotes. Atende de pequenos produtores a grandes fazendas. Atende muitos produtores de cafés especiais da região. Especialidades: preservação de cafés especiais, sacos herméticos multicamada, embalagem para exportação. Atende e envia para todo o Brasil. Preço médio: R$ 35,39 por unidade. Avaliação média 4,9 de 5 (121 avaliações). Disponibilidade: sob encomenda.','preservação de cafés especiais, sacos herméticos multicamada, embalagem para exportação',4.9,121,35.39,'unidade','Piatã','BA','Chapada Diamantina','nacional','Todo o Brasil',NULL,45,NULL,'sob encomenda','(75) 98969-8399',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(1424,'servico','Colheita','Colhedor manual','Juliana Figueiredo','pessoa_fisica','Juliana Figueiredo atua como colhedor de café em Jaguaré/ES, na região Norte do Espírito Santo, com 3 anos de experiência. Faz catação e varrição do café do chão após a colheita. Trabalha na derriça no pano e na colheita seletiva de cereja madura. Segue as boas práticas exigidas por certificadoras. Atende pequenos, médios e grandes produtores. Tem experiência com café conilon/robusta. Especialidades: catação, colheita seletiva, colheita em montanha, derriça no pano. Atende produtores em Jaguaré, Sooretama, num raio de até 30 km. Preço médio: R$ 32,19 por medida de 60 L. Avaliação média 4,4 de 5 (38 avaliações). Disponibilidade: imediata.','catação, colheita seletiva, colheita em montanha, derriça no pano',4.4,38,32.19,'medida de 60 L','Jaguaré','ES','Norte do Espírito Santo','local','Jaguaré, Sooretama',30,3,NULL,'imediata','(27) 98215-3736',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(1425,'servico','Pós-colheita e processamento','Operador de lavador e despolpador','Maria Costa','pessoa_fisica','Maria Costa atua como operador de lavador e despolpador em Elói Mendes/MG, na região Sul de Minas, com 3 anos de experiência. Opera o lavador para separar o café boia do cereja e verde. Acompanha processos de fermentação controlada. Especialidades: cereja descascado, fermentação controlada, despolpamento. Atende produtores em Elói Mendes, São Sebastião do Paraíso, Monte Santo de Minas, num raio de até 60 km. Preço médio: R$ 184,00 por diária. Avaliação média 4,8 de 5 (19 avaliações). Disponibilidade: sob agendamento. Certificações/registros: NR-31.','cereja descascado, fermentação controlada, despolpamento',4.8,19,184.0,'diária','Elói Mendes','MG','Sul de Minas','local','Elói Mendes, São Sebastião do Paraíso, Monte Santo de Minas',60,3,'NR-31','sob agendamento','(35) 98992-4065',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(1426,'produto','Tecnologia e comercialização','Software de gestão rural','Santa Clara Agro Software','empresa','Santa Clara Agro Software é uma empresa sediada em Luís Eduardo Magalhães/BA, na região Oeste da Bahia, no mercado há 39 anos. Segmento: Software de gestão rural. Gera relatórios de custo por saca. Tem aplicativo para registro de atividades no campo. Mantém estoque o ano todo. Emite nota fiscal e entrega na propriedade. Especialidades: gestão financeira, rastreabilidade. Atende e envia para todo o Brasil. Preço médio: R$ 495,00 por mês. Avaliação média 4,5 de 5 (379 avaliações). Disponibilidade: sob encomenda.','gestão financeira, rastreabilidade',4.5,379,495.0,'mês','Luís Eduardo Magalhães','BA','Oeste da Bahia','nacional','Todo o Brasil',NULL,39,NULL,'sob encomenda','(77) 98899-7119',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(1427,'produto','Mudas e sementes','Viveiro de mudas de café','Junqueira Mudas de Café','empresa','Junqueira Mudas de Café é uma empresa sediada em Alfenas/MG, na região Sul de Minas, no mercado há 41 anos. Segmento: Viveiro de mudas de café. Produz mudas de café em tubete e saquinho com registro no RENASEM. Trabalha com cultivares resistentes à ferrugem. Dá desconto em compras de volume e para cooperados. Especialidades: Catuaí Vermelho, Arara, Catuaí Amarelo, Catucaí. Atende toda a região Sul de Minas (Varginha, Três Pontas, Guaxupé, Machado, Alfenas, Boa Esperança, Campos Gerais, Carmo de Minas, São Sebastião do Paraíso, Nepomuceno, Poços de Caldas, Nova Resende, Muzambinho, Cabo Verde, Monte Santo de Minas, Três Corações, Elói Mendes, Paraguaçu, Carmo do Rio Claro, Ilicínea, Santana da Vargem, Coqueiral, Cambuquira), num raio de até 120 km da sede. Preço médio: R$ 2,24 por muda. Avaliação média 4,7 de 5 (87 avaliações). Disponibilidade: sob encomenda. Certificações/registros: Registro RENASEM.','Catuaí Vermelho, Arara, Catuaí Amarelo, Catucaí',4.7,87,2.24,'muda','Alfenas','MG','Sul de Minas','regional','Varginha, Três Pontas, Guaxupé, Machado, Alfenas, Boa Esperança, Campos Gerais, Carmo de Minas, São Sebastião do Paraíso, Nepomuceno, Poços de Caldas, Nova Resende, Muzambinho, Cabo Verde, Monte Santo de Minas, Três Corações, Elói Mendes, Paraguaçu, Carmo do Rio Claro, Ilicínea, Santana da Vargem, Coqueiral, Cambuquira',120,41,'Registro RENASEM','sob encomenda','(35) 98466-8725',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(1428,'servico','Planejamento e implantação da lavoura','Engenheiro agrônomo','Rocha Consultoria Agronômica','empresa','Rocha Consultoria Agronômica é uma empresa sediada em Itumirim/MG, na região Campo das Vertentes, no mercado há 20 anos. Segmento: Engenheiro agrônomo. Orienta a escolha de cultivares, espaçamento e densidade de plantio. Ajuda a planejar a renovação de talhões improdutivos com análise de custo. Tem referências de produtores da região. Especialidades: cafés especiais, recomendação de adubação, renovação de lavouras, nutrição do cafeeiro. Atende toda a região Campo das Vertentes (Lavras, Perdões, Bom Sucesso, Ijaci, Santo Antônio do Amparo, Itumirim, Ingaí), num raio de até 120 km da sede. Preço médio: R$ 706,00 por visita técnica. Avaliação média 4,9 de 5 (46 avaliações). Disponibilidade: imediata. Certificações/registros: CREA ativo.','cafés especiais, recomendação de adubação, renovação de lavouras, nutrição do cafeeiro',4.9,46,706.0,'visita técnica','Itumirim','MG','Campo das Vertentes','regional','Lavras, Perdões, Bom Sucesso, Ijaci, Santo Antônio do Amparo, Itumirim, Ingaí',120,20,'CREA ativo','imediata','(35) 99218-5728',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(1429,'servico','Planejamento e implantação da lavoura','Técnico agrícola','Adilson Martins Lima','pessoa_fisica','Adilson Martins Lima atua como técnico agrícola em lavouras de café em Abaíra/BA, na região Chapada Diamantina, com 19 anos de experiência. Ajuda na regulagem de equipamentos de aplicação e calibração de adubadeiras. Monitora pragas como bicho-mineiro e broca e repassa relatórios ao produtor. Faz orçamento sem compromisso na propriedade. Especialidades: acompanhamento de lavoura, controle de estoque de insumos, coleta de amostras de solo. Atende produtores em Abaíra, Piatã, num raio de até 30 km. Preço médio: R$ 250,00 por visita técnica. Avaliação média 4,9 de 5 (7 avaliações). Disponibilidade: imediata. Certificações/registros: Registro CFTA.','acompanhamento de lavoura, controle de estoque de insumos, coleta de amostras de solo',4.9,7,250.0,'visita técnica','Abaíra','BA','Chapada Diamantina','local','Abaíra, Piatã',30,19,'Registro CFTA','imediata','(75) 99519-1693',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(1430,'produto','Pós-colheita e beneficiamento (equipamentos)','Lavadores e despolpadores','Cafeeiro Máquinas Pós-Colheita','empresa','Cafeeiro Máquinas Pós-Colheita é uma empresa sediada em Varginha/MG, na região Sul de Minas, no mercado há 2 anos. Segmento: Lavadores e despolpadores. Tem tanques para fermentação controlada. Vende lavadores e descascadores para produção de cereja descascado. Emite nota fiscal e entrega na propriedade. Parcela no cartão ou aceita pagamento na safra. Especialidades: despolpador, descascador de cereja. Atende e envia para todo o Brasil. Preço médio: R$ 115.000,00 por unidade. Avaliação média 4,6 de 5 (303 avaliações). Disponibilidade: pronta entrega.','despolpador, descascador de cereja',4.6,303,115000.0,'unidade','Varginha','MG','Sul de Minas','nacional','Todo o Brasil',NULL,2,NULL,'pronta entrega','(35) 98813-9926',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(1431,'servico','Máquinas, estrutura e manutenção','Construtor de terreiros e tulhas','Tatiane Pimenta Barbosa','pessoa_fisica','Tatiane Pimenta Barbosa atua como pedreiro especializado em estruturas rurais em Carlópolis/PR, na região Norte Pioneiro do Paraná, com 21 anos de experiência. Monta terreiros suspensos para cafés especiais. Executa tulhas e galpões para armazenagem. Atende pequenos, médios e grandes produtores. Aceita pagamento via Pix, transferência ou parcelado até a colheita. Especialidades: galpões, barracões. Atende produtores em Carlópolis, Jacarezinho, num raio de até 20 km. Preço médio: R$ 77,00 por m². Avaliação média 3,0 de 5 (21 avaliações). Disponibilidade: imediata.','galpões, barracões',3.0,21,77.0,'m²','Carlópolis','PR','Norte Pioneiro do Paraná','local','Carlópolis, Jacarezinho',20,21,NULL,'imediata','(43) 99213-1805',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(1432,'servico','Manejo e tratos culturais','Consultor em manejo de pragas e doenças','Rafael Rodrigues Pimenta','pessoa_fisica','Rafael Rodrigues Pimenta atua como consultor em manejo integrado de pragas em Ibicoara/BA, na região Chapada Diamantina, com 5 anos de experiência. Implanta programas de manejo integrado de pragas (MIP) com uso de controle biológico. Faz monitoramento de bicho-mineiro, broca e ferrugem e define o momento certo de aplicar. Atende pequenos, médios e grandes produtores. Especialidades: controle biológico, cercosporiose. Atende toda a região Chapada Diamantina (Piatã, Mucugê, Ibicoara, Barra da Estiva, Abaíra, Ituaçu), num raio de até 100 km da sede. Preço médio: R$ 505,00 por visita técnica. Avaliação média 2,4 de 5 (19 avaliações). Disponibilidade: imediata.','controle biológico, cercosporiose',2.4,19,505.0,'visita técnica','Ibicoara','BA','Chapada Diamantina','regional','Piatã, Mucugê, Ibicoara, Barra da Estiva, Abaíra, Ituaçu',100,5,NULL,'imediata','(75) 98617-1168',1,'2026-09-24 20:42:33');
