INSERT INTO "fornecedores" VALUES(1460,'produto','Máquinas e implementos','Revenda de pulverizadores','Brandão Agrícola','empresa','Brandão Agrícola é uma empresa sediada em Carmo do Paranaíba/MG, na região Cerrado Mineiro, no mercado há 7 anos. Segmento: Revenda de pulverizadores. Vende pulverizadores costais e turbo-atomizadores para café. Tem bicos e peças de reposição. Especialidades: bicos e peças, turbo-atomizador. Atende toda a região Cerrado Mineiro (Patrocínio, Araguari, Monte Carmelo, Patos de Minas, Carmo do Paranaíba, Serra do Salitre, Campos Altos, Coromandel, Rio Paranaíba, Ibiá, Perdizes, Estrela do Sul, São Gotardo), num raio de até 100 km da sede. Preço médio: R$ 16.000,00 por unidade. Avaliação média 3,9 de 5 (276 avaliações). Disponibilidade: pronta entrega.','bicos e peças, turbo-atomizador',3.9,276,16000.0,'unidade','Carmo do Paranaíba','MG','Cerrado Mineiro','regional','Patrocínio, Araguari, Monte Carmelo, Patos de Minas, Carmo do Paranaíba, Serra do Salitre, Campos Altos, Coromandel, Rio Paranaíba, Ibiá, Perdizes, Estrela do Sul, São Gotardo',100,7,NULL,'pronta entrega','(34) 99747-5965',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(1461,'produto','Máquinas e implementos','Revenda de colhedoras de café','Souza Máquinas para Café','empresa','Souza Máquinas para Café é uma empresa sediada em Espera Feliz/MG, na região Matas de Minas, no mercado há 10 anos. Segmento: Revenda de colhedoras de café. Tem equipe de pós-venda e treinamento de operador. Vende colhedoras automotrizes e tracionadas para café. Especialidades: colhedoras seminovas, colhedora tracionada, colhedora automotriz, recolhedora. Atende toda a região Matas de Minas (Manhuaçu, Viçosa, Caratinga, Espera Feliz, Simonésia, Manhumirim, Carangola, Alto Jequitibá, Lajinha, Luisburgo), num raio de até 80 km da sede. Preço médio: R$ 1.282.000,00 por unidade. Avaliação média 4,7 de 5 (77 avaliações). Disponibilidade: pronta entrega.','colhedoras seminovas, colhedora tracionada, colhedora automotriz, recolhedora',4.7,77,1282000.0,'unidade','Espera Feliz','MG','Matas de Minas','regional','Manhuaçu, Viçosa, Caratinga, Espera Feliz, Simonésia, Manhumirim, Carangola, Alto Jequitibá, Lajinha, Luisburgo',80,10,NULL,'pronta entrega','(33) 98178-7672',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(1462,'servico','Colheita','Empreiteiro de mão de obra rural','Carvalho Serviços Rurais','empresa','Carvalho Serviços Rurais é uma empresa sediada em Altinópolis/SP, na região Mogiana, no mercado há 21 anos. Segmento: Empreiteiro de mão de obra rural. Atende pedidos de turmas grandes no pico da safra. Organiza as equipes e o controle de produção por medida colhida. Prioriza atendimento a propriedades familiares. Especialidades: alojamento e transporte, turma de colheita, mão de obra registrada, turma de poda. Atende toda a região Mogiana (Franca, Pedregulho, Cristais Paulista, Altinópolis, Espírito Santo do Pinhal, Caconde, Ribeirão Corrente, Jeriquara, Patrocínio Paulista, Itirapuã, São Sebastião da Grama, Mococa), num raio de até 80 km da sede. Preço médio: R$ 164,00 por diária por trabalhador. Avaliação média 4,6 de 5 (186 avaliações). Disponibilidade: sob agendamento.','alojamento e transporte, turma de colheita, mão de obra registrada, turma de poda',4.6,186,164.0,'diária por trabalhador','Altinópolis','SP','Mogiana','regional','Franca, Pedregulho, Cristais Paulista, Altinópolis, Espírito Santo do Pinhal, Caconde, Ribeirão Corrente, Jeriquara, Patrocínio Paulista, Itirapuã, São Sebastião da Grama, Mococa',80,21,NULL,'sob agendamento','(16) 99388-9711',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(1463,'servico','Qualidade e comercialização','Consultor de cafés especiais','Thiago Andrade','pessoa_fisica','Thiago Andrade atua como consultor de cafés especiais em Poços de Caldas/MG, na região Sul de Minas, com 29 anos de experiência. Implanta processos de fermentação controlada e anaeróbica para elevar a pontuação. Ajuda a acessar compradores e concursos de cafés especiais. Prioriza atendimento a propriedades familiares. Especialidades: acesso a mercado de especiais, rastreabilidade. Atende e envia para todo o Brasil. Preço médio: R$ 662,00 por visita técnica. Avaliação média 3,7 de 5 (39 avaliações). Disponibilidade: imediata. Certificações/registros: Q-Arabica Grader (CQI), Barista certificado SCA.','acesso a mercado de especiais, rastreabilidade',3.7,39,662.0,'visita técnica','Poços de Caldas','MG','Sul de Minas','nacional','Todo o Brasil',NULL,29,'Q-Arabica Grader (CQI), Barista certificado SCA','imediata','(35) 99894-9776',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(1464,'servico','Manejo e tratos culturais','Aplicador de defensivos','Raiz Forte Aplicações Agrícolas','empresa','Raiz Forte Aplicações Agrícolas é uma empresa sediada em Joaquim Távora/PR, na região Norte Pioneiro do Paraná, no mercado há 3 anos. Segmento: Aplicador de defensivos. Trabalha com EPI completo e respeita intervalo de reentrada e carência. Possui equipamento próprio calibrado para aplicações de fungicida e inseticida. Atende pequenos, médios e grandes produtores. Especialidades: pulverização com turbo-atomizador, aplicação costal, controle de ferrugem, aplicação de herbicida. Atende toda a região Norte Pioneiro do Paraná (Pinhalão, Carlópolis, Tomazina, Ibaiti, Jacarezinho, Ribeirão Claro, Japira, Joaquim Távora), num raio de até 200 km da sede. Preço médio: R$ 97,00 por hectare. Avaliação média 4,5 de 5 (158 avaliações). Disponibilidade: sob agendamento. Certificações/registros: Curso de aplicação segura de agrotóxicos.','pulverização com turbo-atomizador, aplicação costal, controle de ferrugem, aplicação de herbicida',4.5,158,97.0,'hectare','Joaquim Távora','PR','Norte Pioneiro do Paraná','regional','Pinhalão, Carlópolis, Tomazina, Ibaiti, Jacarezinho, Ribeirão Claro, Japira, Joaquim Távora',200,3,'Curso de aplicação segura de agrotóxicos','sob agendamento','(43) 99065-9587',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(1465,'servico','Máquinas, estrutura e manutenção','Eletricista rural','Cláudia Gomes','pessoa_fisica','Cláudia Gomes atua como eletricista rural em Ibaiti/PR, na região Norte Pioneiro do Paraná, com 14 anos de experiência. Faz instalações elétricas em tulhas, secadores e bombas de irrigação. Faz manutenção preventiva antes da safra. Emite nota fiscal e formaliza o serviço em contrato. Atende pequenos, médios e grandes produtores. Especialidades: instalação de secadores, quadros de comando. Atende produtores em Ibaiti, Ribeirão Claro, num raio de até 20 km. Preço médio: R$ 113,00 por hora. Avaliação média 4,8 de 5 (23 avaliações). Disponibilidade: agenda cheia até o fim da safra.','instalação de secadores, quadros de comando',4.8,23,113.0,'hora','Ibaiti','PR','Norte Pioneiro do Paraná','local','Ibaiti, Ribeirão Claro',20,14,NULL,'agenda cheia até o fim da safra','(43) 98195-8564',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(1466,'produto','Máquinas e implementos','Derriçadeiras e roçadeiras portáteis','Pimenta Equipamentos Agrícolas','empresa','Pimenta Equipamentos Agrícolas é uma empresa sediada em Luís Eduardo Magalhães/BA, na região Oeste da Bahia, no mercado há 35 anos. Segmento: Derriçadeiras e roçadeiras portáteis. Faz revisão pré-safra das máquinas. Tem assistência técnica e peças de reposição na loja. Atende de pequenos produtores a grandes fazendas. Mantém estoque o ano todo. Especialidades: derriçadeira a gasolina, assistência técnica, roçadeira. Atende toda a região Oeste da Bahia (Luís Eduardo Magalhães, Barreiras, São Desidério), num raio de até 120 km da sede. Preço médio: R$ 4.110,00 por unidade. Avaliação média 4,4 de 5 (111 avaliações). Disponibilidade: pronta entrega.','derriçadeira a gasolina, assistência técnica, roçadeira',4.4,111,4110.0,'unidade','Luís Eduardo Magalhães','BA','Oeste da Bahia','regional','Luís Eduardo Magalhães, Barreiras, São Desidério',120,35,NULL,'pronta entrega','(77) 98134-8806',1,'2026-09-24 20:42:33');
