INSERT INTO "fornecedores" VALUES(1468,'servico','Máquinas, estrutura e manutenção','Mecânico de máquinas agrícolas','Cafeeiro Mecânica Rural','empresa','Cafeeiro Mecânica Rural é uma empresa sediada em Piatã/BA, na região Chapada Diamantina, no mercado há 27 anos. Segmento: Mecânico de máquinas agrícolas. Atende emergências durante a safra. Faz manutenção de tratores e implementos com atendimento na propriedade. Segue as boas práticas exigidas por certificadoras. Especialidades: colhedoras, pulverizadores, sistema hidráulico. Atende produtores em Piatã, Ibicoara, Abaíra, Ituaçu, num raio de até 40 km. Preço médio: R$ 103,00 por hora. Avaliação média 3,6 de 5 (310 avaliações). Disponibilidade: sob agendamento.','colhedoras, pulverizadores, sistema hidráulico',3.6,310,103.0,'hora','Piatã','BA','Chapada Diamantina','local','Piatã, Ibicoara, Abaíra, Ituaçu',40,27,NULL,'sob agendamento','(75) 98302-2764',1,'2026-09-24 20:42:33');
INSERT INTO "fornecedores" VALUES(1469,'servico','Colheita','Operador de derriçadeira','Rodrigo Figueiredo','pessoa_fisica','Rodrigo Figueiredo atua como operador de derriçadeira portátil em Jaguaré/ES, na região Norte do Espírito Santo, com 31 anos de experiência. Trabalha junto com a turma no pano para acelerar a colheita. Faz pequenas manutenções na máquina durante a safra. Tem referências de produtores da região. Tem experiência com café conilon/robusta. Especialidades: manutenção de derriçadeira, colheita semimecanizada, derriçadeira portátil. Atende produtores em Jaguaré, Rio Bananal, num raio de até 30 km. Preço médio: R$ 193,00 por diária. Avaliação média 4,9 de 5 (34 avaliações). Disponibilidade: imediata. Certificações/registros: NR-31.','manutenção de derriçadeira, colheita semimecanizada, derriçadeira portátil',4.9,34,193.0,'diária','Jaguaré','ES','Norte do Espírito Santo','local','Jaguaré, Rio Bananal',30,31,'NR-31','imediata','(27) 98007-4654',1,'2026-09-24 20:42:33');
